/** Prosa autoral por seção; uma chave só entra quando supera o piso editorial. */
export const PHP_AUTHORED_PROSE: Record<string, string[]> = {
  "Versão, SAPI e configuração": [
    "## Versão, SAPI e configuração\nPHP não é apenas uma versão da linguagem: CLI, FPM, Apache module e outros SAPIs carregam ini files, environment, extensions, users, paths e lifecycles distintos. O baseline registra `PHP_VERSION`, `PHP_SAPI`, binary, loaded ini, scanned ini, extensions e configurações críticas no gate, sem expor secrets. O mutante executa examples no CLI e afirma equivalência com FPM. Teste de produção consulta uma rota/health segura e um command pelo artifact, comparando matriz deliberada. `php --ini` não prova FPM. Version constraint no Composer declara suporte, mas runtime efetivo ainda é verificado. Um patch/minor pode mudar deprecations e defaults. A documentação fixa baseline somente quando executor existe; neste host, ausência do binário mantém snippets como drafts.",
    "### php.ini e precedência\nConfiguração pode vir de ini principal, scan dir, SAPI/pool, `.user.ini`, flags CLI e calls `ini_set` para directives mutáveis. O baseline centraliza valores obrigatórios — timezone, memory/upload/post limits, error display/logging, sessions, opcache — e falha quando combinação insegura. O mutante corrige configuração em runtime sem perceber que directive é PHP_INI_SYSTEM ou que FPM usa outro arquivo. Gate imprime apenas names/values não secretos e compara CLI/FPM conforme objetivo. `display_errors` fica off em produção; `error_reporting` continua amplo e logger redige. `variables_order`, request parsing e `max_input_vars` alteram boundary. Config change recebe artifact/config version, rollout e rollback, não edição manual sem trilha.",
    "### Extensões e capacidades\nFunções e tipos podem depender de mbstring, intl, PDO driver, openssl, curl, json, sodium, pcntl ou opcache. O baseline declara `ext-*` no Composer quando requerido e executa capability smoke. O mutante usa `function_exists` para cair em algoritmo fraco ou comportamento diferente silenciosamente. Ausência de intl/normalizer, driver ou CA bundle deve bloquear feature/boot conforme risco. Extensão nativa depende de ABI, OS libs e architecture; image/SBOM registra. Gate testa operação mínima, não apenas `extension_loaded`: abrir PDO no banco, validar TLS no sandbox, normalizar Unicode. Extensões opcionais têm fallback semanticamente equivalente e testado, ou são removidas. Atualização roda corpus/smoke. Não instalar extensões apenas para escrever documentação.",
    "### CLI versus FPM\nCLI costuma ser processo curto; FPM mantém worker vivo por requests, reaproveitando statics/globals/opcache/connections. `max_execution_time`, working directory, environment e output diferem. O baseline trata command/job e HTTP como entrypoints separados que compartilham composition root, sem compartilhar state de request. O mutante guarda tenant em static e próximo request do mesmo worker herda. Tests fazem alpha→exception→beta no mesmo worker quando harness permite. FPM pool user, chroot/chdir, env clearing, request limits e graceful reload são gates. CLI worker de fila também é long-lived e precisa reset. Signals/pcntl podem não existir em todo SAPI/OS. Web request não shell-executa CLI por conveniência. Logs identificam SAPI/process/artifact.",
    "### Errors, warnings e deprecations\nPHP pode emitir warning/notice/deprecation e continuar, lançar `Error`, ou retornar false conforme API. O baseline habilita reporting máximo em test, converte categorias esperadas de boundaries conscientemente e falha build em novas deprecations com plano. O mutante usa `@` suppression ou configura error_reporting baixo, escondendo undefined key/encoding/file error. Tests provocam failure e exigem outcome/log redigido, sem output contaminando JSON/headers. Custom handler respeita severity/current mask e não transforma fatal/unknown em domain validation. `set_exception_handler` é última borda, não retry. Production error page não mostra stack/path/env. Error logs têm request/event ID. Deprecation de dependency possui owner/version.",
    "### Reproducibilidade e Composer platform\nComposer resolve constraints com a plataforma presente ou configurada; `config.platform` ajuda resolução, mas não muda runtime. O baseline mantém lock, platform PHP/ext constraints e valida `composer check-platform-reqs` no artifact final. O mutante resolve no laptop com extensões extras e imagem falha. `--ignore-platform-reqs` não entra release. Vendor é instalado com lock/frozen e autoload otimizado, sem scripts não revisados. Build limpo duas vezes compara pacote/digest funcional. CLI Composer credential não vai para layer. Rollback usa vendor artifact anterior. Matrix de versões suportadas roda suíte/analysis/snippets. Um lock verde não prova configuração ini/SAPI nem serviço externo.",
    "### Incidente, aceite e fontes\nCLI tinha mbstring e timezone corretos, FPM não; warning virou bytes antes do JSON e lock foi resolvido noutra plataforma. O baseline registra matriz, ini/extensions e artifact. Mutantes precisam falhar em CLI/FPM config, missing capability, long-lived leakage e deprecation. Manual oficial PHP por versão, Composer e SAPI/server docs são fontes. Aceite executa entrypoints reais, boot/smoke e request sequencial, com outputs redigidos. Sem engine, a seção permanece draft. A banca não chama lint de execução nem `composer.json` de plataforma comprovada.",
  ],
  "Tipos escalares e strict_types": [
    "## Tipos escalares e strict_types\n`declare(strict_types=1)` vale por arquivo chamador para coerção de argumentos escalares; não torna superglobals/JSON tipados nem adiciona runtime soundness completo. O baseline coloca declaração nos arquivos da aplicação, mas ainda valida/coage input em boundary explícita. O mutante aceita `$_POST['quantity']` diretamente num método e confia que type hint rejeitará toda ambiguidade. Tests cobrem strings numéricas, whitespace, exponent, bool, null, arrays e overflow lógico. Um DTO command recebe int validado e faixa. Retorno e properties tipadas eliminam estados, mas database/hydrator precisa mapping. Strictness de vendor/caller é entendida. Não use TypeError como mensagem pública sem tradução segura.",
    "### Numeric strings e comparisons\nPHP possui regras de numeric string, casts e comparisons que mudaram entre versões. `intval('3x')`/casts podem aceitar prefixos ou produzir zero; `==` realiza coerção. O baseline usa `filter_var` ou parsing estrito por regex/round-trip/faixa conforme campo e `===` para identidade/tipos. O mutante compara token/hash/status com `==`, historicamente associado a magic hashes e resultados surpreendentes. Corpus inclui `0`, `00`, `0e...`, signs, whitespace, exponent, huge digits, NaN/INF quando float. Money nunca usa float casual; minor units/decimal library. Quantity 1..8. Array keys também coagem strings inteiras. Test fixa versão do runtime porque semântica importa.",
    "### Bool, null e unions\nBoolean input não é simplesmente `(bool)$raw`: qualquer string não vazia exceto `'0'` vira true. O baseline aceita vocabulário fechado ou JSON boolean. Null significa ausência/valor conforme schema e não é false/empty. O mutante usa `empty`, que agrupa `0`, `'0'`, empty string, null e missing. Tests distinguem `array_key_exists` de `isset`. Union types descrevem alternativas, mas union ampla como `string|int|bool|null` pode empurrar ambiguidade ao domínio. Preferir parser que retorna value object/outcome. Nullable property não deve representar pending/error/not-found simultaneamente. `mixed` na boundary é refinado cedo. `never`, `void` e explicit return ajudam control flow/analyzer.",
    "### Integers, floats e limites\nInteger size depende da plataforma, embora servidores modernos normalmente 64-bit; overflow pode virar float ou perder precisão em JSON/client. O baseline define faixa de domínio bem menor e serializa IDs como strings quando necessário. Float IEEE-754 não representa decimal financeiro exatamente; money usa inteiro minor/decimal extension/library com rounding definido. O mutante soma preços float e compara equality. Tests cobrem .1+.2, boundaries, negative, division by zero behavior, JSON big integers e currency scale. NaN/INF não são JSON padrão. `round` mode explícito. SQL numeric maps sem converter a float. Métricas/tempo podem usar float onde erro é aceitável, documentado. Unit suffixes no nome/value object.",
    "### Strings, coercion e Stringable\nString interpolation/cast pode chamar `__toString`, escondendo trabalho ou exception; objects Stringable não são automaticamente safe para HTML/SQL/log. O baseline converte values de domínio em presentation explícita e sinks aplicam encoding/bind. O mutante concatena object/input em query/shell/template. Tests de redaction e exception garantem que secrets não aparecem. Binary token/hash não passa por Unicode functions. IDs têm pattern/length. Empty string e whitespace policy. `sprintf` format é constante, nunca input. Locale não deve mudar canonical serialization. Enums backed transformam conscientemente. `__toString` simples, sem I/O. Logger structured não força dump de model/request. String offset opera bytes.",
    "### Callables, named args e variance\nCallable pode ser closure, array/object method ou string; aceitar callable de input é code execution. O baseline registra handlers em map fechado e interfaces. Named arguments acoplam nome de parâmetro da API pública; libraries precisam tratar rename como breaking. O mutante usa `call_user_func($_GET['action'])`. Closure pode capturar por value/reference; delayed job não retém request mutable. Tests alteram origem após capture. Type variance e LSP em interfaces são respeitados; static analysis complementa. First-class callable de método conhecido preserva refactor melhor. Reflection/attributes só escolhem classes allowlisted. Serialization de closure não é protocolo de queue. Callback exception category/lifecycle documentados.",
    "### Incidente, aceite e fontes\nCast transformou lixo em zero, `empty('0')` apagou valor e equality frouxa autenticou incorretamente. O baseline parsing estrito, identity comparison e values. Mutantes precisam falhar no corpus numeric/bool/null, money rounding e callable input. Manual PHP de types/type juggling/comparisons e analyzer docs são fontes. Aceite executa na versão/platform real e registra behavior. Sem engine, examples drafts. A banca não chama `strict_types` de validação de request nem type hint de autorização.",
  ],
  "Arrays, strings e Unicode": [
    "## Arrays, strings e Unicode\nArray PHP é ordered map: pode agir como list, dictionary, set improvisado ou mixed structure. Essa flexibilidade cria contratos escondidos. O baseline valida shape e usa `array_is_list`, DTOs/collections para domínio e maps com key type explícito. O mutante assume que JSON object/array ou keys numéricas manterão forma após encode/decode. Tests cobrem empty, sparse, integer-like string keys, duplicates do parser, nested depth e mixed keys. `array_merge`, union `+` e spread têm semânticas de keys diferentes. Reindex pode alterar IDs. Membership usa strict flag. Uma list gigantesca é limitada antes de map/sort/group. Static analyzer annotations/generics refine shapes, sem substituir runtime input schema.",
    "### Copy-on-write e references\nAssignments de arrays/strings usam copy-on-write até mutation; references com `&` alteram aliasing e podem deixar bug após foreach. O baseline evita references salvo hot path provado e chama `unset($value)` depois de foreach by-reference. O mutante reutiliza variável referenciada e último elemento muda numa segunda iteração. Tests reproduzem ownership/mutation e delayed closures. Copy-on-write não significa zero memória quando uma cópia é modificada; carga mede. Objects dentro de arrays continuam handles compartilhados. Cloning é shallow salvo implementação. Readonly property com array não pode ser reatribuída, mas nested object pode mutar. Value objects imutáveis reduzem surpresa. Não retenha request body para um ID.",
    "### Strings são bytes\n`strlen`, offsets e substr comuns medem bytes, não caracteres/graphemes. O baseline decide se campo é binary, Unicode code point ou grapheme/display e usa mbstring/intl adequada, após validar encoding e normalizar quando regra permite. O mutante corta UTF-8 no meio ou limita username por bytes sem declarar. Tests incluem acentos compostos/decompostos, emoji ZWJ, flags, combining marks, invalid UTF-8 e RTL. `mb_strlen` não é grapheme count; intl grapheme APIs quando requisito. Security length pode usar bytes para resource budget e code points para domain, ambos. Output encoding. Database charset/collation alinhados. Logs não corrompem JSON com invalid bytes.",
    "### Normalização, case e identidade\nUnicode permite sequências visualmente equivalentes; normalize apenas quando domínio define. O baseline normaliza email/domain/identifier segundo protocolo, preserva display e versiona canonical fingerprint. O mutante aplica strtolower ASCII ou transliteration ampla e colide identidades. `mb_strtolower` ainda não resolve locale/case folding completo em todos casos; database unique collation precisa corresponder. Tests composed/decomposed, Turkish I, German sharp s, homoglyphs e whitespace. Security não depende de aparência. Username policy pode proibir confusables/restringir vocabulário. Idempotency key ASCII opaque não é normalizada arbitrariamente. Hash/fingerprint usa canonical bytes. Upgrade Unicode library pode alterar resultado e requer migration/gate.",
    "### JSON arrays e objects\n`json_decode(..., true)` retorna arrays para objects/lists, e empty object/list distinction pode se perder na aplicação. O baseline valida JSON schema antes/ao mapear e usa `JSON_THROW_ON_ERROR`, depth e bigint policy. O mutante ignora `json_last_error` ou usa associative arrays sem distinguir shape. Tests malformed/truncated/duplicate keys policy, invalid UTF-8, huge numbers, depth/width and empty. `json_encode` flags chosen; partial output on error prohibited. Domain DTO serializer allowlisted. Numeric IDs strings. Object property order not semantic; canonicalization sorts fields intentionally. Response content type. Never unserialize external. JSON body bytes limited before decode.",
    "### Collection algorithms e complexity\nConvenient `array_map/filter/reduce`, sort and group can allocate full copies and consume CPU/memory. O baseline budgets item count, uses generator/stream/batches and stable comparator. O mutante groups attacker-sized input or comparator inconsistent, causing high cost/wrong order. Tests complexity with boundary/one over, duplicate/equality and locale sorting. Comparator returns int contract and no overflow trick. `in_array` strict; maps for lookup. Sorting may reset keys depending function. Generator single-use/lifetime of resource. DB should filter/paginate before PHP for large data. Load measures RSS/GC. Failed partial processing cleans temp/state. Avoid dynamic symbol/interned unbounded keys where relevant.",
    "### Incidente, aceite e fontes\nNumeric string key changed shape, foreach reference corrupted last row and byte substring broke UTF-8. O baseline validates collection/encoding/ownership. Mutants fail sparse/mixed keys, reference lifecycle, Unicode corpus, JSON shape and size load. PHP array/string/json/mbstring/intl docs are sources. Aceite executes extensions/runtime actual and measures memory. Without them examples draft. A banca doesn't call mbstring full Unicode correctness nor small fixture proof of bounded collections.",
  ],
  "Controle, match e funções": [
    "## Controle, match e funções\nControl flow carries domain outcomes. `match` uses strict comparison and must cover variants or throw; switch historically uses loose comparison and fall-through risks. O baseline maps every closed enum/outcome explicitly and no default for domain variant where future should fail. O mutante default maps unknown to success. Tests create known and future/invalid values via boundary and expect refusal. Guard clauses keep happy path readable but cleanup still finally. Loops bounded; break/continue levels avoided or tested. Ternary/coalesce distinguish missing/null carefully. Exceptions do not become branches for ordinary invalid input unless contract. Analyzer checks exhaustive enum when possible.",
    "### Functions and signatures\nFunctions declare parameter/return types, avoid boolean flag soup and expose required options. O baseline uses named value/command or separate methods. O mutante adds optional tenant default/global. Default values evaluated semantics known and not mutable object accidentally. Variadic input bounded. Named arguments mean parameter names API. Passing by reference only when explicit performance/interop, not hidden output. Return result object/enum variant instead of false/null/array shape ambiguous. Pure helpers separate from I/O. Function scope avoids globals/superglobals. Tests call public contract. Static closure doesn't capture `$this` accidentally. Recursion has depth/iterative choice.",
    "### Closures and capture\nClosure captures variables by value by default, by reference with `&`, and objects as handles. O baseline captures immutable IDs/values for delayed callback and injects dependencies; never full request/tenant mutable context. O mutante closure queued for later reads changed reference or retains huge body. Test pauses executor, mutates origin, asserts copied command. Binding/rebinding can access private state and is restricted. Arrow functions capture by value automatically but object mutation remains. Weak references not lifecycle substitute. Callback unregister/cancel to prevent leaks. Serialization of closures not queue contract. Error/cancellation owner. Trace context safe subset, not auth.",
    "### Generators and iteration\nGenerators stream values and suspend execution with local state/resources. O baseline owner consumes/closes within resource lifetime or generator itself uses try/finally; no transaction/handle escapes unknowingly. O mutante returns generator from within transaction/file closure then consumer iterates later. Tests partial iteration, exception and early break, verifying handle/connection release. Generator is single-pass. `yield from` propagates keys/return with semantics. Batching large DB uses cursor/pagination and deadlines. Cannot rewind started generator generally. Backpressure prevents producer running far ahead. Captured context/tenant stable. Cleanup after process kill requires durable checkpoints, not finally.",
    "### Attributes/reflection registries\nAttributes can declare handlers/routes/serialization metadata, but discovery scans known namespaces/classes at boot and validates duplicates. O baseline builds immutable registry, caches per artifact and only instantiates implementations satisfying interface. O mutante uses class string from request or scans writable upload dirs. Tests duplicate/missing/invalid and production authoritative classmap. Reflection not in hot path unnecessarily. Attribute constructor no I/O. Order explicit. Cache invalidated by artifact. Security review treats metadata as code. Container resolves dependencies. Unknown command/type fails closed. Plugin packages provenance/allowlist. Error doesn't expose paths/classes excessively.",
    "### Recursion, callbacks and limits\nParsers/tree walkers/callback chains can recurse or cycle. O baseline depth/visited limits and iterative traversal where needed. O mutante recursive merge on nested attacker input exhausts stack/memory. Corpus depth/cycles (objects) and broad fanout. `array_walk_recursive` limitations understood. Event/listener recursion prevented by event IDs/depth. Signal/exception handler doesn't recurse logging failure. Shutdown function not reliable transaction recovery. Execution/time limits vary SAPI and blocking extension, so app deadlines/resource controls remain. Callback list bounded and errors categorized. A handler cannot silently swallow future outcome.",
    "### Incidente, aceite e fontes\nSwitch loose/fallthrough confirmed unknown, closure captured request and generator held DB transaction. O baseline exhaustive match, owned values and lifecycle. Mutants fail future variant, delayed mutation, partial iteration and recursion corpus. PHP control/functions/generators/reflection docs are sources. Aceite executes runtime/static analyzer and resource readback. Without engine examples draft. A banca doesn't call syntax parse exhaustive behavior or finally guarantee under process kill.",
  ],
  "Classes, readonly e invariantes": [
    "## Classes, readonly e invariantes\nUma classe de domínio deve impedir instâncias inválidas, não depender de callers lembrarem uma sequência de setters. O baseline usa constructor privado/named factory ou constructor público que valida todos os argumentos antes de publicar `this`. Constructor property promotion reduz ruído, mas não substitui regra. O mutante atribui propriedades uma a uma e lança depois, enquanto callback/registry recebe referência parcial. PHP não deixa `this` escapar automaticamente, porém chamadas feitas dentro do constructor podem. Tests tentam boundaries, invalid, reflection/unserialize paths conforme risco e garantem que factory não retorna parcialmente. Model hidratado do banco também valida ou usa caminho interno estreito. Exceptions carregam code seguro. Invariante vive além do formulário.",
    "### Readonly e imutabilidade\nReadonly impede reatribuição depois da inicialização conforme regras da versão; não congela objeto referenciado nem torna collection profundamente imutável. O baseline usa scalars, enums, DateTimeImmutable e value objects próprios, copiando arrays na construção e sem getters que exponham mutable collaborator. O mutante coloca DateTime mutável/ArrayObject em readonly e caller altera estado. Tests guardam referência original e tentam mutation posterior. Clone e serialization têm semântica/version constraints. Entidade com lifecycle pode ser mutable internamente por métodos de transição, enquanto values permanecem readonly. Não use readonly como substitute de tenant authorization. Static analysis encontra writes, runtime gate confirma versão. Lazy initialization em readonly é revisada. Cache de computed value precisa desenho compatível.",
    "### Visibilidade e encapsulamento\nPublic API pequena: properties privadas/read-only, getters de values e methods com intenção como `confirm`. Public setter de status/tenant/capacity quebra state machine. O baseline usa private/protected conscientemente e final onde extensão violaria invariante. O mutante subclass override remove policy ou reflection hydrator escreve private sem validação. Tests só pela API pública, mais mutation que tenta transição proibida. Protected ainda amplia superfície para subclasses. Magic `__get/__set/__call` esconde typo e analyzer; evite no domínio. Serialization frameworks recebem mapper dedicado. Debug info não inclui secret. `get_object_vars` muda conforme scope e não é contrato. Encapsulation não impede banco inválido; constraints complementam.",
    "### Construção e dependências\nEntidade não busca container, globals, ENV, current request ou database no constructor. O baseline passa values necessários e service injeta clock/ID/policies. O mutante model chama `Container::get` ou gera novo event ID a cada retry, dificultando determinismo. Tests usam fixed clock/ID sem mock de internals. Dependency object tem lifetime/interface e não fica em DTO serializado. Named arguments tornam call legível, mas nomes públicos estáveis. Constructor com dez flags sugere config/value split. Optional dependency não vira null check espalhado: use Null Object somente se semântica legítima. Factory externaliza I/O. Reconstitution do repository separada de creation para evitar eventos duplicados.",
    "### Invariantes e transições\n`Reservation` nasce Pending com tenant/show/quantity/key/event/fingerprint válidos; `confirm`, `cancel`, `markUnknown` verificam source state, actor/reason e produzem event/outcome. O baseline não expõe status assignment. O mutante `setStatus(string)` permite pending→sent sem receipt. Tests matriz de estados, replay e future value; unknown fails closed. Transition repetida pode ser idempotent ou conflict documentado. Timestamp/actor/event version atualizados juntos no service/transaction. Value equality. Exceptions de programmer versus outcome de business. Database conditional update/lock evita stale concurrent object. Domain event é immutable data, não callback que envia. Compensation cria nova transição.",
    "### Serialization e hydration\n`__serialize/__unserialize`, Reflection e ORM hydration podem contornar constructor. O baseline evita native serialization externo, valida schema/version e usa explicit mapper que constrói/reconstitui estado autorizado. O mutante unserializa input com allowed_classes true ou reflection seta qualquer property. Tests corrupted/missing/future fields and legacy supported. Object graph cycles/resources/closures not durable. JSON presenter allowlisted independent. Repository verifies row constraints/status. Read model separado pode ser plain DTO sem entity behavior. Cache serialized value versioned. Secrets omitted. PHP version/class rename compatibility. Unserialization hooks are code execution surface. Queue payload IDs/primitives, not entity blob.",
    "### Incidente, aceite e fontes\nObjeto parcial escapou, readonly conteve collaborator mutável e setter pulou lifecycle. O baseline atomic construction, deep-enough values and methods of intent. Mutants fail reference mutation, transition matrix, reflection/unserialize corpus. PHP OOP/readonly/serialization docs and analyzer are sources. Aceite executes runtime version and storage mapping. Sem engine, examples draft. Banca doesn't call readonly deep immutability nor validation-only durable constraint.",
  ],
  "Enums, value objects e igualdade": [
    "## Enums, value objects e igualdade\nBacked enum fecha vocabulário e mapping para string/int; `from` lança e `tryFrom` retorna null. O baseline decide boundary behavior e usa `match` exhaustivo. O mutante converte unknown status para default Confirmed ou usa raw strings espalhadas. Tests each case, invalid/future persisted value and serialization. Case names versus backed values are distinct contract. Renaming backing value requires migration/compatibility. Enum pode ter behavior methods but no state. API/schema/database check aligned. `tryFrom` null não mistura not-found/error. Static analyzer catches match gaps where possible. Future event from other version stays explicit Unknown/unsupported, not success.",
    "### Value object identity\nMoney, TenantId, IdempotencyKey, Quantity, Fingerprint and EventId encapsulate parsing/canonical/format. Equality is semantic fields, not PHP object identity `===` (which means same instance for objects). O baseline provides `equals` and canonical string. O mutante compares two equal Money objects with `===` and cache misses, or compares loose `==` including hidden properties unexpectedly. Tests reflexive/symmetric/transitive and unequal tenants/currencies. Hash/map keys require canonical scalar since object cannot straightforward array key. Values immutable. Normalization versioned. No I/O. String representation safe/not secret. Database mapper roundtrip. Validation error bounded.",
    "### Money e quantity\nMoney never binary float; minor units plus currency/scale or decimal library. Quantity strict integer range. O baseline checks overflow on multiply/add and rounding mode at pricing boundary. O mutante `(int)($price*100)` truncates and accepts float. Tests 0.1, half rounding, negative, huge, different currency and scale. JSON money representation explicit string/minor+currency. Database decimal fetched often string, mapped without float. Locale only display/input policy, not canonical. Discounts/tax ordering documented. Equality includes currency. Quantity multiplication cannot exceed capacity/domain. PHP integer platform gate. Analyzer type annotation/refinement.",
    "### Time values\nUse DateTimeImmutable with explicit DateTimeZone/instant; separate Instant, LocalDate/Time and business Zone concepts. O baseline parses strict format checking errors, stores UTC and zone when future civil rule matters. O mutante `new DateTimeImmutable($userString)` accepts surprising relative text/default timezone. Tests invalid, DST gap/overlap, boundary/precision and timezone server difference. Expiration compares instants with injected clock. Duration versus calendar interval distinct. Serialization ISO 8601 with offset/UTC and precision. Database timezone/session known. Equality timestamp+semantics. DateTimeInterface mutable possibilities narrowed. Never use formatted localized string as durable identity.",
    "### IDs, keys e canonical fingerprints\nOpaque IDs/keys are strings with byte/character limits and allowlist; no autoincrement guess as auth. Idempotency key scoped by tenant and fingerprint hashes canonical semantic payload with version. O mutante uses `serialize`/JSON property order or loose equality. Tests whitespace/order equivalence, semantic difference, Unicode policy, decimal/time normalization and cross-tenant same key. Cryptographic hash collision policy, no raw original leak. EventId stable across retries/restores. UUID parser canonical version/variant if required. Key not metric label. Retention/reuse contract. Secret tokens differ: high entropy, digest storage, secure compare and redaction. Value types avoid mixing IDs.",
    "### Collections of values\nArray of scalar/value needs shape, element type, uniqueness/order policy and max count. O baseline exposes immutable-ish collection object with iterator/count and copied internal list, returning values. O mutante accepts mixed array and fails mid-service after partial effect. Constructor validates all first. Equality may be order-sensitive or set-based explicitly. Canonical fingerprint sorts only where order semantically irrelevant. Duplicate handling. Generator input materialized bounded before object publish. Static analyzer generic annotations. JSON mapping. No public reference. Large sets remain DB/page rather than value collection. Tests empty/max/one-over/duplicates/delayed source mutation.",
    "### Incidente, aceite e fontes\nUnknown enum confirmed, float lost cents and identity comparison split equal values. Baseline enums, canonical immutable values and equals. Mutants fail future enum, money/time/Unicode/key corpus and persistence roundtrip. PHP enum/DateTime/number docs, decimal library and analyzer are sources. Aceite runs actual extensions/version. Without engine examples draft. Banca doesn't call enum authorization nor formatted equality canonicalization. O readback confirma os mesmos campos após banco, JSON e fila, sem converter decimal em float ou perder timezone.",
  ],
  "Interfaces, traits e composição": [
    "## Interfaces, traits e composição\nInterface names a capability/contract, not a bag of methods copied from implementation. O baseline defines narrow ReservationRepository, ProviderClient, Clock and EventPublisher with domain values/outcomes. O mutante creates one God interface and fakes implement only happy path. Shared contract tests every adapter. Return types do not leak PDO/framework response. Exceptions/outcomes documented. Interface evolution add method can break implementations; version/segregate. Read/write separated where useful. Consumer owns abstraction. Type variance/LSP. No default null for unsupported. Production composition root selects concrete. Static analysis plus runtime contract.",
    "### Composition over inheritance\nInheritance models substitutability, not code sharing. O baseline composes pricing/policy/provider strategies behind interfaces and makes entity final if invariants. O mutante subclasses Reservation to weaken validation or overrides method without parent side effects. Contract tests pass substitute through consumer. Template Method hooks can still expand unsafe surface. Decorator adds telemetry/retry preserving behavior and order. Strategy names closed/config. Multiple inheritance absent; traits are reuse, not subtype. Composition lifetimes explicit. Container builds graph. No `instanceof` cascade against concrete implementations. Performance measured before merging layers.",
    "### Traits and conflicts\nTrait inserts methods/properties into class; multiple traits may conflict and aliases/change visibility. O baseline limits stateless mechanical behavior and keeps security/domain policy in collaborators. O mutante Auth trait reads global current user or overrides method order silently. Tests consuming classes, not trait alone, include conflict/initialization. Trait properties can collide across versions. `insteadof/as` explicit but signals design review. Private trait methods become class internals and can conflict. Constructor in trait brittle. No hidden static caches. Documentation states requirements; analyzer finds. Updating trait affects all consumers and reruns contracts. Attributes from traits behavior/version understood.",
    "### Dependency injection and lifetimes\nConstructor injection makes mandatory deps; factories build request/job/process scopes. O baseline services stateless or explicit context values. O mutante service locator/global container hides provider and captures tenant in singleton. Test alpha→beta same service. DB connection/pool/client lifecycle belongs infrastructure; entity not. Lazy dependency proxy only with thread/process/signal semantics. Optional features via explicit interface. Circular dependency is design smell/event boundary. Container compile/cache by artifact and production graph verified. Factory validates config and no fake fallback. Shutdown closes owners. Secrets only client/config composition. No serializing service graph.",
    "### Decorators and middleware order\nRetry, telemetry, circuit, auth, caching and transaction decorators order changes semantics. O baseline documents pipeline: validate/auth → idempotency/transaction local → external retry/reconcile as appropriate. O mutante retries whole controller after response/effect or caches unauthorized response. Tests fault at each layer and inspect calls/state/effects. Transaction decorator does not wrap provider. Telemetry records final/attempt separately. Cache includes auth context. Retry preserves key. Circuit doesn't convert unknown to failed. Middleware immutability/ownership. Composition test asserts topology/types, but behavioral contract is primary. Upgrade cannot reorder silently.",
    "### Null Object and adapters\nNull Object is valid only when ‘do nothing’ is real domain behavior, not missing mandatory infrastructure. O baseline production provider required; optional analytics may use explicit disabled adapter emitting config state. O mutante catches construction failure and substitutes fake/in-memory. Production graph test forbids. Test doubles are spy/fake/stub with limitation names. Fake persistence must obey shared contract or excluded gates. Adapter translates third-party exceptions/data to domain outcomes, validates response. Anti-corruption mapping. No vendor type in service. Feature disabled visible in readiness/metrics if material. Errors not swallowed.",
    "### Incidente, aceite e fontes\nTrait bypassed policy, service locator reused tenant and retry decorator duplicated effect. Baseline narrow interfaces, composition and explicit ordering. Mutants fail shared contracts, same-service tenant reuse, fault stage and production graph. PHP OOP/traits/variance, PSR/container and adapter docs are sources. Aceite runs real adapters separately. Without engine/infrastructure examples draft. Banca doesn't call interface existence substitutability or fake contract external integration. O relatório registra o grafo de produção efetivo e prova que nenhuma implementação de memória foi selecionada por fallback.",
  ],
  "Atributos, reflection e dinamismo": [
    "## Atributos, reflection e dinamismo\nPHP attributes attach typed metadata to declarations; they are code classes instantiated when requested. O baseline scans known classes/namespaces at boot/build, validates attribute arguments and creates immutable registry. O mutante reflects class name from request or executes I/O in attribute constructor. Tests duplicate routes/handlers, invalid target, missing implementation and deterministic order. Reflection exceptions fail boot before readiness. Attribute class final/readonly where useful. Metadata does not authorize; handler still policy. Cache tied to artifact. No scanning writable upload/vendor untrusted dynamically. Production optimized classmap. Errors redacted paths. Runtime version supports attributes.",
    "### Safe registries\nInput command string maps to registry key built from trusted discovery/config; unknown fails closed. O baseline verifies each handler implements interface and constructor deps resolved. O mutante `new $class`, `call_user_func`, `constant()` or `method_exists/send` on input. Security corpus attempts magic methods/internal/admin classes. Registry exposes names/capabilities not class internals. Duplicate key fatal. Plugin allowlist/provenance/signature and process isolation if third-party. Hot reload not assumed in FPM; deploy artifact rebuild. Metrics bounded by registered key. Serialization carries command type version, then registry maps. Old/new handlers coexist for queue compatibility.",
    "### Reflection costs and boundaries\nReflection can inspect parameters/types/attributes but in hot path repeated scanning allocates/costs. O baseline compiles container/serializer/route metadata once per artifact/process and measures. O mutante caches object containing request/tenant or stale class across deploy incorrectly. OPcache/preload lifecycle. Cache invalidation artifact digest. Generated code reviewed and no secret. Reflection can access non-public through APIs; mapper's privilege constrained to known DTO and validates. Don't use reflection to bypass invariant in generic hydrator. Tests production cache enabled/disabled semantic equality. Benchmark after correct. Errors in cached metadata cause boot fail, not partial routes.",
    "### Magic methods and dynamic properties\n`__get`, `__set`, `__call`, `__invoke`, `__serialize`, `__debugInfo` can hide contract and create injection/leaks. Dynamic properties deprecated/restricted in modern PHP. O baseline declares properties/methods and uses explicit proxy only with allowlisted interface. O mutante forwards unknown method name from HTTP to admin client. Tests typo/unknown and no invocation. `__debugInfo` redacts secrets. `__toString` no I/O/secret. `__unserialize` validates version. Proxy exception mapping. Analyzer recognizes annotations but runtime still. Framework magic at boundary wrapped. `AllowDynamicProperties` not blanket fix. Hydrator doesn't set arbitrary payload keys.",
    "### Attributes for validation/serialization\nMetadata-driven schema can reduce repetition, but validator/serializer must implement closed rules and resource limits. O baseline attributes specify known constraints/groups; boundary chooses group server-side. O mutante client supplies validation group or serializer exposes all public fields. Tests unknown fields, nested max, privileged properties and version. Reflection type plus attribute does not coerce safely by itself. Error paths bounded. Circular graph/max depth. Serialization allowlist separate domain. Custom constraint class no external side effect. Cache compiled. Update dependency reruns corpus. OpenAPI generation compared with behavior. Security annotations don't replace enforcement calls/query scopes.",
    "### Plugin and event discovery\nListeners discovered by attribute may run multiple, order/transaction semantics matter. O baseline priority explicit, handlers idempotent, external side effects after outbox, and duplicate registration test. O mutante reload/preload registers twice or listener sends provider before commit. Registry keyed by class+method/event and immutable. Listener exceptions policy. Event schema/version. Async versus sync explicit. Plugin cannot subscribe to privileged raw data without capability. Tenant context event-owned. Trace context safe. Unregister not needed per immutable artifact but test environment resets. No global mutable dispatcher leaking between tests.",
    "### Incidente, aceite e fontes\nRequest chose class, magic proxy invoked admin and duplicate discovery sent twice. Baseline trusted scan, immutable typed registry and explicit interfaces. Mutants fail class/method input corpus, duplicates, serialization exposure and reload. PHP attributes/reflection/magic docs, Composer autoload and framework metadata docs are sources. Aceite executes build/boot with production cache and functional calls. Without engine examples draft. Banca doesn't call reflection registry authorization or generated spec behavior proof.",
  ],
  "Exceptions, Error e handlers": [
    "## Exceptions, Error e handlers\nPHP agrupa `Exception` e `Error` sob `Throwable`, mas capturar ambos não torna as causas equivalentes. O baseline distingue invalid input e domain outcomes de failures de infraestrutura, timeout ambíguo e programmer defects. O mutante captura `Throwable` no service, retorna false e transforma TypeError ou commit desconhecido em validation. Boundary HTTP/job possui último handler que registra correlation/stage/artifact redigidos e produz resposta/exit seguro; ele não continua processo em estado possivelmente corrompido. Tests injetam cada classe antes/depois de commit/effect e verificam state/outbox/provider. Domain invalid costuma ser result object ou exception estreita. Error inesperado alerta. Não expose stack/path/env.",
    "### Taxonomia e tradução\nAdapters traduzem PDOException/cURL/error codes para categorias estáveis: Conflict, RetryableUnavailable, Permanent, UnknownAfterEffect ou Bug. O baseline inspeciona SQLSTATE/constraint/status/stage conhecidos, não mensagem humana genérica. O mutante trata toda PDOException como duplicate ou todo 5xx como safe retry. Contract tests forçam unique específico, deadlock, connection loss, 429, invalid auth, apply-drop. Translation happens once at adapter boundary; service not coupled vendor. Original exception chained internally for diagnosis, external code bounded. Unknown stays explicit. Updates in driver/provider rerun matrix. An uncategorized error fails closed/alerts rather than guessed. Retry policy outside invalid transaction.",
    "### try, catch e finally\n`finally` roda na saída normal/exception, mas não é garantia sob process kill, OOM or fatal outside recoverable path. O baseline uses it to release in-process handle/slot/temp, while durable obligations live in DB/outbox. O mutante relies on finally to mark provider effect or ack queue, losing state on SIGKILL. Tests normal/error/early return plus kill gate separately. Return/throw in finally can mask original and is avoided. Multiple resources acquired in order, released reverse. Cleanup failure logged without hiding primary unless security demands. Transaction rollback in catch/finally verifies active state. Generator partial iteration uses finally. Shutdown functions are best effort, not transaction coordinator.",
    "### Error handlers e warnings\nLegacy/builtin functions may emit warning and return false. `set_error_handler` can convert selected severities to ErrorException, but must respect `error_reporting` and avoid recursion. O baseline wraps risky call, checks false and captures diagnostic redacted. O mutante suppresses with `@` or global handler converts harmless deprecation/unknown inconsistently. Tests missing file, permission, malformed stream and handler failure. Production display off; structured log. Header/output not contaminated. Handler restored in isolated library/test. Do not convert errors from unrelated code accidentally. Deprecations tracked separately. Fatal/parse/startup errors have different reach; artifact lint/boot catches. `error_get_last` not primary protocol.",
    "### Transactions and exceptions\nPDO transaction rolls back only if application does it; exception does not magically rollback after connection persists. O baseline service begins, commits, catches Throwable to rollback if active then rethrows/translate outside. O mutante catches inside and continues with aborted transaction or returns success after rollback failure. Tests fail each statement and use new connection readback. Nested transaction/savepoint semantics explicit in wrapper; no fake nesting counter without DB. Deadlock/serialization retry entire closure with IDs stable outside attempt. Commit can be unknown on connection loss; query by tenant/key before repeat. Finally releases connection. No provider call within local transaction. Isolation documented.",
    "### Global exception boundary\nHTTP boundary checks whether headers sent and emits minimal problem JSON/HTML with request ID; job boundary classifies retry/dead-letter; CLI exits nonzero. O baseline never dumps exception to client. The mutante has `display_errors=On` or catches and always HTTP 200. Request tests force exception before/after output, ensure correct content type/status/no sentinel. Output buffering policy. Error reporter itself bounded and cannot throw recursively. Fatal OOM may require reserved memory/process restart; do not promise pretty response. Security errors uniform. Audit action failure policy. Observability links without secret. Different SAPIs gated. Framework handler integration reviewed rather than double handlers.",
    "### Incidente, aceite e fontes\nCatch amplo apagou TypeError, warning entrou no JSON e finally foi tratado como garantia contra kill. Baseline taxonomy, narrow adapters and durable recovery. Mutants fail SQL/provider stages, warning/false, rollback and global response secrecy. PHP Throwable/error handling/PDO docs and provider driver docs are sources. Aceite executes actual runtime/SAPI and readback. Without engine examples draft. A banca doesn't call no uncaught exception correctness or pretty 500 recovery proof.",
  ],
  "Streams e filesystem": [
    "## Streams e filesystem\nPHP unifica files, stdin, HTTP and wrappers as streams, with metadata/context/filter behavior. O baseline identifies allowed scheme/resource, opens with mode and context fixed, limits bytes/time and closes owned handle in finally. O mutante accepts path/URL into `fopen`, enabling traversal or SSRF via wrappers. Tests schemes `file`, `php`, `data`, `phar`, HTTP and invalid encodings according enabled wrappers, verifying denied effects. `allow_url_fopen` configuration cannot be sole policy. A resource isn't serializable and has process lifetime. Partial reads/writes/errors handled. Stream metadata not trusted auth. No transaction held while slow stream.",
    "### Path containment\nJoining root with user filename does not guarantee containment: absolute paths, `..`, separators, symlinks, case and Windows drive/UNC matter. O baseline receives logical ID mapped to server-generated filename or validates decoded relative segments, resolves parent and opens safely. The mutante `realpath` only after file exists or checks string prefix `/root/app` accepting `/root/application`. Tests traversal encoded/double, null, absolute, symlink race in sandbox and platform variants. Prefer storage abstraction/IDs. Never follow uploaded symlink/archive entries. Error hides host path. Root configured immutable. Cleanup exact temp path. Permissions least privilege.",
    "### Temp files and atomic write\nTemp file uses secure exclusive creation in intended directory, permissions, size quota and owner cleanup. Durable update writes temp, flush/fsync where required, atomic rename on same filesystem and directory durability per platform—only when requirement warrants. O mutante predictable `/tmp/name` or rename across mounts assumed atomic. Tests concurrent writers, crash points, disk full/read-only and existing target. Lock file not distributed coordination across hosts. File locks advisory/platform-specific and release on process, not business protocol. Avoid TOCTOU check-then-open. Upload tmp lifecycle controlled by SAPI; move_uploaded_file validates actual upload but authorization/content remains. Backup/restore includes files/checksums.",
    "### Uploads and archives\n`$_FILES` status, actual bytes and upload limits validated before use. Filename/display separate from key; MIME header untrusted, sniff/decoder sandbox. O baseline private storage, scan/process resource limits, safe Content-Disposition and lifecycle. The mutante trusts extension or serves SVG/HTML inline same origin. Corpus polyglot, double extension, truncated, zero, oversized, zip bomb, traversal entries, symlink. Archive extraction validates every entry, total/count/ratio and containment, rejects links/special. Partial cleanup. Direct/object storage signed operation ties tenant/purpose/size/checksum. Attach authorization. Unattached expiry. Processor version/provenance. No user path to shell string.",
    "### Streaming and backpressure\nLarge download/export reads/writes chunks, not all memory, and handles client disconnect. O baseline authenticates first, releases DB transaction before stream, owns handle and enforces total/deadline/rate. The mutante passes PDO cursor/file after connection lifecycle or buffers CSV. Tests partial consumer/cancel/slow client and pool/handle release. CSV formula injection/encoding/newlines. HTTP headers before bytes and errors afterward cannot change status; operation log. Range support explicit. X-Sendfile/proxy offload gate. Output buffering/compression interactions. Backpressure. Generator finally but crash cleanup startup. Tenant access rechecked for signed download. Response not cached public accidentally.",
    "### Filesystem security and secrets\nApp user reads only necessary config/code and writes only tmp/uploads/cache/log targets. O baseline no executable uploads, directory listing, backup/config under webroot. The mutante stores `.env`, composer auth or DB dump publicly. Artifact/permissions scan and HTTP probes. Secrets not written temp/core/log. File permission umask explicit; container non-root/read-only. Log rotation owner. Session file store risks and permissions/cleanup. PHAR deserialization risks when file operations invoke metadata in vulnerable contexts/version; avoid untrusted schemes. Local file inclusion from template name prevented by closed registry. Deploy symlink/current release behavior tested.",
    "### Incidente, aceite e fontes\nUser path escaped root, archive wrote outside and slow download exhausted pool. Baseline logical IDs, safe extraction and streaming ownership. Mutants fail wrapper/path/archive corpus, disk fault and cancellation. PHP streams/filesystem/upload docs, OS/storage/proxy docs are sources. Aceite observes sandbox filesystem/handles/RSS and no prohibited network. Without runtime/platform examples draft. Banca doesn't call realpath string check complete containment nor chunk loop bounded service proof.",
  ],
  "JSON, serialize e schemas": [
    "## JSON, serialize e schemas\nJSON is text protocol with object/array/number/string/bool/null, not PHP object graph. O baseline bounds bytes before `json_decode`, chooses associative/object mapping deliberately, sets depth and `JSON_THROW_ON_ERROR`, then validates schema and builds values. O mutante ignores false/null/error or lets deep/wide body allocate first. Corpus malformed/truncated, duplicate keys policy, invalid UTF-8, huge/deep/wide, big integers, empty object/list. Errors bounded path/code without echo. Response uses JSON_THROW and allowlisted DTO. Content-Type/charset. No partial output flag masking invalid. Parser/runtime version recorded.",
    "### Shape and coercion\nDecoded associative array still mixes list/map/scalars. O baseline checks `array_is_list`, exact/allowed keys, required, nullability, type and length before domain. The mutante casts objects/arrays or uses `isset` so explicit null becomes missing. Tests unknown, missing, null, wrong nested shape, arrays one over. Numeric JSON might be int/float depending range; IDs accepted strings. Boolean exact. Decimal as string per contract. Duplicate keys may be last-wins parser; security-sensitive protocol rejects/detects upstream if needed. Patch missing vs null. Schema version. Validation all before side effects. Error paths limited.",
    "### JsonSerializable and presenters\n`JsonSerializable` can hide accidental fields/work; generic encode of public/model properties is fragile. O baseline presentation DTO returns fixed scalar/nested shapes and handles times/money/enums explicitly. The mutante serializes entity, later public property secret leaks, or recursive association. Contract tests exact required and forbidden fields, types/precision. No DB query/provider in serialization. Circular references/depth. Locale independent canonical API. `serialize_precision` config captured. `json_encode` of enum behavior/version known; map explicitly for portability. Error outcome separate. HTTP cache variant. Large collection paginated/stream-safe.",
    "### Native serialize and object injection\n`serialize/unserialize` encodes PHP-specific object/class metadata and hooks `__wakeup/__unserialize/__destruct`; untrusted bytes can trigger gadget chains. O baseline never uses external/session/cache data from untrusted source with object classes; prefer JSON/schema. If legacy internal data, `allowed_classes => false` or exact minimal plus signature, size/version/migration, still review. The mutante `unserialize($_COOKIE/POST/cache shared)` or assumes base64 safe. Corpus object tags/references/corrupt/huge. Dependency gadgets. PHAR contexts. Session serializer/config. Durable protocol not native serialization across deploy. Cache disposable/versioned. Secret/token signatures purpose-bound.",
    "### Schema evolution\nWire/job/event/cache payloads carry version or evolve additively. O baseline readers support known old/current, reject future safely, writers current, fixtures each version. The mutante removes/renames field while old jobs remain or defaults privileged. Migrations/upcasters pure/bounded and don't load current mutable model. Unknown enum explicit. Mixed deployment producer/consumer contract. Deprecation/retention queue duration. Restore older payload. JSON Schema/OpenAPI compared to behavior, not assumed. Canonical fingerprint pins version. Field absence not null. Consumer-driven tests. Rollback. Evidence version/tool artifact.",
    "### XML/YAML/other formats\nIf accepted, each parser has external entity/tag/alias/resource policies. O baseline defaults JSON; XML disables external entity/network and limits depth/size, YAML safe schema/no object tags/aliases as required. The mutante switches parser based on Content-Type without hardening or auto-detects serialized PHP. Tests XXE, billion laughs, YAML object/alias bomb and format confusion. Extensions/libxml/yaml versions. Error redacted. Transform/template injection. Signature verifies raw canonical protocol before parse according provider. Multipart fields same schema. CSV formula. Do not claim parser not installed secure; unsupported type 415.",
    "### Assinatura e canonicalização\nProtocolos assinados definem exatamente quais bytes entram no MAC. O baseline de webhook valida timestamp e raw body antes de decodificar; não reserializa JSON, pois whitespace, order e escapes podem mudar. Quando fingerprint interno exige canonical form, a aplicação possui versão e algoritmo próprios: ordena apenas maps, preserva list order, representa decimal/time/Unicode conforme contrato e limita depth/bytes. O mutante usa `json_encode(json_decode($raw))` para assinatura ou mistura canonical versions. Tests alteram um byte, whitespace/order equivalente para fingerprint, duplicate keys e encoding. `hash_equals` compara digests de tamanho esperado. Key ID/purpose/replay window. Secret nunca logado. Canonical hash não autoriza conteúdo; schema/policy continuam.",
    "### Incidente, aceite e fontes\nJSON null was mistaken for error, model serialization leaked secret and unserialize executed gadget. Baseline throw-on-error, closed schema/presenter and no object loading. Mutants fail shape/depth/UTF-8/bigint, forbidden field, legacy object and evolution matrix. PHP json/serialization/parser/schema docs are sources. Aceite runs runtime/extensions and malicious corpus with effect oracle. Without engine examples draft. Banca doesn't call valid JSON valid domain or allowed_classes universal gadget safety.",
  ],
  "Datas, números e locale": [
    "## Datas, números e locale\nTime value must distinguish instant, local civil time, timezone and duration. O baseline uses DateTimeImmutable, explicit timezone/format and injected Clock. The mutante relies default timezone/server `date()` and deploy region changes behavior. Parsing with `createFromFormat` plus `getLastErrors`/round-trip catches normalized invalid dates; constructor accepts relative phrases useful internally but too permissive for API. Tests DST gap/overlap, leap, boundaries and server zones. Persist UTC instant with precision; preserve business zone if future schedules. ISO 8601 response. Comparison immutable. Clock monotonic for in-process duration, wall clock for durable.",
    "### DST and calendar arithmetic\n`+24 hours` and `+1 day` may differ across DST; month addition can normalize unexpected dates. O baseline names business rule: elapsed duration versus next local calendar occurrence. The mutante adds seconds for daily local event. Tests São Paulo/other relevant zones, transitions, month-end, leap. Timezone database version can change future rules; record/update/recompute policy. Ambiguous local time requires offset/disambiguation. Missing local time rejected or policy. DateInterval semantics reviewed. Cron/queue scheduler time zone explicit. Expiry/security uses instant. Reporting date uses tenant zone. Database session timezone known. No string sorting formatted locale.",
    "### Decimal, rounding and currency\nPHP float binary approximates; prices/taxes use integer minor units or decimal extension/library. O baseline currency carries scale, rounding rule/stage and overflow bounds. The mutante casts decimal DB string to float and back. Tests half values, negatives, multiple operations, currencies with 0/3 decimals and large. BCMath/ext may return strings and configuration/scale; library version. Equality exact canonical. Division produces result/remainder. JSON not raw float. Locale formatter display only. Input parser tied locale contract. Database DECIMAL and PDO fetch mapping. Totals reconcile line items by rule. No implicit numeric string math.",
    "### Intl and locale\nLocale affects display/plural/collation, not canonical values or authorization. O baseline negotiates allowlisted locale from user preference, uses IntlDateFormatter/NumberFormatter/MessageFormatter with explicit zone/currency and checks errors. The mutante accepts arbitrary locale/path or uses process-global `setlocale`, leaking between FPM requests. Tests alpha pt→exception→beta en same worker, parallel/long-lived. Prefer formatter instances/context not global. ICU/ext version recorded; output may evolve. Pseudo/RTL/expansion. Missing translation explicit. Sort/search collation belongs DB/Intl chosen layer. Unicode normalization. Logs/API codes canonical.",
    "### IDs, counters and overflow\nDatabase bigints may exceed JavaScript safe integer; API sends ID string. PHP integer platform/overflow checked. Counters use atomic DB operations and nonnegative constraints, not read-add-save. The mutante overflow converts to float or JSON client rounds ID. Tests PHP_INT boundaries, JS-safe boundary, encode/decode roundtrip and negative. Quantities domain small. Metrics counters library type. Time milliseconds multiplication overflow. Random IDs from random_bytes/UUID library, not mt_rand. Hash compare safe. Sequence not auth. Decimal identifiers remain strings preserving leading zeros. Canonical input regex/length. Static analyzer range annotations.",
    "### Locale in input/output and storage\nHuman form may accept localized number/date, but API should prefer unambiguous. O baseline stores canonical, returns machine format plus localized presentation separately. The mutante uses formatted `1.234,56` directly in SQL/float. Parser exact locale and round-trip; rejects ambiguous separators. Tests spaces/nonbreaking, currency symbols, alternate digits and grouping. Browser input type behaviors. CSV/export format/Excel formula/encoding. Timezone/locale captured for audit only when relevant. Changing preference rerenders, not mutates durable value. Cache key includes locale. Email/job uses user/tenant preference snapshot/reload contract. No locale from untrusted path to file.",
    "### Incidente, aceite e fontes\nServer timezone expired early, float lost cents and global locale leaked to next FPM request. Baseline immutable explicit time/decimal and scoped formatter. Mutants fail DST/calendar, rounding/overflow, long-lived locale reuse and persistence/API roundtrip. PHP DateTime/intl/numeric/JSON docs, timezone/ICU and DB docs are sources. Aceite runs actual extensions/runtime/platform. Without them examples draft. Banca doesn't call DateTimeImmutable correct timezone semantics nor NumberFormatter canonical storage. O relatório registra timezone database, ICU, integer size, decimal implementation e confirma o mesmo valor após banco, fila, JSON e nova request FPM.",
  ],
  "Request, headers e body": [
    "## Request, headers e body\nSuperglobals (`$_GET`, `$_POST`, `$_FILES`, `$_COOKIE`, `$_SERVER`) and `php://input` are transport data, not domain values. O baseline places server/framework request adapter at edge, limits content length and streamed bytes before decoding, validates method/content type/charset/schema, then constructs immutable command. O mutante passes superglobal arrays to service/model and body can override tenant/status. Tests run real HTTP/SAPI where possible with missing/duplicate/malformed headers, oversized/truncated/chunked and cross-tenant fields. `filter_input` isn't universal schema or SQL/XSS solution. Input variables may be transformed by PHP config; raw JSON behavior differs from form/multipart. Document source precedence; never merge query/body/path blindly.",
    "### Body stream and limits\n`php://input` is a stream; reading all via `file_get_contents` before limit can exhaust memory. Server/FPM/post limits may reject earlier, but app still enforces endpoint budget and handles missing body. O baseline reads at most max+1, honors deadline/client abort policy and closes owned resource. The mutante trusts Content-Length only, allowing absent/lying/chunked/compressed. Tests actual server proxy with over/equal/under, slow upload and disconnect. Compression expanded ratio/limit. Multipart uses SAPI upload settings/error codes and per-file total. Error 413 bounded without logging body. No DB connection/transaction before reading. Metrics size buckets. Temporary upload cleanup. Reverse proxy and app limits aligned.",
    "### Headers and proxies\nHeader names case-insensitive, duplicates/comma combination header-specific, values untrusted. O baseline uses framework/PSR API and explicit policies for Authorization, Idempotency-Key, Content-Type, Accept, Host, Forwarded/X-Forwarded. The mutante builds headers from `$_SERVER` assumptions or trusts spoofed proto/host/IP. Trusted proxy list/topology determines client/scheme; gate external sends direct/spoof/through ingress. Host allowlist prevents reset/open redirect poisoning. CRLF rejected. Header size/count server-limited. Correlation/trace IDs validated/bounded and not auth. Multiple Authorization ambiguity denied. Sensitive headers redacted. Response Vary. HTTP/2 normalization considered by server.",
    "### Method, routing and parameters\nRoute method/path identifies operation; route constraints reject malformed shape but don't authorize. O baseline separates path/query/body, decodes once, validates IDs and applies policy on tenant-scoped resource. The mutante lets GET mutate or nested route fetch global ID. Tests methods including HEAD/OPTIONS/override policy, encoded slash/dot/Unicode and same IDs in tenants. Method override only trusted form/auth/CSRF context if enabled. Query arrays/bracket syntax can create unexpected shapes; closed schema. Pagination filters bounded/mapped. Path normalization by proxy/server matches router. 404/403 uniform as needed. Route inventory detects debug/admin endpoints. URL generation host config trusted.",
    "### Command ownership and Current context\nBoundary copies validated scalars/value objects and authenticated identity into readonly DTO. It never retains request stream/superglobal references in job/closure. O mutante captures `$_REQUEST` or mutable request and long-lived worker sees later context. Test delayed executor mutates globals/request, command stable. PHP arrays copy-on-write but nested objects shared; values immutable. Current/global context cleared in finally each request, including exception. Service still receives tenant explicitly. Job payload server-issued IDs/version. Request ID safe. Body tenant ignored/rejected. No default tenant. Long-running servers (RoadRunner/Swoole) make reset mandatory; FPM reuse also static/global risks. Framework request lifecycle gate.",
    "### Content negotiation and error\nRequest Content-Type tells body format; Accept chooses response. O baseline supports explicit media types/versions, returns 415/406, uses JSON problem/error schema and no PHP warning bytes. The mutante route default JSON accepts form/YAML or returns HTML 200 on parse error. Contract tests Accept wildcards/q values as supported, charset, malformed JSON and error pages. Unknown API version. Errors don't echo body/token/internal paths. Status/outcome mapping closed. Correlation in header/body safe. `headers_sent` checked only last resort; no output before response. Output buffering policy. HEAD no body. Cache-Control and Vary. Localization separate from code.",
    "### Incidente, aceite e fontes\nBody was read unbounded, proxy headers spoofed tenant URL and query/body merge overwrote identity. O baseline bounded separated request and trusted proxy policy. Mutants fail byte/shape/header/path corpus, cross-tenant and delayed ownership. PHP request/input/SAPI, PSR-7/server/proxy docs are sources. Aceite uses actual HTTP entrypoint/proxy and state readback. Without server/runtime examples draft. Banca doesn't call superglobal sanitation schema validation nor route regex authorization.",
  ],
  "Response, cookies e sessão": [
    "## Response, cookies e sessão\nHTTP response is status, headers and bytes after domain outcome. O baseline maps Created/Replayed/Conflict/SoldOut/Invalid/Unknown exhaustively, serializes allowlisted body and emits no accidental output. The mutante echoes/debugs early, then headers fail or always 200. Contract tests each outcome/content type/headers/schema and no secrets. Created Location trusted host/path; Unknown operation status; replay same identity. `http_response_code`/header direct code isolated in adapter or PSR response immutable. Output buffers understood/cleared safely. Streaming owns lifecycle. Error after commit doesn't imply operation failed. Client disconnect and idempotent retry. Compression/cache policy.",
    "### Cookie attributes\nCookies carry browser state automatically. O baseline sets Secure, HttpOnly, SameSite, narrow Domain/Path, expiry and prefix/name by environment over HTTPS behind trusted proxy. The mutante disables Secure because TLS ends ingress or uses broad parent domain. Browser/external tests inspect Set-Cookie final and cross-site behavior. SameSite is layer not CSRF complete; None requires Secure. Signed/encrypted data still needs authorization/revocation. Size limits and minimal values. Cookie names avoid collision apps/env. Deletion repeats matching attributes. Host header not used for domain. No tokens in query. Session and remember token lifecycles separate. Rotation key IDs/janela.",
    "### Session fixation and storage\nOn login/privilege elevation regenerate session ID and invalidate old; logout destroys server state/cookie according policy. O baseline stores user ID/auth version/timestamps, reloads active membership. The mutante preserves anonymous ID or stores role/tenant trusted. Tests pre/post IDs, replay old cookie, logout/global revoke, membership change and alpha→beta worker. File/Redis/DB session store permissions/TTL/locking/availability explicit. PHP session locking can serialize parallel requests and harm latency; read-and-close when safe, mutation coordinated. `session.use_strict_mode`, cookie-only and entropy configured. Serializer avoids object gadgets. Cleanup/GC. Store outage fail policy. No session auto-start in CLI jobs.",
    "### Headers and redirects\nSecurity headers CSP, frame, nosniff, referrer, permissions and HSTS correspond to content/proxy. O baseline tests final endpoint, not only PHP array. Redirect targets closed/local parsed; 303 after POST when applicable. The mutante `Location: $_GET['return']` or Host poisoning. Corpus external/protocol-relative/control/encoded. Header function replace/append semantics and CRLF protections version-known. Cache private/no-store for auth/sensitive. ETag includes tenant/auth representation. CORS is browser policy not auth; credentials never wildcard. Errors/mounts carry headers. HSTS rollout safe. CSP nonce per response/cache. Download disposition safe filename.",
    "### Session concurrency and CSRF\nParallel requests with same session can block or race depending handler. O baseline minimizes lock duration, closes session before provider/stream, and server state updates atomic. The mutante holds session lock through slow HTTP, starving tabs, or closes then mutates session array ineffectively. Tests parallel requests/lock wait and correct persisted data. CSRF token bound to session/purpose, random/secure compare/rotation policy. Login CSRF considered. API bearer without cookie has distinct risk. SameSite complements. Session regenerate concurrent requests behavior. Double submit uses idempotency database, not session flag. Session cannot coordinate multiple devices/replicas business invariant.",
    "### Long-lived and cleanup\nFPM worker reused, alternative long-running server more explicit; globals/statics/container request services must reset. O baseline request scope and finally clear identity/locale/logger context/DB transaction/output buffer. The mutante static response/session/user leaks. Sequential alpha→exception→beta test same worker/process harness. Persistent connections state reset. Header list/output buffer/session status verified. Memory retention. Framework lifecycle integration. Fatal/restart. No register_shutdown_function to commit. Telemetry flush bounded. Response object doesn't retain huge request after send. Streaming cancellation cleanup. CLI command unaffected. Production SAPI evidence.",
    "### Incidente, aceite e fontes\nSession fixation survived login, cookie lacked Secure and redirect used attacker Host. O baseline rotates/minimizes session, cookie flags and trusted URL config. Mutants fail old cookie/logout/revoke, cross-site, proxy/redirect and worker reuse. PHP sessions/setcookie/headers, browser and proxy docs are sources. Aceite uses browser/server/store actual with readback. Without environment examples draft. Banca doesn't call signed cookie authorization or SameSite complete CSRF defense. O relatório confirma o mesmo comportamento em duas réplicas, mede lock/TTL do store e verifica que revogação continua válida após restart e rotação de chave.",
  ],
  "Routing, middleware e PSR": [
    "## Routing, middleware e PSR\nPSR-7 models immutable server request/response; PSR-15 middleware transforms request or short-circuits and delegates to handler. O baseline composition order deliberate: trusted proxy/host/limits/request ID, error boundary, auth/session/CSRF, tenant/policy, rate, routing/controller depending framework semantics. The mutante adds auth after handler or logs raw body before redaction. Integration tests traverse stack, not call controller. Immutability means `withAttribute` returns new request; forgetting assignment loses context. Attributes are server-generated, not client authority. Body stream position/rewind ownership. Response body mutable stream despite immutable message shell.",
    "### Ordering and short circuit\nMiddleware order changes whether errors/metrics/security headers wrap denials and whether scarce work begins. O baseline documents stage and tests invalid auth never hits repository/provider, oversized never parsed, exception gets safe response. The mutante transaction middleware wraps template/provider or retry wraps whole request. Short circuit still emits required headers/telemetry and releases resources. Finally around delegate. Duplicate middleware avoided. Framework route middleware versus global understood. CORS preflight policy before auth as designed without exposing data. Rate key after trusted identity when possible. Static assets separate stack. Health minimal/reserved. Upgrades diff stack.",
    "### Request attributes and context\nAuthenticated Identity/Tenant/Route metadata may be request attributes from trusted middleware, typed wrapper. O baseline controller requires presence and constructs command. The mutante reads body/header tenant or silently creates guest/default. Attribute names namespaced, no collision. Context immutable/value, reset at request. Background job doesn't have PSR request; carries server-issued IDs. Trace/correlation not auth. Test malicious incoming headers named like attributes have no effect. Long-lived worker same request object not retained. Policy receives actor/resource. Middleware error before identity logs safe. Localization/timezone context scoped. Container request scope disposal.",
    "### Routing and controllers\nRouter maps method/path to fixed handler and constraints; no controller/method/class names from input. O baseline route inventory, only supported operations, nested scoping and version. The mutante dynamic call/action or public debug route. Tests unknown method/path/format, same ID tenants, URL generation and mounted admin. Controller is thin boundary, no provider call/transaction orchestration. Parameter decoding once. `HEAD/OPTIONS` semantics. Path traversal not file include. Route cache generated artifact and invalidated. Middleware per route capability. Authorization cannot be inferred from route group. Handler implements interface. Dependency injection no service locator.",
    "### Streams and immutable messages\nPSR stream is stateful pointer/resource; passing immutable request doesn't freeze stream. O baseline boundary reads once bounded or replaces/rewinds explicitly and downstream contract. The mutante logging middleware consumes body leaving parser empty, or async captures stream after closed. Tests middleware stack with non-seekable/partial streams. Response stream ownership and close. Large upload streamed. `getContents` from current position. String conversion can load all. Clone message shares stream object often. Headers arrays. URI validation/host. ServerRequest uploaded files normalized but content untrusted. No transaction before body. Cancellation releases.",
    "### Error and response middleware\nOuter error middleware catches unexpected Throwable, records redacted context and returns minimal response unless bytes already irreversibly sent. Domain mapping happens closer/explicit. O mutante catches everything and 422. Tests bug, invalid, not found/forbidden, DB unavailable, Unknown, serialization failure. Security headers and request ID on errors. Error renderer no DB/provider. Production display off. CLI/job separate boundaries. `Throwable` rethrow in test. Logging failure bounded. Response emitter detects invalid headers/body and doesn't hide. Status stable. Stack trace internal. Content negotiation of errors. No retries at HTTP middleware after side effect.",
    "### Interoperability and contracts\nPSRs define interfaces, not implementation behavior: factories, server, router, container and emitter differ. O baseline pins libraries and has shared contracts for messages/middleware, plus end-to-end chosen server. The mutante assumes one stream is seekable or attributes preserved across adapter. Contract tests alternate implementation where supported and production. No reliance on implementation-specific internals. PSR-17 factories injected. PSR-11 container not service locator in domain. Logger PSR-3 structured limitations. Cache PSR semantics may lack atomicity. Async server compatibility. Version/advisory/provenance. Benchmarks. Boundary wrappers isolate upgrade.",
    "### Incidente, aceite e fontes\nLogger consumed body, middleware order authorized late and dynamic handler invoked admin. O baseline ordered stack, typed context and closed routing. Mutants fail short-circuit effects, non-seekable stream, incoming attribute spoof and route inventory. PSR-7/15/17, server/framework docs are sources. Aceite runs actual stack/server. Without engine/server examples draft. Banca doesn't call PSR compliance app security or immutable request immutable body stream.",
  ],
  "Templates, escaping e CSRF": [
    "## Templates, escaping e CSRF\nHTML output encoding depends on context. For text/attributes, `htmlspecialchars` with `ENT_QUOTES|ENT_SUBSTITUTE`, explicit UTF-8; URL/JS/CSS require their own construction/policy. O baseline template engine autoescape and helpers. The mutante echoes input or marks safe to fix UI. Corpus tags, quotes, entities, SVG/events, invalid UTF-8 and protocol URLs. Browser test confirms no script/network, not substring only. Safe string types reviewed. Escaping shows markup literally; rich HTML needs maintained sanitizer allowlist. CSP layer. Data serialized to JS via safe JSON helper/nonce or fetched endpoint. No generic escape.",
    "### Template ownership and helpers\nTemplate receives presenter/DTO authorized and preloaded, not raw model/request/container. O baseline helpers pure, return safely encoded markup and map variants/classes/destinations closed. The mutante template queries DB, calls policy late or builds include path from input. Tests hostile content, null/locale and forbidden fields/N+1. Partial/component locals explicit. File names fixed registry; no LFI. Errors do not dump context. Cache includes tenant/auth/locale/version. Reused templates email/browser contexts differ. Translation strings escaping/plural. URLs via trusted base/router. Form fields values escaped. Debug toolbar production off.",
    "### CSRF model\nBrowser sends cookies automatically; attacker can cause state-changing request. O baseline all unsafe methods cookie-auth require unpredictable session-bound/purpose token and Origin/SameSite layers. GET safe. The mutante disables CSRF for JSON endpoint still cookie-authenticated or accepts token from cookie alone without double-submit integrity design. Tests cross-site form, missing/invalid/expired/session-changed and valid; state readback. Login/logout CSRF considered. Bearer-only API policy distinct, but CORS/storage threat. Webhook uses HMAC raw body, not CSRF. Token compare secure, length. Rotation/multi-tab behavior. Error uniform. Framework mechanism configured/tested actual.",
    "### XSS and session consequences\nXSS can read non-HttpOnly DOM data, act with session and bypass CSRF by reading tokens, so HttpOnly/SameSite/CSRF don't replace encoding/CSP. O baseline minimizes client secrets, strict CSP/nonces, sanitize rich content and safe upload serving. The mutante claims HttpOnly solves XSS. Tests stored/reflected/DOM contexts, CSP report/enforce, upload SVG/HTML. Session/action audit may detect. Token in DOM only where form needs. Third-party scripts/trust supply chain. JSON content type/nosniff. URL schemes. Open redirect/phishing. Incident rotates session/secrets as appropriate, investigates persisted payload. Template dependency advisories.",
    "### Forms and validation errors\nServer validates all; client validation UX only. O baseline POST-redirect-get on success, 422 render on invalid, preserves non-secret input, regenerates/keeps CSRF appropriately, accessible error summary/field links. The mutante echoes password/token or returns 200 success-looking invalid. Double submit idempotency key + DB. File inputs not repopulated. Error strings escaped; field names fixed. Checkbox missing semantics explicit. Locale. Method override protected. Multipart limits. Autocomplete attributes sensible. Browser tests keyboard/focus/back/refresh and concurrent submits. State/outbox oracle. Flash escaped/one-use. No hidden privileged fields trusted.",
    "### CSP, headers and inline code\nCSP source list/nonce/hash restricts script/style/connect/frame; baseline avoids unsafe-inline/eval and tests final proxy header. The mutante wildcard to accommodate vendor. Nonce random response and inserted by helper; cached HTML implications. Report-only rollout, report endpoint limited/redacted. frame-ancestors, nosniff, referrer and permissions complement. HSTS at TLS layer. Third-party minimal/integrity/sandbox. Build/assets compatible. Error pages too. Browser violations fail relevant test. CSP cannot sanitize HTML or stop allowed compromised script. Trusted Types optional. Header length. Config version. No nonce logging.",
    "### Incidente, aceite e fontes\nRaw echo stored XSS, JSON cookie endpoint skipped CSRF and dynamic include enabled LFI. O baseline contextual encoding, CSRF and closed templates. Mutants fail XSS/browser corpus, cross-site requests, upload/template path and CSP final. PHP htmlspecialchars/session, template/framework, browser/CSP docs are sources. Aceite browser + HTTP stack + state readback. Without environment examples draft. Banca doesn't call escaped text safe URL/JS or CSRF token XSS defense. A evidência inclui DOM final, console e network do browser, cookies/headers recebidos após o proxy e consulta do estado durável. O corpus atravessa texto, atributo, URL, JSON embutido, rich text e upload ativo; cada sink usa controle próprio. Também se verifica keyboard/focus e mensagens de erro para impedir que uma correção de segurança torne o formulário inutilizável. Um scanner automatizado complementa, mas não substitui, a execução que comprova ausência de script, request indevido ou mudança de estado cross-site.",
  ],
  "PDO, binds e SQL seguro": [
    "## PDO, binds e SQL seguro\nPDO oferece interface comum, mas driver, emulated prepares, fetch types, transactions and errors differ. O baseline constructs DSN/config from trusted config, uses exception error mode, native prepares when appropriate and explicit fetch mode. All values use placeholders; identifiers/order/direction use closed mapping. The mutante concatenates query/search/order or treats quote as universal. Corpus quotes, comments, wildcard, null byte/encoding and identifier attempts runs against target DB. Query/result state readback. Runtime role least privilege. DSN/password redacted. Persistent connections reviewed. Server version/sql modes/timezone/charset recorded. A green SQLite fake doesn't prove PostgreSQL/MySQL behavior.",
    "### bindValue, bindParam and types\n`bindValue` binds current value; `bindParam` binds by reference and value at execute, enabling subtle loop bugs. O baseline prefers execute arrays/bindValue with explicit PDO::PARAM_INT/STR/BOOL/NULL where driver semantics known. The mutante reuses one referenced variable in loop or binds numeric-looking IDs as ints losing leading zero. Tests types/null/bool/big IDs/decimal strings/binary. LIMIT/OFFSET binding support driver-specific; mapping/cast validated before SQL. Named placeholder reuse may differ with native prepares. No placeholder for table/column keyword. Dates ISO strings/driver types explicit. Fetch casts may be strings. `ATTR_STRINGIFY_FETCHES`/emulate documented. Binding doesn't authorize tenant.",
    "### LIKE, lists and dynamic filters\nLIKE wildcards `%`/`_` remain semantics inside bound value; literal search escapes with chosen ESCAPE. IN lists generate one placeholder per bounded element; empty handled explicitly. O baseline maps sort/filter fields and composes predicates server-side. The mutante joins CSV raw or builds arbitrary operator. Tests empty/one/max/one-over, Unicode/collation, wildcard and null. Large lists use temp/table/join/batch strategy. Query plan/index. Optional filters don't become `OR ? IS NULL` plan disaster without measurement. Tenant predicate always present, not optional. Search full-text uses its parser/grammar allowlist and limits. Pagination keyset. Identifiers quoted only trusted mapping.",
    "### Fetching and hydration\nFetch mode can return associative, numeric, class/hydrate magic. O baseline FETCH_ASSOC then explicit mapper validating required columns/types/status, or safe ORM mapping. The mutante FETCH_CLASS bypasses constructor/sets properties unexpectedly or row partial becomes entity. Tests missing/extra/null/invalid enum/bigint/decimal/time. Column aliases stable. No SELECT * for contracts. Duplicate column names in joins. Streaming cursor owns connection; closeCursor. FetchAll large memory avoided. Query result errors checked. Read model separate. Database strings/encoding. Mapper never uses raw row as JSON. Tenant row verified. Hydration shouldn't emit events. Identity map bounded/request scope.",
    "### SQL errors and statements\nPDOException errorInfo/SQLSTATE categorized only for known driver/constraint; transaction may be aborted. O baseline closes/reuses statement appropriately, rollback and translates unique idempotency/deadlock/timeout. The mutante catches any integrity error as replay. Tests specific constraints, syntax bug, disconnect, deadlock. Prepared statement lifecycle/cache bounded and schema change handling. Multi-statements disabled. Row count semantics driver-dependent; conditional update affected rows tested. LastInsertId behavior sequences/transactions driver-specific; prefer generated ID. No SQL/error/DSN in client. Logging template + bounded safe metadata, not binds secrets. Slow query instrumentation.",
    "### Tenant and authorization in SQL\nEvery SELECT/UPDATE/DELETE/unique key includes tenant or joins scoped parent; runtime role/RLS layer where available. O baseline repository requires TenantId constructor/argument and never offers global find to web service. The mutante fetches by ID then policy, leaks/timing/log. Same-ID negative tests and affected rows. Foreign keys composite prevent cross-tenant relations. Cache/job/search/provider follow tenant. Admin repository separate/break-glass. Database session tenant variable if RLS transaction-scoped/reset in pool. Prepared query plan/index begins tenant. Enumeration response uniform. Bulk predicates. No body tenant. Authorization remains above binds.",
    "### Incidente, aceite e fontes\nOrder was interpolated, bindParam reused reference and generic integrity error replayed wrong row. O baseline closed SQL structure, explicit binds/map and constraint-specific translation. Mutants fail injection corpus, type/list boundaries, partial row and cross-tenant. PHP PDO/driver/database docs are sources. Aceite executes target engine/role with SQL/state/plan evidence. Without PHP/driver examples draft. Banca doesn't call prepared statement complete SQL safety or SQLite target locking proof.",
  ],
  "Transactions e isolation": [
    "## Transactions e isolation\nPDO transaction belongs to one connection and database; it does not include HTTP/provider/cache/queue. O baseline transaction closure performs conditional capacity, intent/reservation/outbox only, then commit before external delivery. The mutante opens transaction in controller and calls remote while locks held. Fault/load test pauses provider and inspects locks/pool. Autocommit and implicit DDL commit differ by DB. Begin/commit/rollback return/errors checked. Nested methods cannot independently begin unless savepoint wrapper. Connection released finally. Response success after commit known. Commit connection loss leads Unknown/readback tenant/key, not blind repeat.",
    "### Isolation phenomena\nRead committed/repeatable read/serializable definitions and defaults differ. O baseline states property needed and tests target with two sessions: last-seat atomic update, same-key unique, write skew if relevant. The mutante sets isolation string unsupported or assumes transaction serializes read-check-write. Tests barrier, connection IDs, SQLSTATE/final invariant. Higher isolation can abort and requires whole-transaction retry. Gap locks/phantoms/database specifics. Snapshot/read replicas. Conditional DML/constraints often simpler. Explain lock footprint/index. Isolation set before transaction per driver. Evidence version/config. Unsupported gate Pending.",
    "### Last-seat atomic update\n`UPDATE shows SET available=available-:q WHERE tenant_id=:t AND id=:id AND available>=:q`; affected row 1 wins, 0 maps sold-out/not-found securely. Within same transaction insert reservation/outbox. O baseline two independent PDO connections barrier with capacity one, final zero/one/one. The mutante SELECT then UPDATE or PHP/FPM mutex. Tests exactly winner/loser, retries, third connection readback, no provider. Check constraint nonnegative. Deadlock ordering. Query plan index tenant/id. Quantity validated. Rollback winner scenario. Repeated fixture namespace. RowCount semantics target verified. No sleep synchronization.",
    "### Retry and identity\nDeadlock/serialization may be retried with bounded attempts/jitter, but entire unit and stable command IDs/fingerprint. O baseline creates event/command identity outside retry and transaction callback has no external side effects. The mutante regenerates ID or retries only final insert. Tests injected/real deadlock, attempts and one state/outbox. Unique same key after ambiguous commit triggers readback. Validation/conflict/permanent no retry. Connection reset/reacquire after failure. Deadline global. Logging attempts no secret. Backoff outside transaction/connection. Retry storm control. Framework/library automatic retry not stack invisibly. Metrics attempt vs operation.",
    "### Savepoints and nesting\nPDO lacks universal nested transaction; wrappers may count and use savepoints, with driver caveats. O baseline top-level service owns unit; inner repository doesn't commit. Savepoint used only if semantic partial rollback intended/tested. The mutante inner commit ends outer or counter says rolled back while DB aborted. Tests inner exception caught, outer behavior and DDL. Naming generated trusted. Transaction status after error. Avoid swallowing and continuing PostgreSQL aborted transaction. Events/outbox rollback with savepoint according requirement. No provider. Contract declares `transaction(callable)` reentrancy policy. Static analyzer/design prevents surprise. Target DB gate.",
    "### Multiple databases and replicas\nTwo PDO connections/databases cannot be atomically committed without distributed protocol; Rails-like illusions absent. O baseline chooses source of truth and outbox/saga, not dual-write hope. The mutante writes DB then broker/second DB and loses window. Tests fail between. Replica read lag means immediate receipt reads primary/sticky. Tenant routing/shards explicit and identity mapping. Cross-shard operation orchestrated. Connection pools per target bounded. Backup/restore consistency across stores. Read-only role. Analytics async. No transaction object shared across process/job. Exactly-once claim narrowed. Reconciliation.",
    "### Observabilidade e orçamento de bloqueio\nA transação recebe operation ID, nome estável e orçamento menor que o deadline HTTP; métricas distinguem espera por conexão, tempo aberto, espera por lock, tentativas e resultado do commit. O baseline alerta por p95/p99 e por idade da transação, correlaciona SQL seguro sem registrar parâmetros sensíveis e captura o grafo de deadlock oferecido pelo banco. O mutante mede apenas a duração total da rota, ocultando fila no pool e lock. Testes de carga usam duas conexões reais, barreira determinística e consulta administrativa para provar que nenhum request aguarda uma chamada externa. Cancelamento fecha statement, desfaz a unidade e devolve a conexão limpa; timeout não transforma resultado desconhecido em falha segura. Runbook define como localizar blocker, preservar evidência, interromper com menor impacto e reconciliar comando ambíguo antes de qualquer replay.",
    "### Incidente, aceite e fontes\nRemote call held lock, read-check-write oversold and retry changed event ID. O baseline short local transaction, atomic predicate and stable identity. Mutants fail two-session, failpoints, deadlock and dual-write window. PDO/database isolation/lock docs are sources. Aceite records connections/isolation/SQL/state/outbox. Without target engine examples draft. Banca doesn't call transaction callback distributed atomicity or serializable no-retry guarantee.",
  ],
  "Modelagem, migrations e constraints": [
    "## Modelagem, migrations e constraints\nSchema is executable domain protection shared by all writers. O baseline chooses types/null/default, PK/FK, unique/check, tenant composite relations and indexes from queries. The mutante relies only application validation. Catalog tests and malicious direct insert verify. Money decimal/minor, IDs, timestamps timezone semantics, status check. Name constraints explicit for error mapping. Charset/collation. Foreign key delete actions match lifecycle. JSON only for flexible versioned payload, not replacing relational invariant. Runtime role no DDL. Schema dump/migrations versioned. Real DB because support differs.",
    "### Migration discipline\nMigrations immutable after applied, ordered, tested empty and upgrade from supported state. O baseline separate migrator, preflight/timeouts/locks, expand-contract for mixed fleet. The mutante edits old migration or drops/renames same release. Gate old/new app against intermediate schema. Schema dump matches catalog. DDL transaction/implicit commit differences. Backfill separate resumable batches, no current domain model/callback. Rollback/data loss explicit. Migration failure inspected. One runner coordination. Version in readiness. No migrations every FPM worker boot. Dry-run/query. Replica lag/storage. Artifact links.",
    "### Unique and idempotency\nUnique `(tenant_id,idempotency_key)` durable concurrency gate; store fingerprint version, event/reservation IDs and receipt/status. O baseline insert, catch named constraint, read winner and compare fingerprint. The mutante validation/select or any unique means replay. Tests simultaneous equal/divergent/cross-tenant, winner commit/rollback. Canonical version. No Hash unstable. Retention/key reuse. Error doesn't leak original. Provider stable ID. Restored schema/data retains. Index collation/case semantics. Key size/index. Partial unique where lifecycle. Upsert not overwrite divergent. Affected rows/result target verified.",
    "### Foreign keys and tenant integrity\nA reservation tenant/show must align. Simple FK show_id proves existence but not tenant match; composite unique/FK `(tenant_id,id)` or trigger/RLS/design can enforce. O baseline tests cross-tenant direct insert/update. The mutante controller scopes but background/SQL bypass creates relation. Association deletes restricted/anonymized. Cycles/deferred constraints understood. Bulk load ordering. Constraint validation staged for legacy rows. Index supporting FK. Error mapping not expose. Tenant deletion workflow preserves obligations. Admin operations audited. Restore validates orphans. ORM metadata aligned. No disabling FK globally in test/prod.",
    "### Check, null and generated values\nCheck constraints enforce quantity/capacity/status/conditional receipt where DB supports, but SQL NULL three-valued logic requires NOT NULL too. O baseline expresses `available >= 0`, status vocabulary, sent→receipt as appropriate. The mutante check `quantity > 0` but null passes. Tests null/boundary/future. Generated/default timestamps/IDs source known. Application and DB clock differences. Enum database type evolution tradeoffs. Constraint NOT VALID then validate. Error name. No business involving external state in check. DB-specific syntax documented. Restore/migration. Validation message UX separate. Direct writes.",
    "### Index and query plans\nIndex follows tenant predicates, equality/range/order and uniqueness, with write/storage cost. O baseline EXPLAIN representative distribution and concurrent/online creation capability. The mutante indexes every field or misses tenant prefix. Tests plan properties with stats, not exact unstable text. Partial/function/collation semantics. Covering index/read tradeoff. Slow query metric. Remove only evidence. Build locks/time. Index doesn't authorize. Keyset pagination. Outbox pending index. Unique also invariant. Bloat/maintenance. Production version. Migration rollback. Query shape from repository.",
    "### Verificação pós-migração e recuperação\nAplicar sem erro não basta: o pipeline compara versão registrada, catálogo efetivo, constraints validadas, índices utilizáveis e amostras de invariantes antes de liberar a nova frota. O baseline executa smoke de leitura e escrita com a role de runtime, confirma que ela não possui DDL e mede lock, duração e replica lag. O mutante confia no exit code do migrator e descobre depois que um índice ficou inválido ou uma constraint permaneceu não validada. Backups usados no plano são restaurados periodicamente em ambiente isolado e percorrem todas as migrations suportadas. Um checksum detecta arquivo histórico editado, mas a correção sempre vem em nova migration. O runbook declara ponto de não retorno, estratégia de forward fix, preservação de dados e como retirar um nó incompatível sem improvisar downgrade destrutivo.",
    "### Incidente, aceite e fontes\nApp validation raced, FK allowed cross-tenant show and check let null through. O baseline constraints/catalog/direct-negative and mixed migrations. Mutants fail concurrent/direct insert, old/new and plan. Database/migration tool/PDO docs are sources. Aceite queries catalog and final state on target. Without engine examples draft. Banca doesn't call ORM schema durable or migration success zero-downtime proof.",
  ],
  "Repositories, mapping e ORM": [
    "## Repositories, mapping e ORM\nRepository presents domain-specific persistence operations, not generic CRUD/query leakage. O baseline requires TenantId and methods like reserveCapacity, findIntent, saveReservation/outbox within provided transaction. The mutante `find($id)` global or returns query builder to controller. Interface/outcomes and shared contracts. Implementation uses PDO/ORM but domain independent. No hidden commit. Mapping validates row. Bulk/read models separate. Unit fake obeys contract or limitations. Production graph. Errors translated. Query ownership. Repository doesn't call provider/cache unexpectedly. Idempotency protocol cohesive. Metrics template.",
    "### Mapping rows and types\nPDO rows are arrays of strings/null/driver types. Mapper requires exact columns, strict parses int/decimal/time/enum and reconstructs entity without creation event. The mutante `(int)` invalid, defaults missing or hydrates setters. Tests corrupt/legacy/future/null/overflow. Database ID string. Date UTC. JSON payload schema. Row tenant matches scope. Unknown status explicit. Missing column programmer/migration error, not domain absence. Read DTO for projection. No reflection arbitrary fields. Map errors include safe table/id token, not data. Roundtrip insert/read. Encoding. Immutable copies. Lazy relations avoided.",
    "### Identity map and unit of work\nORM identity map ensures one object per row per unit, but long-lived process can retain stale/tenant objects. O baseline request/job scope clears; transaction reads/locks/reloads appropriately. The mutante global EntityManager/static cache across FPM requests. Sequential alpha/beta/revocation tests. Unit of work flush can defer SQL and exceptions; service knows flush/commit boundary. Callbacks not remote. Bulk DML bypasses UoW/callback and clears/reconciles. Memory batches detach. Optimistic version. No entity crossing queue. Repository returns fresh/read model where required. Cache external separate. Rollback in-memory object may remain changed—reload/discard.",
    "### Query builders and SQL escape\nORM builder values parameterized, but dynamic identifiers/DQL/raw fragments still injection. O baseline closed sort/filter mappings and tenant root scope. The mutante uses raw order from request or disables global scope. Tests inspect SQL/binds/result with malicious corpus. Eager/lazy N+1, joins/cardinality and projections. Pagination order total. Query count/plan. ORM default filters defense-in-depth not only tenant control; explicit repository. Native query isolated. Criteria limits. NULL semantics. Soft delete. Admin repository. No serialization lazy proxy. Query builder never leaves persistence boundary.",
    "### Transactions and domain events\nService/transaction runner coordinates repository calls. Entity may record domain events in memory; repository/outbox persists them in same transaction then clears only after commit. The mutante dispatcher sends before commit or clears event before failed commit. Failpoint tests. ORM lifecycle callbacks restricted local deterministic. afterFlush/postPersist complexities avoided/reviewed. Event ID stable. Retry creates entity/events once per attempt carefully; command identity. Aggregate optimistic lock/conditional SQL. Outbox payload mapper. No framework event equals domain durability automatically. Rollback discards unit. Integration verifies rows/outbox.",
    "### Caching and read models\nRepository source of truth; cache decorator tenant/policy/version namespaced, stores DTO not entity. The mutante caches global ID or serializes ORM proxy. Collision/revocation/invalidation tests. Read model optimized SQL separate from aggregate writes and eventual semantics stated. Cache miss load scoped. Stampede protection. Restore/cache namespace. Search/analytics async. Counts/counters reconcile. Query result pagination. Authorization before/within query. No stale object used for destructive transition without version/lock. Metrics. Store outage policy. Shared contract plus store gate.",
    "### Contract tests do adaptador real\nO mesmo conjunto de cenários roda contra cada implementação suportada: criação, releitura, ausência, conflito de versão, tenant homônimo, rollback, constraint e linha deliberadamente corrompida. O baseline gera IDs e namespace por execução, consulta o banco por uma conexão independente e limpa somente seus próprios dados; assim, um fake rápido continua útil, mas não certifica SQL, mapping ou isolamento. O mutante compara apenas chamadas de mock e aceita um adaptador que esquece o filtro de tenant. A suíte registra versão do driver, servidor, schema e configuração relevante, e marca Pending quando a infraestrutura real não existe. Tempos e quantidade de queries recebem limites explícitos para revelar N+1 sem congelar planos frágeis. Qualquer diferença permitida entre ORM e PDO aparece no contrato, em vez de ser escondida por expectativas condicionais.",
    "### Incidente, aceite e fontes\nGeneric find leaked tenant, mapper cast corrupt row and long-lived identity map served stale object. O baseline scoped repositories, strict mappers and bounded UoW. Mutants fail same-ID, corrupt row, sequential worker and failpoint events. PDO/ORM/database docs are sources. Aceite runs real adapter and contract/state readback. Without runtime/driver examples draft. Banca doesn't call repository interface tenant proof or ORM transaction outbox guarantee.",
  ],
  "Namespaces e Composer autoload": [
    "## Namespaces e Composer autoload\nNamespace identifica símbolos; diretório é uma convenção verificada pelo autoloader, não uma fronteira de segurança. O baseline usa um vendor prefix estável, PSR-4 sem sobreposição ambígua e uma classe principal por arquivo, com casing idêntico ao caminho para funcionar em filesystem sensível a maiúsculas. O mutante depende do Windows tolerante e quebra no Linux. O gate cria autoload otimizado em ambiente limpo, instancia entry points e procura símbolos duplicados. Arquivos carregáveis apenas declaram classes, interfaces, enums e funções deliberadas: não conectam banco, leem ambiente, registram handler global nem executam migration. Side effect no load torna preload, testes e análise imprevisíveis. O composition root realiza o bootstrap explicitamente.",
    "### PSR-4, classmap e files\nO mapping PSR-4 associa prefixo a raiz e remove o prefixo para resolver o caminho. Prefixos mais específicos, múltiplas raízes e fallback precisam intenção documentada. O baseline evita fallback global e exclui tests/fixtures do pacote de produção. Classmap é útil para legado e otimização, mas pode mascarar caminho incorreto; `files` executa código em todo request assim que o autoloader entra. O mutante coloca configuração e funções com estado em files. Testes constroem pacote, inspecionam mapa e carregam em processo novo. Funções auxiliares puras ainda precisam nomes, compatibilidade e ausência de colisão. Dev autoload fica separado. Um namespace não autoriza classe recebida por string: registries fechados continuam necessários.",
    "### Autoload otimizado e authoritative\nProdução pode otimizar mapas e usar authoritative mode para não sondar filesystem por classes inexistentes. O baseline gera `vendor/autoload.php` no build, depois testa o mesmo artefato; não monta source ou roda dump no boot. O mutante copia vendor antigo, altera source após dump ou confia em geração dinâmica de classes. Gate verifica que handlers/controllers/jobs realmente resolvem, inclusive proxies legítimos quando o framework exige. APCu cache e OPcache têm lifecycle separado e namespace/release precisa impedir mapa antigo. O artefato inclui hash do lock e do autoload. Uma classe ausente é falha de build/deploy, não motivo para baixar pacote em runtime. Readiness pode instanciar um conjunto mínimo sem executar efeitos externos.",
    "### Casing, conflitos e preload\nPHP trata nomes de classe de modo historicamente permissivo em alguns usos, mas arquivos Linux não; git e archives também preservam mudanças de case de formas distintas. O baseline executa verificação de PSR e build em ambiente equivalente ao destino. O mutante mantém `src/service.php` para `App\\Service`. Dois pacotes não podem declarar o mesmo símbolo; replace/provide do Composer não resolve colisão acidental. Preload executa arquivo uma vez no processo mestre e exige código seguro, dependências ordenadas e restart para nova versão. Não inclui conexão, container request-scoped ou segredo. Teste inicializa dois workers/reloads e confirma release identity. Classes preloadadas devem pertencer exatamente ao artifact implantado.",
    "### Boundaries e arquitetura\nNamespaces comunicam módulos, mas dependências são policiadas por regras de importação, interfaces e testes arquiteturais. Domínio não importa PDO, framework HTTP ou container; adapters dependem da porta interna. O baseline mantém API pública pequena e usa `internal` por convenção/ferramenta quando aplicável. O mutante cria namespace `Utils` que vira acoplamento universal. Um relatório de dependências detecta ciclos, imports proibidos e framework vazando para entidades. Aliases temporários de migração têm prazo e teste. Reflection e serialização que persistem nomes de classe tornam rename uma migração de dados. Jobs usam tipo/version de mensagem, não FQCN arbitrário. Plugin discovery usa manifest assinado/allowlisted, nunca input do request.",
    "### Diagnóstico e evidência\nFalha de autoload registra símbolo e release, não paths secretos completos. `composer dump-autoload` com flags de produção, validação do pacote e um script de smoke formam evidência; sucesso no editor não conta. O baseline roda sem dev dependencies e com permissões equivalentes ao container. Mutantes removem uma entrada do mapa, trocam casing, introduzem efeito num arquivo e solicitam classe hostil; os gates devem falhar antes de tráfego. Medidas incluem tempo de bootstrap e misses, mas otimização não justifica mapa incorreto. Runbook distingue class not found por artefato, cache de bytecode antigo e configuração de plugin. A correção troca release de modo atômico e recarrega workers, sem editar vendor no host.",
    "### Incidente, aceite e fontes\nUma classe carregava configuração e abria PDO; no preload, o processo mestre herdou recurso inválido e todo worker falhou. Outro pacote passou em Windows e não encontrou arquivo no Linux. O baseline mantém declarations sem efeitos, casing exato e build authoritative testado. Aceite valida composer metadata, autoload prod, preload quando usado, processo novo e grafo de imports. Documentação Composer, PSR-4 e runtime PHP são fontes primárias; comportamento de framework recebe gate próprio. Sem PHP/Composer instalados, os exemplos permanecem draft e não são chamados executados. A banca não confunde namespace com sandbox, classmap otimizado com pacote íntegro, nem `class_exists` verde com composition root correto.",
  ],
  "Composer lock e supply chain": [
    "## Composer lock e supply chain\n`composer.json` expressa faixas e requisitos; `composer.lock` fixa versões, fontes, dist hashes e resolução concreta. Aplicação versiona o lock e produz artefato com `composer install`, nunca update no deploy. O baseline resolve mudança em revisão separada, compara lock e executa suíte na plataforma-alvo. O mutante deixa o servidor escolher a versão mais nova durante incidente. `--no-dev`, scripts, plugins, plataforma, prefer-dist e otimização são opções do build registradas. Lock não fixa imagem base, extensões ou repositório mutável sozinho; o manifest do artefato inclui esses elementos. Reprodutibilidade é demonstrada reconstruindo e comparando conteúdo relevante, não apenas por existir um arquivo lock.",
    "### Resolução e plataforma\nComposer resolve PHP, extensões, packages, conflicts, replace/provide e estabilidade como um grafo. O baseline declara versão mínima e extensões realmente usadas, configura platform somente para representar o destino e ainda executa `check-platform-reqs` no runtime real. O mutante falsifica ext disponível para resolver e descobre em produção. Constraints estreitas demais impedem patches; largas demais aceitam breaking não semântico. Prefer-stable/minimum-stability exigem justificativa. O diagnóstico usa `why`, `why-not` e árvore, sem apagar lock. Matriz testa versões suportadas, inclusive menor constraint quando biblioteca. Extensão opcional tem adapter/capability explícita. Polyfill não promete desempenho ou semântica nativa idêntica. Arquitetura/OS e biblioteca compartilhada também entram no gate.",
    "### Scripts, plugins e código durante install\nScripts e plugins Composer executam código com privilégios do build; são dependência ativa, não metadata passiva. O baseline allowlista plugins, fixa versões, revisa scripts e usa credenciais efêmeras somente quando necessário. O mutante aceita plugin novo interativamente ou executa script de pacote desconhecido com token amplo. CI começa com instalação sem segredos quando possível, rede restrita e workspace descartável. Scripts de aplicação são determinísticos e não migram produção nem telefonam para terceiros. Um gate compara alteração de scripts/plugins no diff do lock. `--no-scripts` pode apoiar inspeção, mas o artefato final precisa executar scripts exigidos e testar seus outputs. Cache guarda downloads verificados, não substitui origem/provenance.",
    "### Auditoria, advisories e resposta\nAuditoria cruza versões com advisories, mas ausência de alerta não prova segurança e alerta exige alcance/contexto. O baseline roda audit no update e periodicamente, bloqueia severidade conforme política e registra exceção com owner, prazo e mitigação testada. O mutante ignora tudo ou atualiza major às pressas sem suíte. Inventário/SBOM liga package a artefato implantado; scanner de source sem release identity não localiza exposição. Incidente determina versões afetadas, reachability, secrets acessados e necessidade de rotação. Patch constrói novo artifact; editar vendor quebra provenance. Feed e timestamp ficam registrados. Pacote abandonado ou sem manutenção entra em plano de substituição. Fork interno carrega responsabilidade de patches e namespace/versionamento claros.",
    "### Repositórios privados e autenticação\nRepositórios privados usam HTTPS/SSH verificados, domínio fechado e credencial de leitura curta. O baseline injeta auth como secret do build, impede que `auth.json`, token ou URL credenciada entre em layer, log, SBOM ou cache exportado. O mutante grava token em composer.json ou ARG de container. Teste inspeciona histórico e arquivos finais com corpus de canários. Dist/source origin e commit/tag precisam imutabilidade; tag movida invalida confiança. Mirror interno tem sync, retenção, assinatura/attestation e resposta a revogação. Falha de rede não autoriza cair silenciosamente em pacote público homônimo. Package names são reservados e repository priority revisada para conter dependency confusion.",
    "### Atualização controlada e rollback\nBot ou pessoa abre mudança pequena com json/lock, changelog, advisories, API diff e testes. O baseline separa update de refactor, mede comportamento e mantém rollback do artefato anterior compatível com dados. O mutante agrupa dezenas de majors e só observa cobertura. Atualização de transitive pode alterar serialização, TLS, SQL ou clocks; contract/integration gates cobrem fronteiras relevantes. Canary registra release/package set. Se rollback de código não for compatível com migration, usa forward fix ou flag previamente desenhada. Lock merge conflict nunca é resolvido manualmente escolhendo trechos: repete-se resolução a partir do json aprovado e revisa-se o diff. Renovação periódica reduz salto, mas não substitui evidência.",
    "### Incidente, aceite e fontes\nDeploy executou update, baixou release recém-publicada e um plugin leu credencial do ambiente. O baseline instala lock revisado em builder isolado, limita plugin/script, verifica plataforma, audit e ausência de secrets no artifact. Mutantes removem lock, falsificam extensão, introduzem pacote público homônimo e canário secreto; gates devem barrar. Aceite registra comandos, versões, hashes, SBOM, audit e testes do artefato. Composer e advisory providers oficiais são fontes; blogs apenas contextualizam. Sem toolchain/rede controlada, exemplos ficam draft. A banca não chama lock uma assinatura, audit verde uma prova de ausência de vulnerabilidade, nem SemVer uma garantia de comportamento.",
  ],
  "Container e dependency injection": [
    "## Container e dependency injection\nDependency injection torna dependências exigidas visíveis no construtor; container apenas monta o grafo no composition root. O baseline cria config validada, clock, logger, PDO, repositories, provider e services explicitamente por ambiente. O mutante injeta container inteiro e busca serviços no meio do domínio, escondendo dependências e permitindo fallback. Interfaces ficam onde o consumidor precisa da abstração, não para cada classe. Objetos de domínio não conhecem PSR container. Factories tratam criação variável com input fechado. O teste de production graph sobe o mesmo wiring do artefato sem fazer efeitos destrutivos e confirma classes concretas, scopes e configuração. Autowiring economiza repetição, mas ambiguidades e scalars recebem binding explícito.",
    "### Lifetimes e scopes\nSingleton, worker, request, transaction e operação são lifetimes distintos. Em FPM tradicional, memória pode sobreviver no processo; em servidores long-lived, a diferença é crítica. O baseline mantém config/clients seguros no worker e identity, unit of work, request e buffers em scope reiniciado sempre. O mutante registra repository com EntityManager request-scoped como singleton e vaza tenant. Testes sequenciais alpha/beta no mesmo processo e após exceção revelam retenção. Factory de PDO/pool devolve conexão limpa; transaction nunca entra em singleton global. Lazy service precisa preservar lifetime, não capturar request antigo. Destruição/cleanup não depende apenas de GC. Container compilado lista scopes e rejeita dependência de vida longa apontando para vida curta.",
    "### Config e factories tipadas\nEnvironment é lido uma vez na borda e convertido em value objects; serviço não chama getenv quando decide. O baseline distingue missing, vazio, inválido e secret, valida relações como pool versus workers e passa configuração mínima. O mutante injeta array genérico ou string DSN em toda classe. Factory fechada seleciona adapters por enum de deployment, falha para valor desconhecido e não aceita FQCN remoto. Credenciais não aparecem em exception/toString. Rotação usa provider com contrato/lifecycle quando necessária, sem espalhar leitura. Testes exercitam cada variante suportada e config negativa. Default só existe quando seguro e documentado. Feature flag tem owner, expiry e comportamento nos dois lados.",
    "### Production graph e test doubles\nA suíte unitária pode fornecer doubles manuais, mas o grafo de produção deve ser testado. O baseline proíbe fallback para in-memory fora de test/local e expõe diagnostic seguro com adapter class, servidor e release. O mutante captura exception de PDO e silenciosamente constrói repository de memória. Smoke resolve handlers/jobs, verifica que todas as interfaces têm binding único e executa probe não destrutivo. Contract suites mantêm fake e real alinhados, documentando limites do fake. Mock do container é sinal de design escondido; injeta-se a porta direta. Decorators de cache/telemetria preservam ordem e semântica. Um teste mutante troca binding real pelo fake e precisa falhar.",
    "### Ciclos, lazy e side effects\nCiclo de construtores indica responsabilidades misturadas ou evento mal colocado. O baseline quebra ciclo com orquestrador/porta e usa lazy apenas para custo ou dependência realmente opcional. O mutante resolve ciclo fazendo setter injection em objeto parcialmente válido. Construção não chama rede, inicia transaction ou registra shutdown inesperado; bootstrap executa warmup/probes em fase explícita com timeout. Provider client pode ser criado sem request remoto. Proxy lazy precisa ser compatível com final/readonly e serialização. Falha de construção encerra readiness, não deixa grafo parcial. Ordem de decorators é testada: autorização e tenant scope não podem ficar depois de cache global. Event dispatcher recebe handlers fechados e auditáveis.",
    "### Observabilidade e inspeção segura\nContainer compilado ou mapa de serviços ajuda diagnosticar, mas dump público pode revelar classes, paths e config. O baseline produz manifesto sanitizado de bindings críticos e hash do grafo no build. Métricas identificam adapter por vocabulário limitado, jamais DSN. Startup registra apenas capabilities não secretas. Teste compara manifesto aprovado, instancia duas requests e observa reset. Em incidente, operador consegue responder qual implementation atende repository/provider e qual scope possui, sem editar código. Alteração no grafo exige review como alteração de comportamento. Performance mede compile/start e memória; service locator cache não é otimização aceitável. O runbook cobre cache de container antigo e restart atômico.",
    "### Incidente, aceite e fontes\nProdução caiu silenciosamente para repository em memória e singleton reteve identidade do request anterior. O baseline usa composition root explícito, config tipada, bindings sem fallback e scopes resetáveis. Mutantes trocam adapter, removem reset, criam ciclo e solicitam classe por config hostil. Aceite compila e sobe production graph, executa sequência multi-tenant, failure cleanup e contract real. Documentação do container/framework, PSR e PHP lifecycle são fontes. Sem runtime, exemplos são draft. A banca não chama constructor injection suficiente quando container vaza, autowiring prova de binding correto ou singleton sinônimo de stateless.",
  ],
  "Bibliotecas e compatibilidade": [
    "## Bibliotecas e compatibilidade\nUma biblioteca promete API, comportamento, requisitos e política de evolução a consumidores desconhecidos. O baseline define exports deliberados, menor PHP/ext suportado, estabilidade, error model e side effects; todo resto é interno mesmo que public por limitação da linguagem. O mutante publica classes de infraestrutura e depois as quebra em patch. SemVer orienta expectativa, mas não detecta mudança comportamental: testes de consumidor e release notes completam o contrato. Biblioteca não lê env global, instala handler ou abre conexão ao ser incluída. Defaults são estáveis e seguros. Tipos de parâmetros, retornos, exceptions, interfaces, traits, attributes, constants, serialização e named arguments fazem parte da compatibilidade quando expostos.",
    "### Superfície pública e evolução\nAdicionar parâmetro obrigatório, método a interface implementada por consumidores ou case a enum pode quebrar. Renomear parâmetro quebra named arguments; estreitar input ou ampliar exception também. O baseline mantém fixtures de código consumidor, análise de BC e matriz old-consumer/new-library. O mutante olha apenas testes internos. Novos métodos usam nova interface, capability ou major conforme contrato. Classes abertas à herança tornam protected/final/ordem de chamadas parte da API; preferir composição/final reduz superfície. DTO serializado precisa versionamento. Constantes podem estar inlined. Documentação marca thread/process safety, ownership e null semantics. Alteração compatível ainda pode exigir rollout coordenado por performance ou banco.",
    "### Deprecation e remoção\nDeprecation tem substituto, versão inicial, prazo/major de remoção e sinal testável. O baseline emite aviso apropriado sem segredo, oferece codemod/guia e testa caminho antigo e novo durante janela. O mutante remove silenciosamente ou gera warning em hot path milhões de vezes. Consumer CI trata novas deprecations de dependência de forma visível sem bloquear correção urgente indiscriminadamente. Alias/adaptor preserva semântica, inclusive exception e ordering. Métricas podem contar uso por nome bounded. Remoção ocorre somente no ciclo prometido, com migration notes. Método deprecated não delega de modo que duplique efeito. Uma flag temporária não substitui contrato de versão.",
    "### Extensões e polyfills\nRequisito nativo deve aparecer no Composer e no runtime check; comportamento varia por versão e build. O baseline isola extensão atrás de porta quando opcional e testa implementação nativa e fallback com vetores comuns. O mutante usa `function_exists` e assume equivalência de Unicode, crypto ou decimal. Polyfill tem limites documentados, performance e segurança avaliadas; primitive criptográfica nunca recebe fallback improvisado. FFI aumenta superfície e lifecycle. Tipos retornados por extensão, resources/objects e erros mudam entre versões. CI cobre menor e maior PHP suportados em sistemas relevantes. Se capability é obrigatória, falha no boot; degradar silenciosamente pode corromper dados.",
    "### Matriz e testes de consumidor\nBiblioteca testa combinações suportadas, não produto cartesiano infinito: menor/maior PHP, menor dependencies, latest estável e extensões-chave. O baseline roda instalação com prefer-lowest cuidadosamente, testes, análise estática e um projeto consumidor fixture. O mutante testa só lock do maintainer. Contract fixtures compilam named arguments, implementations de interfaces e serialização. Mutation cobre defaults e error mapping. Pacote de framework testa duas versões suportadas com suas configurações reais. Resultado Pending para combinação sem executor, nunca aprovado por inferência. EOL remove linha em major/política anunciada. CI registra versões efetivas e artifact, evitando badge verde sem contexto.",
    "### Release e provenance\nTag corresponde a commit revisado, changelog e artefato gerado por pipeline confiável; credenciais de publicação têm escopo e proteção. O baseline valida metadata, licença, arquivos incluídos, ausência de secrets/tests pesados e instalação limpa antes de publicar. O mutante publica do laptop com working tree suja ou inclui auth.json. Assinatura/attestation e checksum ajudam provenance, enquanto consumer ainda revisa confiança. Yanking é excepcional e comunicado; versão imutável evita reconstrução diferente. Pacote privado previne dependency confusion. Dry-run lista conteúdo. Após release, smoke instala pelo canal público numa aplicação mínima. Rollback publica correção nova, não move tag existente.",
    "### Incidente, aceite e fontes\nUma minor adicionou método obrigatório à interface, consumidores quebraram; outro host não possuía extensão usada só em produção. O baseline controla exports, usa análise de BC, fixtures consumidoras, matriz e platform requirements. Mutantes renomeiam named parameter, adicionam enum case e removem extensão; gates relevantes falham. Aceite instala tarball/dist limpo, executa matriz e compara API com release anterior. Documentação PHP, Composer, SemVer declarado pelo projeto e especificações PSR são fontes. Sem executores, exemplos ficam draft. A banca não chama SemVer mecanismo automático, testes internos prova de compatibilidade ou polyfill equivalência sem vetores e limites.",
  ],
  "Process model, FPM e state": [
    "## Process model, FPM e state\nPHP não possui um único modelo de execução. CLI termina após o comando; FPM mantém processos capazes de atender muitos requests; servidores long-lived e queue workers conservam o runtime por ainda mais tempo. O baseline identifica SAPI, servidor, quantidade de workers, política de recycle e o que realmente é reinicializado entre unidades. O mutante assume que toda variável estática morre ao final do request porque isso ocorreu no servidor embutido. Estado de negócio e coordenação ficam em banco, cache ou fila com contrato durável; memória local serve apenas a cache descartável e metadado imutável. Testes enviam tenants alpha e beta ao mesmo processo, provocam exceção e repetem a sequência para detectar identity, locale, transaction ou buffer retido.",
    "### FPM, workers e réplicas\nFPM distribui requests entre processos independentes; cada processo possui memória, conexões e OPcache compartilhado conforme configuração, mas um mutex ou static de um worker não coordena os demais nem outra réplica. O baseline calcula `pm.max_children` em conjunto com memória, pool do banco e limites do upstream. O mutante usa lock em arquivo local para proteger a última vaga e funciona em um host apenas. Gate concorrente dispara requests por conexões independentes e confirma invariante no banco. Reload gracioso deixa versões coexistirem por algum tempo, portanto schema e protocolo suportam frota mista. Afinidade de sessão não substitui store compartilhado. PID, worker/release e request ID entram em diagnóstico bounded, não na semântica de idempotência.",
    "### Globals, statics e registries\nSuperglobals pertencem à fronteira e são convertidas imediatamente em valores próprios. Globals, singleton mutável, static local e registry aberto acumulam contexto invisível. O baseline injeta dependências e usa request scope explicitamente resetado; caches estáticos só guardam dados imutáveis ou têm chave completa com tenant, policy version, locale e release. O mutante memoiza `find($id)` sem tenant ou conserva usuário autenticado no singleton. Testes alternam identidades com o mesmo ID, revogam autorização e verificam ausência de colisão. Closure pode capturar objeto de request e prolongar seu lifetime em callback/job. Handler global, timezone, locale e error reporting alterados precisam restauração em `finally` quando biblioteca não puder evitá-los.",
    "### OPcache, preload e memória\nOPcache compartilha bytecode, não objetos arbitrários da aplicação. Preload executa no processo mestre ao iniciar e suas classes permanecem até restart; arquivo de preload não pode abrir socket, ler tenant ou construir scope de request. O baseline liga release identity ao pool e reinicia de modo controlado depois de trocar artifact. O mutante sobrescreve arquivos in-place, deixando workers com conjuntos mistos. Teste de deploy consulta vários workers e exige digest esperado. Long-lived workers medem RSS ao longo de milhares de jobs, removem referências, fecham cursor e reciclam antes do limite. Garbage collector não corrige cache sem bound. Profiling distingue leak real, fragmentação, extensão nativa e retenção intencional.",
    "### Cleanup entre unidades\nToda unidade possui envelope: entrar com context novo, executar com deadline, finalizar telemetria, rollback se necessário e limpar scope mesmo sob Throwable. O baseline não reutiliza conexão com transaction aberta, session lock, temporary file, header buffer ou span corrente. O mutante captura erro, continua loop e entrega estado parcialmente contaminado ao próximo job. Testes injetam falhas depois de begin, mudança de locale, criação de temp e aquisição de lease; o segundo trabalho deve observar baseline limpo. Framework hooks ajudam, mas seu alcance é validado na versão real. Um worker que não consegue provar cleanup encerra e deixa supervisor substituí-lo. Shutdown handler não é garantia para kill abrupto e não realiza novo efeito externo.",
    "### Estado local permitido e observabilidade\nCaches locais de config parseada, metadata reflection ou cliente stateless podem reduzir custo quando possuem bound, invalidation por release e nenhuma identidade dinâmica. O baseline documenta owner, chave, tamanho, TTL e efeito de stale para cada cache. O mutante transforma qualquer singleton em otimização. Métricas por worker expõem requests/jobs atendidos, RSS, recycle, erros de reset, conexões e versão; labels usam vocabulário controlado. Readiness falha se release, extensão ou config divergir. Em incidente, operador diferencia um único worker contaminado de dado durável incorreto e pode drenar o pool sem perder obrigação. Heap dump e logs passam por controle de acesso porque podem conter payload e secret.",
    "### Incidente, aceite e fontes\nUm static armazenou autorização de alpha; o worker seguinte serviu o mesmo ID a beta. Um deploy in-place deixou metade do pool com classes antigas. O baseline usa scopes resetáveis, chaves contextuais, artifact imutável e reload observável. Mutantes removem reset, omitem tenant, mantêm transaction aberta e misturam release; sequências no mesmo processo precisam falhar. Aceite registra SAPI, servidor, política FPM, worker/release, estado externo e RSS de soak. Manuais PHP/FPM/OPcache e documentação do servidor utilizado são fontes primárias. Sem runtime apropriado, exemplos permanecem drafts. A banca não chama request stateless porque o código parece funcional, nem process-local lock uma garantia distribuída.",
  ],
  "Queues, retries e idempotência": [
    "## Queues, retries e idempotência\nUma fila comum entrega at-least-once: mensagem pode repetir após timeout, crash, redelivery manual ou perda do ack. O baseline define identidade estável do comando/evento fora da tentativa, fingerprint canônico, estágio observado e resultado durável. O mutante gera UUID no handler e cada retry vira operação nova. Producer persiste payload versionado e referência mínima; consumer valida tamanho, schema, tenant e autorização adequada ao contexto assíncrono. Idempotência não significa ignorar duplicata: mesma key e mesmo fingerprint retorna o outcome gravado; mesma key e comando diferente é conflito auditável. Testes publicam cópias simultâneas e sequenciais, matam o worker em cada fronteira e contam estado, efeito e receipt.",
    "### Payload e evolução\nMensagem carrega event ID, type, schema version, occurred/created time, tenant, aggregate ID, trace link e dados necessários sem objeto PHP serializado. O baseline usa JSON limitado com decoder estrito, allowlist de tipos e upcaster explícito quando a janela de compatibilidade exige. O mutante coloca FQCN/serialize e deixa autoload instanciar classe antiga ou gadget. Campos de segurança não são confiados cegamente; worker relembra policy ou usa snapshot deliberado conforme o caso. PII e secrets são minimizados, criptografados quando necessário e possuem retenção. Producer antigo e consumer novo, e o inverso durante rollout, recebem contract tests. Evento desconhecido vai para quarantine, não é marcado como sucesso.",
    "### Retry, backoff e classificação\nRetry serve falha transitória comprovada: timeout antes de efeito conhecido, rate limit, deadlock ou indisponibilidade. Validation, autorização, schema e conflito permanente terminam sem repetição. O baseline usa tentativas limitadas, exponential backoff com jitter, deadline total e `Retry-After` bounded quando confiável. O mutante reprocessa imediatamente e amplifica outage. Cada tentativa registra attempt, causa segura e próximo horário, enquanto operation ID permanece. Backoff ocorre fora de transaction e sem segurar lease/conexão desnecessariamente. Circuit breaker pode aliviar upstream, mas não perde item. Teste usa clock controlável e provider fake com transcript para provar agenda, máximo e preservação de ID. Retry manual segue o mesmo protocolo, não duplica mensagem cegamente.",
    "### Ack e fronteiras de falha\nAck confirma à fila que a obrigação foi tratada; se acontece antes do commit/efeito, crash perde trabalho; depois do efeito, crash pode repetir. O baseline combina outbox/inbox, idempotency key do provider e readback/reconciliation conforme capacidade. O mutante chama provider, depois marca banco e acredita em exactly-once. Matriz de kill points cobre antes/depois de claim, commit, request, response, receipt e ack. Resultado `Unknown` preserva investigação e não autoriza replay automático. Visibility timeout/lease excede p99 com heartbeat/fencing quando suportado, mas trabalho longo é dividido. Um ack falho após commit resulta em duplicata tratável, não em segunda cobrança. Evidência vem de estado independente, transcript e contagem de receipts.",
    "### Dead letter e operações\nDead-letter queue é quarentena operacional, não lixeira. O baseline preserva message ID, payload redigido/referência, schema, attempts, primeira/última falha e motivo classificado. Acesso é auditado; replay seleciona itens, valida versão e usa a mesma identidade original. O mutante exporta payload, edita ID e republica em massa. Runbook calcula blast radius, pausa consumer, corrige causa, testa amostra e aumenta gradualmente. Poison message não bloqueia partition inteira indefinidamente. Retenção combina obrigação legal e privacidade. Alertas usam taxa/idade, não label por ID. Ferramenta de redrive possui dry-run e limite. Delete só após prova de resolução ou decisão registrada, com reconciliação do source of truth.",
    "### Ordenação, concorrência e pressão\nOrdenação é normalmente por partition/key, não global. Se aggregate exige sequência, mensagem leva version e consumer faz compare-and-set, buffer bounded ou busca estado atual; duplicata antiga não regride. O baseline particiona por tenant/aggregate conforme hotspot e fairness, limita inflight por worker e propaga backpressure. O mutante lança concorrência ilimitada e esgota pool/provider. Testes embaralham, duplicam e atrasam eventos, incluindo tenant ruidoso. Concurrency do consumer se alinha a conexões e rate limit. Prefetch alto aumenta throughput e custo de redelivery. Métricas medem lag, age, inflight, retry, DLQ e resultado por tipo bounded. Escalar worker não corrige lock central ou provider saturado.",
    "### Incidente, aceite e fontes\nRetry gerou nova key depois de timeout e cobrou duas vezes; outro worker deu ack antes do commit e perdeu reserva. O baseline fixa identidade, classifica erro, posiciona ack e reconcilia outcome ambíguo. Mutantes alteram ID, ack antecipado, repetem permanent error e reordenam versão; gates com kill points devem falhar. Aceite registra configuração da fila, payload/schema, attempts, banco, transcript do provider e receipts. Documentação da fila/client library e contrato do provider são fontes. Sem broker/worker reais, exemplos permanecem drafts e não provam timing. A banca não chama DLQ tratamento concluído, retry disponibilidade automática ou idempotent consumer exatamente uma vez.",
  ],
  "Outbox, claims e fencing": [
    "## Outbox, claims e fencing\nTransactional outbox grava mudança de domínio e obrigação de publicar/enviar na mesma transaction local. O baseline cria event ID estável, tenant, aggregate, type/version, payload/referência, created time e status inicial junto da reserva. O mutante faz commit da reserva e depois tenta publicar, deixando janela de perda. Dispatcher é separado: seleciona itens elegíveis, faz claim concorrente, executa efeito fora da transaction de claim quando necessário e persiste receipt/outcome. Outbox não fornece exactly-once por si: crash depois do efeito e antes do registro repete; idempotency do destino ou reconciliação fecha essa janela. Testes interrompem cada fronteira e verificam que nenhuma obrigação some ou cria identidade nova.",
    "### Claim atômico\nDois workers não podem apenas `SELECT pending` e depois marcar; ambos verão a mesma linha. O baseline usa mecanismo do banco alvo: update condicional com token/version, `FOR UPDATE SKIP LOCKED` em transaction curta, ou claim atomically returned. O mutante depende de mutex PHP. Claim registra owner, lease_until, attempt e fencing token monotônico. A query inclui tenant/partition/status/time e índice correspondente. Teste inicia conexões independentes com barreira, exige conjuntos disjuntos e consulta final por terceira conexão. Batch é bounded e fair. Transaction de claim não envolve HTTP. Row count/returning/locking são validados no engine real; SQLite ou array não certifica PostgreSQL/MySQL.",
    "### Leases e fencing\nLease expira para recuperação de worker morto, mas relógio e pausa podem permitir owner antigo continuar. Fencing token faz toda gravação posterior aceitar somente geração atual; quando destino não suporta fencing, usa idempotency key e resultado readback. O baseline renova antes do vencimento com compare-and-set de owner/token e aborta ao perder ownership. O mutante prolonga trabalho e atualiza `sent` mesmo depois de outro worker reassumir. Teste pausa worker A, deixa B claimar e libera A; estado final deve refletir apenas owner válido e um efeito lógico. Tempo vem do banco/coordenador, não de relógios locais divergentes. Lease duration nasce de distribuição observada e deadline, não número mágico.",
    "### Estados e resultado desconhecido\nUma máquina explícita separa pending, claimed, dispatching, sent, retryable, failed e unknown conforme protocolo. O baseline persiste receipt do provider e fingerprint; transição usa expected state/token. O mutante representa tudo com boolean `sent`. Timeout após enviar é Unknown: primeiro consulta provider por stable ID; somente ausência autoritativa permite novo envio. Error mapping não converte toda exception em retry. Terminal failure mantém obrigação visível e decisão operacional. Cancelamento de reserva pode coexistir com evento já enviado e demanda compensação, não exclusão histórica. Check constraints limitam estados. Testes exercitam transição inválida, resposta perdida, receipt conflitante e provider que aceita mas demora para tornar consulta visível.",
    "### Reconciliation e anti-entropy\nReconciler procura itens antigos por estado/lease, compara source of truth, outbox e provider, e aplica decisão idempotente. O baseline usa cursor persistido, paginação keyset, budget e checkpoint; não varre tabela inteira em cada minuto. O mutante apenas reenvia todo pending antigo. Reconciliation também detecta reserva sem outbox por migração/bug histórico, outbox sent sem receipt e receipt externo sem estado local. Cada reparo registra reason, previous/current state e operator/job version. Dry-run e amostragem apoiam incidente. Índices por status/time e retenção/arquivamento preservam desempenho. Métricas medem age do item mais antigo, divergence e tempo para convergir. Restore sempre executa reconciliação antes de liberar delivery.",
    "### Payload, privacidade e retenção\nOutbox não vira depósito de PII. O baseline guarda identificadores e snapshot mínimo necessário, cifra campo sensível quando obrigação exige e define purge apenas após horizonte de replay/audit. O mutante copia request e headers inteiros. Payload tem schema version, size limit e canonical serialization; consumer desconhecido não desserializa classe. Tenant participa de chave, query, logs e provider mapping. Se evento precisa dado mutável, decide-se snapshot versus lookup e comportamento após delete. Backfill respeita rate limit. Arquivamento preserva prova de receipt e identity. Backup/restauração mantém unique keys e event IDs. Testes usam canários para impedir token/cookie em payload, logs e DLQ.",
    "### Incidente, aceite e fontes\nDois dispatchers selecionaram a mesma linha e enviaram duas notificações; worker pausado marcou sent após perder lease. O baseline usa claim atômico, fencing e identidade no destino, mais reconciliação para Unknown. Mutantes removem predicate, reutilizam token e apagam item falho; gates concorrentes/kill-point detectam. Aceite registra SQL/plan, conexões, tokens, timeline, transcript e estado final independente. Documentação do banco, broker e provider é fonte primária. Sem engine/broker real, exemplos ficam drafts. A banca não chama outbox exactly-once, `SKIP LOCKED` fairness automática ou lease exclusão suficiente sem fencing/readback.",
  ],
  "Fibers, event loops e async": [
    "## Fibers, event loops e async\nFiber permite suspender e retomar execução cooperativamente; não cria paralelismo, não torna uma função bloqueante não bloqueante e não fornece scheduler completo. Bibliotecas de event loop associam readiness/timers/promises a I/O compatível. O baseline identifica quais clients realmente usam sockets não bloqueantes e mede o loop sob carga. O mutante envolve cURL/PDO bloqueante em Fiber e anuncia concorrência. Cada operação recebe deadline/cancellation, context explícito e ownership de resources. Suspender dentro de transaction/lock conserva o recurso e amplia contenção, portanto I/O remoto ocorre fora da unidade local. Testes atrasam um peer e provam que timers e outras operações continuam; um benchmark de throughput sozinho não revela starvation ou perda de estado.",
    "### Context e isolamento\nGlobals e static não viram fiber-local automaticamente. Quando duas fibers intercalam, tenant, trace, locale ou transaction global pode ser trocado. O baseline passa context imutável ou usa mecanismo context-local comprovado, com enter/reset em `finally`. O mutante define `CurrentTenant::$id` antes de await e lê depois, já sobrescrito. Teste força ordem alpha-suspend-beta-resume e verifica queries/logs/provider. Objetos request-scoped não atravessam job futuro. Async callback captura somente dados necessários e stable IDs. Error handler e timezone globais continuam process-wide. Library wrapper documenta se propagação de context é suportada. Telemetria liga spans sem fazer ID de alta cardinalidade virar label.",
    "### Cancellation e deadlines\nCancellation é protocolo cooperativo: operação checa token, cancela timer/socket quando possível e libera resource exatamente uma vez. O baseline deriva deadlines filhos do orçamento restante, distingue timeout antes/depois de efeito e preserva Unknown. O mutante apenas abandona promise enquanto request continua no provider. Testes cancelam antes do envio, durante conexão, depois de headers e após resposta perdida; state/effect oracle decide outcome. `finally` fecha stream e devolve conexão limpa, mas não tenta compensação remota não idempotente. Timeout do proxy, PHP, client e provider são alinhados. Uma tarefa detached precisa owner, supervisão e durable obligation; fire-and-forget no request pode morrer no fim do worker.",
    "### Structured concurrency e erros\nTarefas filhas pertencem a um escopo: sucesso aguarda as necessárias, falha cancela siblings quando semântica permite e todos são joined antes de sair. O baseline limita fan-out e agrega erro por categoria sem perder stack/cause. O mutante cria promises em loop e esquece await, vazando exception e sockets. Operações independentes podem concorrer; duas mutações do mesmo aggregate exigem coordenação durável. Race/timeout combinators cancelam perdedores. Testes provocam uma falha, uma demora e uma resposta, conferindo cleanup e que nenhum efeito órfão continua. Unhandled rejection/exception termina job de forma observável. Supervisor aplica retry no nível da operação, não em callback parcial.",
    "### Backpressure e pools\nLoop rápido pode criar mais trabalho que banco, DNS, sockets ou provider suportam. O baseline usa semaphore/bounded queue, pool dimensionado e admission control; concurrency é menor ou igual ao recurso mais restrito. O mutante dispara dez mil fibers e só limita memória do PHP. Testes de overload medem fila, lag, RSS, sockets, timeouts e estado final, mantendo fairness por tenant. Producer desacelera ou rejeita cedo com contrato; não acumula closure ilimitada. Pool de conexão não é compartilhado simultaneamente por fibers se driver não suporta multiplexação. Streaming aplica janela e fecha cursor. Métricas evitam uma label por coroutine. Ajuste nasce de soak e capacidade, não de contagem de CPU isolada.",
    "### Compatibilidade e adapters\nAmp, ReactPHP, Swoole e outros runtimes possuem APIs e lifecycle diferentes; código do domínio depende de portas de clock, HTTP e scheduler quando necessário. O baseline escolhe uma stack, fixa versões e executa tests nela, sem misturar promise types invisivelmente. O mutante chama biblioteca sync dentro de adapter declarado async. Bridge sync/async define se bloqueia e onde é permitido. Extensão/event loop pode alterar signal handling, globals e hooks do framework. Readiness registra backend. Contract test mede que duas esperas realmente se sobrepõem e que cancelamento alcança socket. Fallback síncrono é opção explícita com capacidade distinta, não degradação silenciosa. Profiling inclui tempo no loop e callbacks lentos.",
    "### Incidente, aceite e fontes\nUma Fiber suspendeu com transaction aberta e outra operação bloqueou o pool; static de tenant foi sobrescrito entre resumes. O baseline mantém transactions curtas, context isolado, cancellation e concurrency bounded. Mutantes usam client bloqueante, omitem await, vazam context e ignoram cancel; testes determinísticos/overload falham. Aceite registra runtime/extensões, scheduler, timeline, pool, resources e state/effect readback. Manuais PHP Fiber e documentação da biblioteca/client são fontes primárias. Sem runtime/event loop real, exemplos permanecem drafts. A banca não chama Fiber thread, sintaxe async prova de nonblocking ou timeout cancelamento de efeito.",
  ],
  "PHPUnit e unit contracts": [
    "## PHPUnit e unit contracts\nTeste unitário prova uma unidade e seus invariantes com colaboradores controlados; não prova integração com PDO, framework, filesystem ou rede só porque usa nomes reais. O baseline organiza Given/When/Then ou estrutura equivalente, um oracle observável e mensagens que explicam o contrato. O mutante espelha implementação, verifica cada chamada interna e quebra em refactor sem mudança de comportamento. Value objects, fingerprint, transitions e policy recebem casos de fronteira. Clock, ID generator e provider são portas injetadas, não globals substituídos. Cada teste cria seus próprios dados e não depende de ordem. Uma assertion principal pode ter várias verificações coerentes de um mesmo outcome. Cobertura indica execução, não correção; mutation e casos negativos testam força do oracle.",
    "### Data providers e fronteiras\nData providers expressam tabela de exemplos com nomes semânticos: mínimo, máximo, Unicode, null, tipo errado, overflow e variante futura. O baseline mantém expected legível e falha por caso; o mutante cria loop dentro do teste e só informa índice. Provider não consulta produção nem compartilha objeto mutável. Para parser, casos válidos e inválidos ficam separados porque seus oracles diferem. Valores como `0`, `false`, string vazia e ausência são preservados. Locale/timezone são fixados ou explicitamente variados e restaurados. Testes de floating point usam domínio/tolerância justificados, enquanto dinheiro usa minor units/decimal. Uma amostra não substitui property test quando espaço é amplo, mas documenta regras essenciais.",
    "### Doubles e limites\nStub fornece resposta; spy registra interação relevante; fake implementa protocolo simplificado; mock impõe expectativa. O baseline escolhe o double menor e testa resultado, estado e efeito contratual, não sequência privada. O mutante mocka entidade, DateTime ou PDO inteiro e cria mundo impossível. Provider fake modela timeout antes do efeito, sucesso com receipt e Unknown após aceitar. Repository fake inclui tenant, unique e version quando a unidade depende desses aspectos, ou documenta que o contract real cobre. Final classes não são problema quando porta está correta. Partial mocks e métodos mágicos escondem design. Double nunca é evidência do adapter real. Uma mutation que remove idempotency key da chamada precisa ser detectada por transcript/outcome.",
    "### Contract suites\nContract suite é conjunto reutilizável que toda implementação da porta deve satisfazer. O baseline usa factory/fixture abstrata para memory, PDO ou provider sandbox e declara capabilities/diferenças explicitamente. Cenários cobrem create/read, same ID across tenant, duplicate equal/divergent, version conflict, rollback e error mapping. O mutante roda contract somente no fake e chama interface validada. Dados recebem namespace único e limpeza restrita. Adapter real é observado por conexão/cliente independente. Quando infraestrutura não existe, resultado é Pending/skip com razão e gate separado obrigatório, não pass silencioso. Contract não deve exigir detalhes de SQL ou SDK; testes específicos do adapter cobrem isso. A mesma semântica de clock e IDs evita falsos desvios.",
    "### Exceptions e failure paths\n`expectException` deve envolver somente a chamada que pode falhar e verificar categoria/mensagem segura quando parte do contrato. O baseline testa que estado e efeitos permaneceram inalterados, cleanup ocorreu e causa foi preservada. O mutante marca teste verde porque setup lançou a mesma exception. Callbacks/fakes permitem failpoint exatamente antes/depois de mutation. Testes de retry verificam tentativas, IDs estáveis, backoff e ausência de retry para permanente. Resultado Unknown não é assertado como failed. Warnings/deprecations esperados são capturados e restaurados, nunca desligados globalmente. Um teste que não falha quando se remove rollback, tenant predicate ou authorization é insuficiente mesmo com coverage alto.",
    "### Organização, velocidade e determinismo\nUnit suite roda rápida, paralela e sem rede, banco compartilhado, relógio real ou sleep. O baseline injeta clock, usa IDs fixos/gerados por fixture e limpa globals em teardown/finally. O mutante aumenta timeout para esconder race. Seeds são registrados. Ordem aleatória e repetição detectam dependência; processo isolado só quando global inevitável. Fixtures builders mantêm defaults válidos e tornam variação visível. Snapshot textual é usado apenas para saída estável revisável, não para esconder centenas de campos. Logs não são oracle principal. Testes lentos são medidos e classificados, sem expulsar integração necessária. Nome descreve regra e condição, ajudando a localizar lacuna editorial e incidente.",
    "### Incidente, aceite e fontes\nMocks confirmaram `save()` chamado, embora transaction nunca commitasse e key mudasse no retry. O baseline testa outcome/estado, stable identity e contract real separado. Mutantes removem tenant, rollback, fingerprint comparison e exception mapping; pelo menos um teste apropriado precisa falhar. Aceite registra PHPUnit/PHP/config, seed e escopo de cada suite; coverage/mutation são evidências complementares. Documentação PHPUnit e PHP são fontes, junto do contrato da porta. Sem runtime, exemplos ficam drafts. A banca não chama mock integration, 100% coverage especificação completa, nem contract do fake prova do adapter de produção.",
  ],
  "Integration, HTTP e banco": [
    "## Integration, HTTP e banco\nTeste de integração atravessa componentes reais relevantes e nomeia o que ainda é fake. Para Quíron, baseline sobe bootstrap/DI de produção, stack HTTP, middleware, router, serializer e banco alvo descartável; provider externo pode ser stub com transcript se o foco termina nessa fronteira. O mutante chama controller diretamente com repository em memória e rotula end-to-end. Request passa por socket ou kernel oficial do framework, e state readback usa segunda conexão. Resposta sozinha não prova commit; linha sozinha não prova headers/cookies. Manifesto registra versões do PHP, extensões, driver, engine, schema e server. Infra ausente gera Pending explícito. Fixture nasce por migration real, não schema artesanal divergente.",
    "### Ambiente descartável e migrations\nCada execução recebe database/schema/namespace exclusivo, aplica migrations do zero e, quando suportado, faz upgrade de snapshot antigo. O baseline espera readiness específica, utiliza role da aplicação e destrói somente recurso nomeado. O mutante aponta para banco de desenvolvedor ou compartilha tabelas entre workers. Seed mínimo usa SQL/repository consciente das constraints e IDs únicos. Cleanup não mascara falha original. Timezone, collation, isolation e extension ficam alinhados ao destino. Migration gate inspeciona catálogo, índices e constraints. Container é opção, não requisito sem justificativa; engine local gerenciada também serve quando versão/protocolo são reais. Nunca instalar servidor apenas para afirmar que redação executou: primeiro há necessidade de gate e autorização operacional.",
    "### HTTP boundary\nCasos cobrem method/path/query/header/body/content type, limites de bytes, autenticação, tenant, CSRF/cookie quando aplicável e error envelope. O baseline envia duplicate headers, malformed UTF-8/JSON, body vazio/grande, content negotiation e proxy metadata conforme deployment. O mutante constrói array já parseado e ignora web server. Teste verifica status, headers, cookies, MIME e corpo, mais ausência de stack/secret. Redirect possui Location fechado. Streaming prova ownership e encerramento. Same-ID cross-tenant usa respostas uniformes e readback. Middleware ordering é exercitado com request rejeitado antes do handler. TLS/proxy real fica em staging/browser gate se harness local não o inclui, com alcance escrito.",
    "### Banco e concorrência\nPDO real valida binds, tipos, constraints, row count, errors e transaction. Concorrência usa duas conexões independentes e uma barreira determinística: ambas tentam a última vaga, exatamente uma vence, final capacity é zero e há uma reservation/outbox. O mutante executa sequencialmente ou usa duas references à mesma conexão. Teste de idempotência simultânea cobre payload igual e divergente. Failpoints provocam rollback e ambiguous commit quando harness suporta proxy/fault. Terceira conexão lê resultado depois do join. Plan/lock evidence complementa. Retry testa SQLSTATE específico no engine. SQLite não certifica locking/DDL de PostgreSQL/MySQL. Sem executor adequado, gate permanece Pending e conteúdo não recebe attestation falsa.",
    "### Provider, queue e browser\nSandbox/provider fake registra method, URL, headers redigidos, stable key, body e response, permitindo verificar uma chamada lógica. Queue integration usa broker real quando claim/ack/visibility são objeto; array fake só testa orchestration. Browser real prova cookie, CSP, escaping, CSRF e accessibility que client HTTP não enxerga. O baseline mantém testes em camadas com ownership claro, em vez de um E2E gigantesco instável. O mutante chama tudo E2E embora TLS, worker e provider estejam simulados. Dados sandbox são únicos, custo limitado e cleanup/reconciliation executado. Secrets de teste têm least privilege e nunca entram em artifact/log. Retry do test runner não esconde falha de produto.",
    "### Evidência e flakiness\nFalha preserva request ID, timeline, versões, SQL seguro, transcript e estado final, redigindo payload sensível. O baseline usa readiness e eventos/barreiras, não sleep; timeout é orçamento, não sincronização. Teste flaky é incidente do harness ou produto: recebe owner e diagnóstico, não retry infinito. Quarantine temporária reduz bloqueio apenas com prazo e risco registrado. Seeds e clocks são fixos quando não testados. Paralelismo respeita capacidade. Assertion eventual usa polling bounded com condição precisa. Artefatos de CI relacionam commit/digest. Um passe isolado após dez falhas não aprova. Métrica de duração e taxa de retry revela regressão antes que suíte vire ruído.",
    "### Incidente, aceite e fontes\nController test retornava 201, mas production middleware rejeitava content type e transaction não persistia outbox. O baseline atravessa stack real, lê estado por conexão independente e declara fakes. Mutantes removem middleware, constraint, commit e tenant predicate; suites correspondentes falham. Aceite lista componentes reais/simulados, versões, migrations, requests e state/effect evidence. Documentação do framework, PDO/database, broker e browser é fonte primária. Sem executor, exemplos são draft. A banca não chama teste com banco integration se wiring de produção não entrou, nem HTTP client end-to-end se proxy/TLS/worker/provider estão fora.",
  ],
  "Static analysis e mutation": [
    "## Static analysis e mutation\nAnálise estática aproxima contratos que PHP não verifica sozinho: shapes, generics via annotations, nullability, variance, exhaustiveness e fluxo. O baseline escolhe PHPStan ou Psalm em nível alto, fixa versão/config e trata baseline como dívida visível. O mutante gera baseline de todo erro novo e chama verde. Código fonte, tests e config são analisados; generated/vendor seguem política. Tipos não substituem validação externa: `non-empty-string` anotado não transforma request em valor válido. Value objects e assertions reconhecidas refinam depois da checagem. Suppression é local, explica falso positivo, liga issue e tem teste. Resultado registra versão PHP/extensions para refletir stubs corretos. Zero findings só prova regras habilitadas.",
    "### Shapes, generics e domínio\nArrays sem shape escondem chave ausente e mixed. O baseline usa DTO/value object na fronteira durável e annotations precisas para coleções, repository e Result. O mutante espalha `array<string,mixed>` até o domínio e faz casts. Templates/generics expressam que repository retorna entidade correspondente sem reflection perigosa. Enum/match exaustivo revela variante futura. `list<T>` diferencia mapa. Callable signatures incluem retorno e exceptions permanecem documentadas/testadas. Stub de extensão precisa corresponder à versão. Analisador detecta acesso nullable, dead branch e argumento trocado, mas não sabe que SQL contém tenant; regra customizada ou mutation/test cobre propriedades arquiteturais. Tipos impossíveis são corrigidos, não silenciados com assert falso.",
    "### Regras arquiteturais e segurança\nFerramentas podem proibir domínio importando framework/PDO, uso de unserialize, shell string, getenv fora do bootstrap, random inadequado e repository global. O baseline combina analisador, grep semântico/AST e review. O mutante confia em regex que não entende alias ou dynamic call. Taint analysis acompanha request até SQL, HTML, command e URL quando configurada, mas sanitizer contextual deve ser modelado corretamente. False positive não justifica desligar categoria inteira. Regra recebe fixtures positive/negative e versionamento. Secrets scanners usam canários e histórico conforme escopo. Dependency audit é separado de source analysis. Relatório aponta arquivo/linha/regra e não imprime dado sensível.",
    "### Mutation testing\nMutation altera operadores, condicionais, retornos e chamadas para medir se testes rejeitam comportamento errado. O baseline define mutantes críticos próprios/conceituais: remover tenant predicate, trocar `>=` por `>`, pular rollback, regenerar idempotency key, aceitar status desconhecido e ack antecipado. O mutante persegue score global com testes triviais ou ignora survived críticos. Cada sobrevivente é classificado: lacuna de teste, mutante equivalente ou código morto. Threshold existe por módulo/risco e não cai para aprovar. Mutation roda subset relevante e periodicamente completo; cache liga commit/config. Coverage reduz busca, mas não substitui execução. Timeout/crash do mutant é resultado investigado. Um teste novo deve falhar no mutante e passar no baseline.",
    "### Baselines e evolução\nBaseline de findings/mutants existentes permite adoção incremental somente se novas dívidas são bloqueadas e estoque diminui com owner. O baseline armazena fingerprint estável, não números de linha frágeis, e diff é revisado. O mutante regenera arquivo após upgrade sem examinar centenas de supressions. Atualização da ferramenta vem separada, com changelog e impacto. Métricas contam categorias e idade, evitando gamificação. Código tocado pode exigir nível maior. Generated code é corrigido no gerador quando possível. Findings de segurança têm SLA e exceção formal. CI publica artifact legível e falha se analyzer não executou; comando ausente não vira sucesso. Local e CI usam mesma config/lock.",
    "### Limites e combinação de provas\nStatic analysis não executa driver, lock, CSP ou deploy; mutation só avalia mutantes gerados e oracles atuais. O baseline combina unit, contract, integration, fuzz, review e observabilidade. O mutante anuncia type-safe como injection-safe. Runtime assertions permanecem nas fronteiras. Interface tipada pode estar ligada ao adapter errado; production graph test cobre. SQL string tipada pode omitir predicate; mutation/integration cobre. A matriz de evidência associa cada requisito ao gate que realmente o observa e marca ausente como Pending. Performance do analyzer é otimizada por cache correto/paralelismo, sem excluir diretórios críticos. Findings são tratados como feedback de design, não mera cerimônia.",
    "### Incidente, aceite e fontes\nUm array mixed omitiu tenant e um teste cobriu a linha sem perceber; mutante que removeu scope sobreviveu. O baseline refina DTO, cria regra arquitetural e teste negativo/real. Mutantes alteram comparação, rollback, key e mapping; todos os críticos precisam morrer ou ter equivalência justificada. Aceite registra ferramenta/versão/config, findings, suppressions e relatório mutation por risco. Documentação PHPStan/Psalm e mutation tool, além do PHP, são fontes. Sem executores, exemplos ficam drafts. A banca não chama level máximo prova de segurança, mutation score alto especificação completa, nem baseline vazio quando ferramenta não varreu arquivos.",
  ],
  "Property, fuzz e security corpus": [
    "## Property, fuzz e security corpus\nExample-based tests cobrem casos escolhidos; property tests geram muitos valores sob uma propriedade com oracle claro. Para fingerprint, canonicalização preserva igualdade sem depender da ordem; para parser, aceitar implica forma/range válidos; para reserve, capacity nunca fica negativa e total vendido respeita inicial. O baseline define generators válidos e inválidos, seed reproduzível, limites e shrink. O mutante gera apenas happy path ou afirma `não lançou`. Propriedade não pode ser tautologia da mesma função. Model-based test usa implementação simples independente como oracle. Falha salva seed e caso minimizado como regressão. Distribuição é observada para garantir boundaries, Unicode e combinações relevantes.",
    "### Generators e shrinking\nGenerator conhece domínio: tenant/IDs homônimos, quantity em torno dos limites, timestamps de DST, JSON profundo/largo, bytes UTF-8 inválidos e status futuros. O baseline pondera casos raros e compõe comandos com preconditions. O mutante filtra tanto input que nunca alcança erro. Shrinker reduz preservando validade ou intenção maliciosa, tornando o incidente legível. Random source é injetada/seeded; CI registra biblioteca/versão/seed. Quantidade de exemplos e deadline equilibram confiança e tempo. Um único seed diário complementa conjunto fixo. Gerador de SQL/URL/HTML não inventa gramática superficial quando corpus real existe. Dados sensíveis nunca entram na estratégia.",
    "### Fuzz de parsers e boundaries\nFuzzer alimenta bytes diretamente na fronteira: JSON decoder, multipart, headers, route, CSV/import, webhook signature e message envelope. O baseline impõe limite de bytes, depth, tempo/memória e oracle: não crashar, não hang, não aceitar inválido perigoso e roundtrip quando aplicável. O mutante faz fuzz do DTO já validado. Harness é determinístico e isolado; crash/timeout conserva input minimizado. Differential fuzz compara parser próprio com referência somente onde semântica coincide. Sanitizers nativos podem exigir build específico. Corpus inclui regressões e seeds estruturados. Fuzz não chama produção/provider. Um parse error deve permanecer bounded e redigido, sem stack ou eco do payload integral.",
    "### Corpus de segurança\nCorpus versionado cobre SQL metacharacters e identifiers, XSS por contexto, path traversal/encoding, SSRF schemes/hosts/redirects/DNS, command args, upload polyglots, duplicate headers, Unicode confusables e deserialization gadgets inertes. O baseline associa cada item ao sink e outcome esperado; payload SQL não serve como prova de HTML. O mutante roda scanner genérico e conta requests. Same-ID cross-tenant, CSRF e authorization possuem corpus/state oracle, não só string. Canários detectam secrets em logs/outbox. Atualizações vêm de incidentes e advisories sem copiar payload destrutivo desnecessário. Resultados false-positive são reproduzidos e corrigidos na regra. Teste browser/DB real entra quando interpretação do sink é essencial.",
    "### Stateful e concorrência gerada\nState machine gera sequências create/replay/cancel/dispatch/restore e mantém modelo simples de reservations, capacity e obligations. O baseline intercala dois atores/tenants, duplica mensagens e injeta falhas em fronteiras. Invariantes valem após cada passo: não negativo, uma identidade por key/fingerprint, tenant isolado, todo commit exige outbox, receipt não regride. O mutante testa comandos isolados. Concorrência property-based controla scheduler/barreiras quando possível e registra schedule; aleatoriedade sem reprodução gera flake. Engine real é necessária para lock/isolation. Shrinking de sequência preserva condição de corrida. Limites impedem explosão. Um outcome Unknown permite conjunto de estados e exige etapa de reconciliação antes do oracle terminal.",
    "### Recursos e negação de serviço\nProperty/fuzz também observa tempo, allocations, depth, file descriptors e processos. O baseline define budgets relativos/absolutos estáveis, executa inputs geométricos e procura crescimento inesperado, sem benchmark ruidoso como único gate. Regex, normalization, decompression, image metadata e JSON profundo merecem casos. O mutante aceita payload antes de medir ou aumenta memory_limit. Harness termina child travado, coleta diagnóstico e não derruba CI host. Rate limit/queue fairness recebem load test separado. Um input que é rejeitado só após consumir recurso excessivo ainda falha. Resultado registra plataforma e versões. Fix reduz trabalho antes da alocação, não somente timeout.",
    "### Incidente, aceite e fontes\nJSON profundo exauriu worker e canonicalização tratou dois comandos divergentes como iguais; exemplos manuais não alcançaram. O baseline usa generators, fuzz de bytes, corpus por sink e resource oracle. Mutantes removem depth, tenant, escape ou limite e devem produzir counterexample minimizado. Aceite registra property, generator distribution, seed, shrink, corpus version, budgets e componentes reais. Documentação da biblioteca property/fuzz, PHP parsers e sinks é fonte. Sem engine/browser apropriado, partes ficam Pending. A banca não chama mil inputs segurança, ausência de crash correção semântica, nem fuzzer verde quando harness não alcança a fronteira real.",
  ],
  "Authentication e autorização tenant": [
    "## Authentication e autorização tenant\nAutenticação estabelece quem apresenta a requisição; autorização decide se esse ator pode executar a ação naquele tenant e recurso agora. O baseline usa `password_hash`/`password_verify` com algoritmo/custo suportado, rehash oportunista, resposta uniforme e rate limit. Sessão é regenerada no login/elevação, cookie Secure/HttpOnly/SameSite apropriado e revogação considera auth version. O mutante guarda hash fraco, diferencia usuário inexistente por timing ou confia em user ID do body. MFA/recovery têm protocolo próprio, códigos de uso único e auditoria redigida. Testes cobrem credential stuffing bounded, fixation, logout/revogação e sessão velha. Segredo de senha nunca entra em log, analytics, exception ou fila.",
    "### Tenant como contexto confiável\nTenant vem da identidade/rota validada e membership autorizada, não de campo arbitrário. O baseline cria `Identity(actorId, tenantId, roles, authVersion)` e o propaga por command, repository, cache, job e provider. O mutante lê `tenant_id` do JSON e faz `find($id)` global antes da policy. Mesmo ID em alpha/beta é teste negativo obrigatório. Queries e unique keys incluem tenant; relações usam constraints compostas; cache e outbox também. Admin cross-tenant usa porta separada, strong auth, reason e audit. Resposta para recurso ausente/proibido evita enumeração conforme threat model. Logs registram IDs pseudonimizados/bounded. Troca de tenant invalida context anterior, não apenas altera header.",
    "### Policies e ordem da decisão\nPolicy recebe valores próprios e ação fechada; regra combina membership, role/capability, ownership, estado e risco. O baseline autentica, resolve tenant autorizado, carrega recurso já scoped e avalia ação antes da mutação. O mutante consulta globalmente, revela existência e só depois nega. Default é deny e variante futura não cai em allow. Role não substitui constraint do recurso. Delegação/impersonation tem prazo, alvo, motivo e audit, com UI clara. Batch verifica cada item ou query retorna somente permitidos. Tests table-driven cobrem actor/resource/state, além de same-ID cross-tenant e role revogada. Policy version pode integrar cache key e job reauthorization.",
    "### Tokens, sessões e APIs\nToken assinado ainda precisa validar algoritmo fechado, issuer, audience, expiry/not-before com skew bounded, key ID e revogação conforme risco. O baseline não aceita `none`, algoritmo vindo do token ou chave ambígua. Access token é curto; refresh rotation detecta reuse. API keys são hashed, scoped, identificáveis por prefixo seguro e rotacionáveis. O mutante trata decode como verify ou usa token em query URL. Sessões server-side possuem expiry absoluto/idle e lock/concorrência entendidos. CSRF protege autenticação por cookie; bearer em header exige CORS/origin conforme app. Testes usam chaves reais de teste e vetores inválidos, não apenas mock de decoder.",
    "### Jobs, cache e provider\nAutorização não termina no request. Job carrega tenant, actor/delegation quando necessário, action e stable ID; consumer decide entre revalidar policy atual ou honrar snapshot autorizado conforme obrigação. O baseline documenta isso e impede job antigo de ganhar novos privilégios. Cache de resposta/decisão inclui tenant, actor/capability/policy version e visibility; o mutante usa somente resource ID. Provider account/project é mapeado por tenant no servidor, jamais escolhido pelo payload. Search/export/analytics mantêm scope. Teste sequencial no mesmo worker, cache collision, revogação antes do consumo e provider transcript demonstram propagação. Audit é append-only/least privilege e não contém token.",
    "### Evidência e resposta\nEventos de auth distinguem success/failure/lock/revoke sem revelar senha ou confirmar conta indevidamente. Rate limits usam dimensões defendíveis e não permitem um atacante bloquear todo tenant com uma chave. O baseline mede falhas, sessões ativas, denials e uso administrativo com cardinalidade bounded. Runbook revoga sessions/keys, rotaciona signing keys com janela segura, preserva audit e investiga cache/jobs. Backup/restore mantém auth version e revocation ou força reautenticação deliberada. Testes procuram canários de secret nos logs. Browser/HTTP/database reais cobrem cookie e scope. Scanner não substitui same-ID state oracle.",
    "### Incidente, aceite e fontes\nRepository global retornou reserva de alpha a usuário de beta; cache por ID repetiu vazamento. O baseline propaga identity/tenant, consulta scoped, policy deny-by-default e chave contextual. Mutantes removem predicate, aceitam body tenant, ignoram revogação e cacheiam global; gates precisam falhar. Aceite registra auth flow, cookie/token claims seguros, SQL/cache/job/provider e state readback. Manuais PHP password/session, especificações de token e framework são fontes primárias. Sem browser/runtime/DB, exemplos ficam drafts. A banca não chama autenticação autorização, JWT decode validação, nem policy no controller prova de isolamento sistêmico.",
  ],
  "Injection, upload e SSRF": [
    "## Injection, upload e SSRF\nInjection ocorre quando dado é interpretado como estrutura por um sink. Cada sink exige controle próprio: valores SQL usam binds, identifiers mapping; shell prefere API/argv sem shell; HTML encoding contextual; path containment; URL parser/egress; header sem CRLF. O baseline inventaria sinks e mantém corpus específico. O mutante aplica `addslashes` ou regex universal e chama sanitizado. Validação de domínio e encoding de saída são camadas distintas. Taint analysis ajuda, mas adapters dinâmicos precisam tests. Error nunca ecoa payload integral. Testes verificam resultado/efeito real no parser, banco, browser ou processo seguro, não apenas presença de caracteres escapados.",
    "### Command e código dinâmico\n`exec`, `shell_exec`, backticks, `system`, `passthru`, `proc_open` com command string e `eval` ampliam risco. O baseline evita; quando processo é requisito, escolhe executable absoluto allowlisted, argv separado, environment mínimo, cwd conhecido, timeout, output cap e exit handling. No Windows/POSIX, quoting difere, logo concatenação não é portátil. O mutante usa `escapeshellarg` e ainda permite escolher executable/options. Template/include/callable/class por input também é code injection: usa registry fechado. Unserialize externo é proibido. Tests tentam separators, option injection (`-...`), espaços/Unicode e output flood. Child é encerrado como árvore conforme plataforma.",
    "### Upload e filesystem\nUpload chega em temp sob controle do runtime, mas nome, MIME declarado e conteúdo são hostis. O baseline verifica erro/tamanho antes de ler, MIME por conteúdo, formato por decoder seguro, dimensões/decompression ratio, gera nome próprio e grava fora do web root com permissão mínima. O mutante confia na extensão ou `Content-Type`. Imagem/documento pode ser polyglot/ativo; re-encode/sandbox/antivirus depende do produto e não autoriza servir inline. Path final usa diretório fixo e ID, sem traversal/symlink race. Download define Content-Disposition/nosniff e autorização tenant. Cleanup cobre falha. Corpus inclui dupla extensão, null/Unicode, ZIP bomb, SVG/script e arquivo truncado.",
    "### SSRF e egress\nURL fornecida pelo usuário não deve escolher livremente destino do servidor. O baseline prefere IDs/hosts cadastrados; se URL é necessária, parser estrito limita scheme https, port, credentials, hostname canônico e path, resolve DNS e bloqueia redes especiais em cada conexão/redirect. O mutante bloqueia string `127.0.0.1` mas aceita IPv6, decimal, DNS rebinding ou redirect. Egress firewall/proxy é defesa forte; client desliga redirects ou revalida cada hop, fixa timeout, byte cap e métodos. TLS hostname/cert permanece ativo. Resposta não é logada inteira. Testes usam servidor controlado e destinos canário para metadata/loopback/private, sem tocar serviço real sensível.",
    "### SQL, headers e templates\nBinds não parametrizam table/order/operator; mapping fechado controla estrutura. LIKE wildcards são regra separada. Header/cookie/location recusam CR/LF e valores são produzidos por APIs apropriadas. Templates escapam por HTML text, attribute, URL, JS ou CSS; rich text usa sanitizer allowlist e CSP complementa. O mutante marca string como safe após limpeza inadequada. JSON embutido precisa encoder/element handling. Email templates e log forging são sinks adicionais. Testes de browser confirmam DOM/network; banco confirma nenhuma segunda statement; HTTP confirma headers finais após proxy. Sanitização transforma e pode colidir identidade, então validação/canonicalização ocorre antes de authorization key.",
    "### Limites e operação\nTodo sink tem budget: SQL rows/time, child runtime/output, upload bytes/depth, URL response/redirect e sanitizer complexity. O baseline rejeita cedo, usa temp quota e apaga com owner conhecido. O mutante só configura `memory_limit` global. Métricas contam rejeições por categoria bounded e nunca payload. Incident response revoga endpoint/feature flag, preserva amostra criptografada com acesso restrito e procura efeitos: arquivo gravado, request egress, comando iniciado ou row alterada. WAF é camada auxiliar, não correção do sink. Dependency parser/decoder recebe advisories e sandbox quando risco exige. Regression corpus nasce do incidente.",
    "### Incidente, aceite e fontes\nImport de URL alcançou metadata via redirect; upload SVG servido inline executou script; opção iniciada por hífen alterou comando. O baseline fecha destino/executable, valida cada redirect, trata upload como ativo e limita recursos. Mutantes liberam private IP, usam filename, concatenam argv e marcam HTML safe; gates específicos falham. Aceite registra parser, egress/proxy, filesystem, process argv e browser/DB state. Manuais PHP, client/OS e formatos são fontes. Sem sandbox/browser/rede controlada, exemplos ficam drafts. A banca não chama escaping universal, MIME header prova de tipo ou allowlist inicial suficiente se redirect/DNS mudam destino.",
  ],
  "Secrets, TLS e headers": [
    "## Secrets, TLS e headers\nSegredo é credencial com lifecycle: origem, distribuição, memória, uso, rotação, revogação e audit. O baseline mantém código/config não secreta no artifact e obtém segredo por secret manager/file mount/identity da plataforma com least privilege. O mutante coloca token em repository, composer auth, image layer ou `.env` copiado. Environment também pode vazar em diagnostics/process dumps; risco é avaliado. Boot valida presença sem imprimir valor. Objetos secret não têm `__toString`, serialization ou logging casual. Testes usam canários e inspecionam source, history quando escopo, artifact, layers, logs, exceptions e telemetry. Credencial de build é efêmera e não persiste na imagem.",
    "### Rotação e identidade\nRotação compatível aceita chave antiga/nova por janela mínima, atualiza consumers e revoga antiga depois de evidência. O baseline identifica key version sem expor material, mede uso e ensaia rollback. O mutante substitui valor instantaneamente ou mantém segredo eterno. Database/provider keys são por ambiente/serviço, não compartilhadas. Workload identity reduz segredo estático quando plataforma suporta. Signing key possui algorithm, kid, storage e publicação de chave pública; kid não escolhe path/FQCN arbitrário. Backup de segredo e disaster recovery seguem política separada. Incidente decide rotação de derivados/sessions. Testes simulam old/new, cache refresh e falha do manager sem cair em default inseguro.",
    "### TLS de saída\nClient verifica cadeia e hostname com trust store atual; SNI, proxy e redirects são considerados. O baseline não desliga `CURLOPT_SSL_VERIFYPEER`/host, limita protocolos/ciphers conforme plataforma e registra apenas versão/código seguro. O mutante aceita self-signed em produção para resolver incidente. CA privada é instalada explicitamente e pinning só com plano de rotação. mTLS protege canal/identidade mas não autoriza recurso sozinho. Timeout e response cap evitam DoS. Teste usa certificado válido, expirado, hostname errado e CA desconhecida em harness controlado. Data/hora do host é dependência. TLS termination de entrada é verificada no proxy real, não inferida do PHP.",
    "### Proxy e headers de entrada\nAplicação confia em forwarded headers somente de proxies conhecidos e conforme topologia; senão Host, proto e client IP podem ser forjados. O baseline configura trusted proxies, hosts allowlisted e URL pública canônica. O mutante aceita qualquer `X-Forwarded-Proto` e emite cookie inseguro/redirect hostil. Duplicate headers e RFC parsing recebem gate da stack. Request ID externo é validado/bounded ou substituído. Authorization/cookie são redigidos antes do logger. CORS responde origins fechadas e varia cache corretamente; não é autorização. HSTS é emitido somente sobre HTTPS final e com rollout consciente. Teste atravessa proxy de staging para provar valores recebidos.",
    "### Headers de resposta e cookies\nBaseline aplica CSP sem unsafe amplo, frame-ancestors, nosniff, referrer/permissions policy e cache-control conforme dado; cookie usa Secure, HttpOnly, SameSite, path/domain mínimos e prefixo quando útil. O mutante duplica/conflicta headers entre PHP e proxy. CSP nonce é aleatório por resposta, ligado ao HTML e não reutilizado por cache; report-only antecede enforcement. Download usa disposition seguro. API sensível não fica em shared cache. Error responses recebem políticas também. Browser tests verificam header final, execução bloqueada, cookies e redirects. Security headers não corrigem XSS/CSRF, apenas reduzem impacto. Config possui owner e compatibilidade documentada.",
    "### Logging e observabilidade\nRedaction ocorre antes de qualquer sink e cobre tokens, cookies, Authorization, DSN, request bodies e query params sensíveis. O baseline usa allowlist de campos e IDs correlacionáveis não secretos. O mutante tenta regex depois que collector já recebeu. Trace baggage não transporta credential/PII. Labels são bounded. Exception de SDK pode incluir URL/token e recebe mapper. Sampling não autoriza conteúdo. Acesso, retenção e exportação de logs são controles de segurança. Testes injetam canários em cada fronteira e buscam todos os artifacts. Audit registra ação/actor/tenant/result, não segredo. Debug mode é impossível em produção por gate, e phpinfo nunca é endpoint público.",
    "### Incidente, aceite e fontes\nToken Composer ficou em layer e client desativou verificação TLS; Host forjado gerou link de reset atacante. O baseline separa secret de artifact, verifica TLS e fixa trusted proxy/public origin. Mutantes imprimem canário, aceitam cert errado, confiam forwarded e enfraquecem cookie/CSP; gates falham. Aceite inclui scan do artifact/log, rotação ensaiada, TLS harness e browser/proxy headers finais. Manuais PHP/cURL, padrões TLS/HTTP e plataforma são fontes. Sem ambiente TLS/proxy/browser, exemplos ficam drafts. A banca não chama variável de ambiente secret manager, HTTPS string prova de verificação ou headers no código prova do valor final após proxy.",
  ],
  "DoS, limits e incident response": [
    "## DoS, limits e incident response\nDisponibilidade exige autorizar consumo de bytes, CPU, memória, conexões, processos, filas e dependências. O baseline define orçamento em camadas: proxy/body, PHP execution/memory, parser depth/items, upload/temp, DB rows/time, HTTP response, worker concurrency e tenant quota. O mutante aumenta `memory_limit` depois de OOM. Rejeição acontece antes de alocar/trabalhar sempre que possível e retorna erro bounded. Limites se alinham para que upstream não continue trabalho após caller desistir. Testes usam tamanhos imediatamente abaixo/acima e crescimento geométrico, medindo RSS/latency/state. Rate limit é apenas uma peça; payload barato numericamente pode ser caro semanticamente.",
    "### FPM, pools e admission\n`pm.max_children`, backlog, server concurrency, DB pool e provider limit formam um sistema. O baseline reserva capacidade, rejeita cedo e protege health/admin sem permitir bypass de negócio. O mutante aceita tudo até fila consumir memória e timeouts sincronizarem retry storm. Little's Law e load tests orientam capacidade, mas invariantes/state oracle acompanham throughput. Per-tenant fairness impede noisy neighbor; identidade não autenticada usa dimensões resistentes a spoofing. Keep-alive e slow clients são tratados no web server/proxy. Worker recycling limita leak sem esconder causa. Readiness não encaminha tráfego antes de dependencies essenciais; liveness não mata processo por outage remota transitória.",
    "### Parsers, regex e arquivos\nJSON limita bytes e depth antes/ao decodificar; collections têm máximo; regex evita catastrophic backtracking ou usa pattern/subject/time budget; decompression/image/doc parsing possui ratio/dimensions/pages e sandbox. O baseline não lê `php://input` ilimitado nem `file_get_contents` de upload inteiro sem cap. O mutante valida extensão depois de carregar gigabytes. Temp storage tem quota e cleanup. Unicode normalization e hashing de input enorme também custam. Fuzz/resource tests procuram superlinearidade. Timeout aborta child/parser, mas o processo principal ainda precisa limpar. Bibliotecas nativas podem crashar; isolamento por processo/container é considerado. Error não devolve trecho massivo.",
    "### Banco, fila e dependências\nQueries têm paginação/limit, índices, statement/lock timeout e role; exports grandes viram job/stream bounded. O baseline limita inflight e usa backpressure na fila. O mutante permite filter/order arbitrário ou N+1. Circuit breaker, bulkhead e deadline protegem provider sem perder obrigação; retry tem budget/jitter. Cache outage não derruba banco por stampede: single-flight/bounded stale conforme dado. Teste degrada DB/provider/broker, mede queues/pools e confirma que commits/outbox não somem. Cancelar request não presume cancelar query/efeito. Tenant quota contabiliza trabalho antes/depois de auth com cuidado. Reconciliation drena backlog em ritmo seguro após recuperação.",
    "### Algoritmos e abuso lógico\nDoS pode explorar busca ampla, combinação de filtros, regex, fan-out, endpoints de login/reset, geração PDF ou idempotency keys sempre novas. O baseline aplica custo estimado, paginação keyset, quotas por ação e deduplicação. O mutante limita requests por IP e ignora botnet/usuário autenticado. Respostas uniformes de auth não fazem trabalho caro ilimitado; email/reset é enfileirado e capped. Idempotency store tem tamanho/retention e key length. Graph/query depth quando aplicável. Testes de adversarial workload variam distribuição, tenant e cache miss. Métricas por outcome/cost bounded ajudam ajustar sem expor alvo. Controle possui acessibilidade e não bloqueia usuários legítimos indiscriminadamente.",
    "### Resposta a incidente\nRunbook define sinais, severidade, owner, mitigação reversível, evidência e critérios de recuperação. O baseline pode reduzir concurrency, desativar feature cara, limitar tenant, pausar consumer ou proteger egress sem editar host manualmente. O mutante reinicia repetidamente e apaga evidência. Telemetria inclui saturation, backlog age, RSS, OOM/recycle, timeouts e error classes; IDs não viram labels. Preserva amostra/canários com acesso controlado. Depois de conter, reconcilia source/outbox/provider, repõe capacidade gradualmente e verifica invariantes. Postmortem produz corpus, load scenario e mudança de design. Chaos/fault drill ocorre em ambiente seguro. Comunicação evita afirmar perda/segurança antes de state audit.",
    "### Incidente, aceite e fontes\nJSON profundo e upload comprimido exauriram FPM; retries imediatos mantiveram outage mesmo após provider voltar. O baseline limita cedo, alinha pools/deadlines, aplica backpressure e runbook com reconciliação. Mutantes removem depth/size, liberam concurrency e repetem sem jitter; resource/load gates falham. Aceite registra configuração efetiva de proxy/PHP/FPM, workload, RSS/pools/queues, latency e estado final. Manuais PHP/FPM/web server e dependências são fontes. Sem ambiente de carga isolado, exemplos ficam drafts. A banca não chama status 429 proteção completa, timeout cancelamento garantido ou throughput alto sucesso se estado/efeitos se perderam.",
  ],
  "OPcache, JIT e preload": [
    "## OPcache, JIT e preload\nOPcache guarda bytecode compilado e reduz parsing, mas sua configuração, validação de timestamps, memória e lifecycle precisam combinar com o modo de deploy. O baseline produz artifact imutável, identifica release por digest e troca symlink/container antes de reload gracioso. O mutante sobrescreve arquivos enquanto workers atendem e cria mistura de versões. Em produção com timestamp validation desativada, restart/reset controlado é obrigatório; em desenvolvimento, revalidation coerente evita confusão. Gate percorre vários requests/workers e exige a mesma release, classes e schema compatível. Métricas observam hit rate, used/free/wasted memory, restarts e cached scripts sem expor paths sensíveis. Limpar cache não é correção permanente para artifact inconsistente.",
    "### Capacidade e invalidação\nMemória insuficiente ou hash table cheia causa restart/eviction e latência. O baseline mede quantidade/tamanho de scripts no artifact real, deixa margem e alerta por wasted/max keys. O mutante copia vendor/testes desnecessários ou aumenta memória sem entender shared segment. Deploy atômico usa paths estáveis por release e preload correspondente; rollback aponta artifact anterior e recarrega. `opcache_reset` afeta processo/contexto conforme SAPI e não substitui coordenação de pool. File cache possui segurança/permissão e invalidation próprias. Teste de cold/warm mede bootstrap e confirma comportamento, mas não usa hit rate como prova funcional. Config efetiva vem de FPM, não do CLI diferente.",
    "### Preload seguro\nPreload roda na inicialização do processo mestre e mantém símbolos até restart. O baseline inclui somente declarations side-effect-free em ordem resolvível, geradas/revisadas no build; não abre PDO, lê tenant, monta request scope ou faz chamada remota. O mutante inclui bootstrap completo e herda conexão/recurso inválido nos workers. Classes condicionais/proxies e autoload precisam compatibilidade. Preload não aceita troca parcial durante release. Gate inicia pool novo, executa smoke em múltiplos workers e compara release. Falha impede readiness. Benefício é medido contra complexidade/memória; se irrelevante, não se usa. Secrets nunca entram em arquivo gerado ou dump de diagnóstico.",
    "### JIT e workload\nJIT pode beneficiar cálculo CPU-bound, mas aplicações web dominadas por I/O raramente ganham automaticamente e podem consumir memória/alterar debugging. O baseline testa workload representativo com e sem JIT, mesma versão/config, e exige equivalência de resultado/efeito. O mutante habilita por marketing e relata microbenchmark. Warmup, CPU governor, samples e variance ficam registrados. Extensões, FFI e código numérico recebem atenção de correção. Mudança de JIT é configuração de release, canary e rollback. Performance de request inclui DB/provider e filas; reduzir 1 ms de CPU não resolve lock. Profiler confirma hotspot. Crash/regressão desabilita de forma controlada sem editar host manualmente.",
    "### Deploy e frota mista\nReload gracioso mantém workers antigos até drenar, portanto duas versões podem coexistir. O baseline usa expand-contract de schema/message/cache, namespace por release quando necessário e readiness por digest. O mutante assume troca instantânea e remove classe/coluna. Requests longos/jobs possuem limite e estratégia de drain; workers presos são terminados após obrigação segura. Health endpoint informa versão sanitizada. Load balancer só envia ao pool pronto. Canary compara erros, latency, saturation e invariantes antes de ampliar. Rollback considera preload/opcache e dados já escritos. Teste old/new lê/escreve estado intermediário. Cache de container/autoload e OPcache são layers diferentes e todos pertencem ao artifact.",
    "### Diagnóstico e segurança\nEndpoints de status OPcache não são públicos; dados administrativos exigem acesso restrito e redaction. O baseline coleta métricas por agente/local e registra config não secreta. O mutante publica phpinfo/status para debug. Runbook diferencia cache cheio, script stale, preload failure, mixed release e erro de código. Ação preserva amostra, drena, troca artifact e reinicia de modo limitado. Alertas evitam cardinalidade por filename. Teste procura endpoints diagnósticos e permissões. Config drift é comparada com manifesto. Um reset global durante pico pode causar stampede de compilação, logo rollout controla taxa. Postmortem atualiza capacity/release gate.",
    "### Incidente, aceite e fontes\nDeploy sobrescreveu arquivos com timestamp validation off e workers executaram classes incompatíveis; preload abriu conexão antes do fork. O baseline usa artifact imutável, preload puro, digest e reload observável. Mutantes misturam release, incluem side effect e mantêm worker antigo além do drain; gates falham. Aceite registra SAPI, ini efetivo, status redigido, artifact, requests multiworker e resultado funcional. Manuais PHP OPcache/preload/JIT e servidor são fontes. Sem FPM real, exemplos ficam drafts. A banca não chama OPcache cache HTTP, JIT garantia de velocidade ou reload prova de troca uniforme.",
  ],
  "FPM, pools e servidores": [
    "## FPM, pools e servidores\nFPM pool transforma memória e processos em capacidade. `pm` static/dynamic/ondemand, max_children, spare, requests, timeouts e backlog devem caber em RAM, DB pool e upstream. O baseline mede RSS p95/p99 por workload e reserva sistema/sidecars antes de calcular children. O mutante multiplica CPU por um número e excede conexões. Cada child atende um request por vez; latency e arrival rate determinam concorrência. Proxy limita body/slow clients e possui timeout maior/coerente com app. Teste de carga observa queue, active/idle, max children reached, RSS, DB connections e estado final. Capacidade é por pool/host e por toda frota.",
    "### Segregação e least privilege\nPools separados por aplicação/trust podem usar Unix user, directories, limits e env distintos, reduzindo blast radius. O baseline roda sem privilégio, filesystem read-only exceto temp/upload definidos e secrets mínimos. O mutante compartilha pool/usuário e permite escrita no código. Socket/TCP listener possui ACL/rede. Chroot/container não substitui atualização/egress. Status/ping ficam em rota interna e não pulam auth pública. Environment é limpo/allowlisted. Upload temp/session directories têm quotas. Teste de permissão tenta gravar source, ler secret alheio e acessar listener externo. Log files/stdio não aceitam payload sem redaction.",
    "### Timeouts, abort e shutdown\nProxy, web server, FPM `request_terminate_timeout`, PHP execution, DB/client deadlines e load balancer são alinhados. O baseline deixa camada externa dar orçamento e interna terminar antes, preservando tempo para resposta/cleanup. O mutante apenas aumenta timeout. Cliente desconectado pode não cancelar trabalho; código checa deadline onde seguro e não assume rollback automático. Kill abrupto não roda finally/shutdown, então obrigação durável precede efeito externo. Slowlog captura stack de request lento com proteção de dados. Testes simulam client abort, query lenta e provider timeout, depois leem transaction/outbox. Fatal/OOM têm telemetria limitada; worker recycle não é commit protocol.",
    "### Reload, drain e saúde\nReload inicia novos workers e drena antigos; deployment monitora ambos. O baseline fecha admission, aguarda requests bounded, coordena queue workers separadamente e confirma release digest. O mutante mata tudo e perde job ou mantém versão velha invisível. Readiness verifica config/runtime e dependências essenciais sem mutação; liveness confirma loop/processo, não falha por qualquer outage externa. Startup storm é limitado. `pm.max_requests` recicla leak/fragmentação com jitter para evitar onda. Testes mantêm request lento durante deploy e garantem conclusão/resultado ou retry seguro. Signals e supervisor behavior são verificados no sistema real.",
    "### Servidor e proxy\nNginx/Apache/Caddy/IIS ou plataforma definem headers, buffering, static assets, compression, TLS e FastCGI params. O baseline fixa SCRIPT_FILENAME/path info, trusted proxy/host, body limit e não permite executar upload como PHP. O mutante usa config de exemplo permissiva. Filesystem route impede traversal e source disclosure. Error pages não mostram stack. Compression evita segredo refletido quando ameaça aplicável. Cache de resposta respeita auth/tenant/Vary. Testes atravessam proxy real em staging, incluindo duplicate Host, encoded path, large body, TLS e cookie. Config é versionada/linted e ligada ao artifact.",
    "### Overload e operação\nQuando children/DB saturam, baseline rejeita cedo, mantém health/control plane e aplica fairness. Autoscaling usa queue/latency/saturation com limites e considera DB/provider, não apenas CPU. O mutante escala pods até derrubar banco. Alerts medem listen queue, max_children, 5xx/timeouts, recycle, RSS e pool wait. Runbook reduz admission/concurrency, pausa recurso caro e escala dentro do budget. Soak detecta leak. Capacity review acompanha mudança de payload/dependency. Métricas não rotulam URL/tenant arbitrário. Recuperação drena backlog com rate seguro e reconcilia effects.",
    "### Incidente, aceite e fontes\nMax children excedeu conexões do banco, filas cresceram e retries pioraram; servidor também executava `.php` em upload. O baseline dimensiona sistema inteiro, separa paths e valida proxy/FPM reais. Mutantes ampliam children, removem timeout/body cap e expõem upload; load/security gates falham. Aceite registra configs efetivas, topologia, workload, pools/queues/RSS e state/effect oracle. Manuais FPM e servidor/proxy são fontes. Sem host/pool real, exemplos ficam drafts. A banca não chama mais workers mais capacidade, liveness readiness ou graceful reload ausência de frota mista.",
  ],
  "Logs, metrics e traces": [
    "## Logs, metrics e traces\nTelemetria responde o que aconteceu sem virar vazamento ou nova indisponibilidade. Logs são eventos estruturados; metrics agregam séries bounded; traces ligam operações. O baseline define schema com timestamp, level, event name, service/release, operation/request/trace, outcome e campos allowlisted. O mutante concatena request/body/exception e chama observável. PSR-3 placeholders ainda podem carregar segredo; redaction ocorre antes. IDs de alta cardinalidade ficam em logs/traces, não labels. Clock e timezone são consistentes. Falha do collector não derruba transação; buffers possuem bound/drop policy. Audit de segurança é stream com retenção/controle próprios, não log debug comum.",
    "### Correlation e propagation\nRequest ID externo é validado/bounded ou substituído; trace context segue padrão e não concede confiança. O baseline cria operation ID estável para retry e separa attempt/span IDs. Jobs propagam trace link e event ID, não objeto de request. O mutante usa trace ID como idempotency key ou aceita CRLF em correlation header. Baggage é allowlisted e não leva token/PII. Logs de HTTP, DB, outbox e provider compartilham operation/event ID. Testes atravessam request→outbox→worker com collector fake e procuram correlação, duplicação e cleanup entre tenants. Sampling preserva errors/critical flows conforme política, mas não altera lógica.",
    "### Metrics e SLOs\nCounters medem operações/outcomes, histograms latency/size e gauges recursos/queues com nomes/unidades estáveis. O baseline usa route template, operation e error class bounded; o mutante usa path, tenant ou exception message como label. RED/USE e SLOs ligam sinais a experiência: availability correta inclui state/effect, não apenas HTTP 2xx. Queue age e unknown outcomes são sinais de obrigação. Histograms têm buckets úteis e exemplars seguros. Tests inspecionam series count/labels. Cardinality budget é monitorado. Alertas combinam burn rate/saturation e runbook, evitando threshold ruidoso. Métrica do exporter ausente não vira zero silencioso.",
    "### Traces e instrumentação\nSpan cobre trabalho significativo e define status por outcome, sem criar span por item ilimitado. O baseline instrumenta HTTP, transaction, query template, provider e queue, propagando context de forma segura. O mutante grava SQL com binds/headers ou fecha span antes do commit. Retry cria child attempt sob operação estável. Async links representam causalidade quando parent já terminou. Sampling head/tail possui custo/privacidade. Auto-instrumentation é validada, pois pode duplicar spans ou capturar dados. Teste confirma commit/Unknown e exception mapping. Export é assíncrono bounded; shutdown tenta flush dentro de orçamento, sem segurar resposta crítica.",
    "### Redaction e privacidade\nAllowlist supera blacklist. Password, token, cookie, Authorization, DSN, idempotency key sensível, bodies e PII não entram por default. O baseline oferece tipos/processor de redaction antes de formatter/exporter e canários automatizados. O mutante mascara na UI enquanto storage contém valor. Hash de PII ainda pode ser identificador e exige salt/política. Stack traces, SQL exceptions e SDK URLs são revisados. Retenção e acesso correspondem à finalidade/regulação. Debug temporário possui expiry e audit. Teste injeta canário em request, provider error, env e message, então busca arquivos/collector/traces. Dumps são artefatos sensíveis.",
    "### Operação e confiabilidade\nTelemetry pipeline pode atrasar/falhar; baseline limita queue/memory, escolhe drop priority e expõe self-metrics. O mutante bloqueia request tentando enviar log remoto. Rotação de arquivo evita disco cheio; stdout depende do runtime collector. Schema/version de eventos permite consumidores. Dashboards ligam release/deploy sem label explosiva. Runbook começa por SLO, saturation, recent change e unknown obligations, depois consulta logs/traces correlacionados. Alertas têm owner. Synthetic checks não realizam efeito irreversível. Restore/incident preserva timestamps e release. Observabilidade é testada em staging com outage do collector.",
    "### Incidente, aceite e fontes\nToken virou label e explodiu cardinalidade; span encerrou antes do commit e 201 pareceu sucesso apesar do rollback. O baseline usa schemas, allowlist, operation/outcome e fechamento após fronteira real. Mutantes adicionam secret/ID label, removem correlation e marcam success cedo; gates falham. Aceite registra telemetry config, collector transcript, cardinality e canary scan, junto de state/effect. PSR-3, OpenTelemetry e backend escolhido são fontes. Sem collector/runtime, exemplos ficam drafts. A banca não chama volume observabilidade, trace prova de commit sem readback ou redaction de interface remoção no armazenamento.",
  ],
  "Profiling, carga e memória": [
    "## Profiling, carga e memória\nProfiling localiza onde tempo/CPU/alocação ocorre; benchmark compara unidade; load/soak mede sistema sob concorrência. O baseline começa por hipótese, workload representativo e oracle funcional. O mutante otimiza microbenchmark enquanto produção espera lock/provider. Perfil distingue wall, CPU, I/O, allocations e call count com sampling/instrumentation e overhead conhecido. Dados sensíveis em arguments/heap são protegidos. Cold/warm, OPcache, data distribution e cache state ficam registrados. Mudança só é aceita se melhora métrica alvo sem alterar estado/efeito, segurança ou legibilidade além do tradeoff aprovado.",
    "### Cenários e modelos de carga\nWorkload descreve mix de rotas/jobs, arrival rate, concurrency, payload, tenant distribution, think time e duração. O baseline inclui steady, spike, stress e soak, com capacity de dependencies isoladas/sandbox. O mutante usa loop fechado que reduz arrival quando sistema fica lento e esconde overload. Open model ajuda representar tráfego externo; ambos têm uso. IDs e idempotency keys são realistas e bounded. Warmup separado. Generator não vira gargalo e clock hosts está sincronizado. Teste da última vaga usa cenário específico e barriers; load geral não prova race por acaso. Resultados incluem errors/timeouts/queue, não apenas média.",
    "### Oráculo de estado e efeitos\nCada cenário calcula expected accepted/rejected/created/replayed e depois consulta source of truth, outbox e provider transcript. O baseline exige capacity nunca negativa, uma reserva por intenção, todas as reservas com outbox e effects reconciliados. O mutante comemora throughput mesmo com perda/duplicação. Unknown é contabilizado e reconciliado antes do veredito. HTTP latency não termina no response se obrigação assíncrona possui SLO; mede queue age/time-to-effect. Segunda conexão/processo faz readback. Checksums/counts são acompanhados de amostras/joins para não mascarar colisão. Cleanup preserva artifact da falha e remove somente namespace da execução.",
    "### Memória e leaks\nSoak acompanha RSS por worker, heap quando disponível, GC, objects, file descriptors, connections e caches ao longo de muitas unidades. O baseline alterna tenants/payloads e força failure paths; slope sustentável importa mais que snapshot. O mutante seta max_requests baixo e declara resolvido. Profilers/heap dumps mostram retainers, mas podem conter segredo. Causas incluem static cache, closure, ORM identity map, stream/cursor, extension e fragmentation. Fix adiciona bound/cleanup e teste; recycle continua safety net. Upload/JSON peak memory também é medido. OOM pode matar sem finally, então protocolo durável não depende de cleanup.",
    "### Database e upstream\nProfile correlaciona query count/template, pool wait, lock, plan e rows; provider mede DNS/connect/TLS/TTFB/body e rate limits. O baseline otimiza N+1/index/batching com contract e plan evidence. O mutante aumenta concurrency contra dependency saturada. Load fake não certifica provider real, mas sandbox pode ter quotas diferentes; alcance é declarado. Fault injection aumenta latency/errors e verifica backpressure/circuit/retry. Cache hit/miss distribution é realista. Connection reuse e TLS têm lifecycle. Slow query log é redigido. Uma melhoria local que transfere custo para DB ou fila não conta sem medida do sistema.",
    "### Regressão e budgets\nPerformance CI usa budgets robustos para operações estáveis e trend em ambiente controlado; não falha por ruído de laptop sem contexto. O baseline fixa versões/config, repete, relata percentis e intervalo, compara baseline aprovado. O mutante usa melhor execução ou média apenas. Functional suite roda junto/antes. Mudança relevante recebe canary em produção e rollback threshold. Budgets incluem p95/p99, error, RSS slope, pool wait, queue age e correctness. Artifact do perfil é retido com acesso. Otimização não reduz timeout/validation para parecer rápida. Capacity forecast inclui crescimento e headroom.",
    "### Incidente, aceite e fontes\nTeste mostrou p50 melhor após remover transaction, mas perdeu outbox; outro soak escondia leak reciclando a cada dez jobs. O baseline une performance a state/effect oracle e mede lifecycle real. Mutantes removem commit, liberam concurrency e retêm objetos; gates falham. Aceite registra artifact/config/hardware, workload, percentis, recursos, profiles e readback/reconciliation. Documentação de profiler/load tool, PHP/FPM e dependencies são fontes. Sem ambiente isolado, exemplos ficam drafts. A banca não chama microbenchmark capacity, p50 SLO completo ou recycle prova de ausência de leak.",
  ],
  "Build, container e provenance": [
    "## Build, container e provenance\nEntrega começa num build reproduzível que transforma commit revisado, lock e toolchain identificada em artifact imutável. O baseline executa `composer install` a partir do lock, sem dev dependencies quando o produto não precisa delas, com scripts/plugins revisados, autoload otimizado e plataforma compatível. O mutante roda `composer update` no servidor ou monta source/vendor mutável. Tests, migrations, assets, config não secreta e manifestos necessários entram deliberadamente; caches, `.git`, auth, `.env`, dumps e fixtures sensíveis ficam fora. Artifact recebe digest, release ID, SBOM e provenance/attestation conforme plataforma. Reconstrução limpa compara conteúdo relevante e executa smoke no próprio artifact, não na árvore do desenvolvedor.",
    "### Container em estágios\nBuilder possui compilers/Composer e credenciais efêmeras; runtime contém apenas PHP/SAPI, extensões, config e artifact necessários. O baseline copia por lista fechada, roda como usuário sem privilégio, usa filesystem read-only com diretórios temporários explícitos e não deixa package manager/token no layer final. O mutante usa uma imagem gigante ou passa segredo por ARG, que permanece no histórico. Base é fixada por digest e recebe atualização controlada. Extensões são compiladas/instaladas com versões e bibliotecas compartilhadas registradas. Healthcheck não muta banco. Entrypoint não executa migrations concorrentes por réplica. Multi-arch recebe matriz real; um digest por plataforma compõe manifesto. Scan de imagem complementa, não substitui runtime gates.",
    "### Composer, autoload e assets\nBuild valida composer metadata/lock, platform requirements, audit conforme política, licenses e ausência de pacote abandonado sem decisão. `dump-autoload` otimizado/authoritative é produzido depois do conjunto final de arquivos. O baseline executa teste de resolução de handlers/jobs e procura classmap inconsistente. O mutante reutiliza vendor de outro PHP ou altera source após autoload. Frontend/assets, se houver, também possuem lock/toolchain/digest e manifest referenciado pelo PHP; não são baixados no boot. Generated config/container/preload é determinístico e não incorpora secret/path do builder. Migrations acompanham release. Um inventário associa package e extensão ao artifact implantado, permitindo responder advisory por versão real.",
    "### Provenance, SBOM e assinatura\nProvenance liga source revision, builder, materiais e comandos ao digest; assinatura/attestation ajudam verificar origem, mas não provam correção. O baseline protege identidade do pipeline, separa aprovação de publicação e registra timestamp. O mutante assina artifact criado em laptop comprometido ou confia em tag móvel. SBOM contém packages/extensões/base relevantes, formato/version e hash, sem credenciais. Gate de deploy verifica digest/attestation/policy antes de executar. Repositório de artifacts é imutável, retém versões de rollback e audita promoção entre ambientes. Revogação e key rotation são ensaiadas. Consumer ainda roda security/functional gates; assinatura válida de componente vulnerável continua vulnerável.",
    "### Config e secrets no runtime\nMesmo artifact atravessa ambientes; config não secreta e secrets entram por interfaces da plataforma no start/request apropriado. O baseline valida tudo em value objects, registra fingerprint sanitizado e falha readiness para combinação inválida. O mutante bakeia endpoint/password por ambiente na imagem. Secret mounts não são copiados para layer ou incluídos em crash dump. Rotação não exige rebuild quando contrato permite. PHP ini/FPM/proxy config fazem parte do release ou manifesto e são testados na SAPI real. Drift é detectado. Feature flags têm owner/expiry e defaults seguros. Debug/xdebug/phpinfo ficam ausentes ou impossíveis em produção. Teste busca canários no filesystem, history, manifest, logs e resposta.",
    "### Gates do artifact\nPipeline abre somente após lint/type/static/unit; depois constrói artifact e executa novamente smoke/integration/security contra ele. O baseline confirma usuário/permissões, writable paths, extensions, CA/timezone, release endpoint, autoload/preload, migrations parseadas e ausência de dev tools/secrets. O mutante testa source e publica imagem diferente. Vulnerability scan possui feed/timestamp e exceções formais. Tamanho/layers e startup são budgets. Um artifact sem executor adequado permanece Pending; não se instala infraestrutura apenas para redigir. Evidência é anexada ao digest. Promoção referencia exatamente esse digest e não reconstrói. Falha preserva logs redigidos e impede push/promotion.",
    "### Incidente, aceite e fontes\nToken Composer permaneceu num layer e produção recebeu vendor resolvido durante deploy; rollback não possuía artifact idêntico. O baseline usa builder isolado, lock, copy fechado, digest/provenance e storage imutável. Mutantes removem lock, incluem auth canário, executam como root e alteram source após dump; gates falham. Aceite registra commit, locks, base/extensões, comandos, SBOM, assinatura, scan e smoke do digest. Documentação Composer, PHP/container runtime e provenance format são fontes. Sem engine/builder real, exemplos ficam drafts. A banca não chama container isolamento total, SBOM scan ou assinatura prova de qualidade.",
  ],
  "Deploy, migrations e rollback": [
    "## Deploy, migrations e rollback\nDeploy promove artifact já aprovado por ambientes e altera tráfego de forma observável. O baseline separa release, migration, activation e verification; usa canary ou rollout gradual com thresholds de error, latency, saturation e invariantes. O mutante copia arquivos in-place e roda migration no primeiro request. Release ID/digest aparece em health/telemetry. Readiness só abre depois de config/runtime válidos; health não executa mutação. Uma implantação pode terminar tecnicamente e ainda falhar por dados/efeitos, logo smoke cria operação namespaced e faz state/effect readback. Gates e aprovação ficam ligados ao mesmo artifact. Rollout consegue pausar sem apagar evidência.",
    "### Expand-contract e frota mista\nFPM/drain e réplicas criam período old/new. O baseline adiciona coluna/tabela/índice de forma compatível, implanta leitores/escritores tolerantes, backfill resumível, muda preferência e somente depois contrai em release separado. O mutante renomeia/remove coluna no mesmo deploy. Defaults e NOT NULL em tabela grande recebem plano específico. Message/cache schemas também suportam janela; jobs antigos continuam. Tests executam old app/new schema e new app/intermediate schema com fixtures reais. Contract phase mede uso antes de remover. Feature flag pode coordenar, mas não corrige binários incompatíveis. Rollback de código permanece possível até o ponto declarado.",
    "### Migration runner e locks\nUma identidade controlada executa migrations uma vez, com DDL privilege separado da aplicação. O baseline adquire coordination lock, faz preflight de versão/espaço/lag, usa statement/lock timeout e registra migration/duração/outcome. O mutante deixa cada pod migrar no boot. DDL transactional varia por engine; rollback automático não é presumido. Index online/concurrent e constraint validation são testados na versão alvo. Backfill roda em batches keyset, checkpoint, throttle e sem callbacks do model atual. Falha para e inspeciona catálogo/estado antes de retry. Migration histórica é imutável; correção entra em nova. Readiness verifica schema mínimo, não dispara alteração.",
    "### Canary e verificação\nCanary recebe tráfego representativo/tenant seguro, não apenas health GET. O baseline compara success correto, unknown, DB locks/pool, queue age, provider effects, RSS e telemetry cardinality. Synthetic mutation usa identity/key própria e cleanup/reconciliation. O mutante olha somente 5xx. Thresholds e janela são predefinidos; promoção é gradual. Shadow traffic nunca duplica mutação real. Logs/traces ligam release. Verificação pós-migration consulta catalog/constraints/indexes e executa write/read. Um canary verde pequeno não elimina soak, mas limita blast radius. Se sinal é inconclusivo, pausa e preserva estado; não acelera para obter amostra.",
    "### Rollback e forward fix\nRollback troca para artifact anterior somente se schema/message/config/dados continuarem compatíveis. O baseline documenta ponto de não retorno e testa rollback antes do rollout. O mutante assume que imagem anterior sempre funciona. Data migration destrutiva exige backup/restore ou forward fix, não down migration fictícia. Feature flags podem desligar caminho novo mantendo formato dual. Workers/consumers também precisam rollback/drain; mensagens novas não podem poisonar versão antiga. Provider effects já realizados não são revertidos por código: compensação/reconciliation trata. Rollback preserva event/idempotency IDs. Depois de voltar, state audit confirma nenhuma obrigação perdida.",
    "### Operação e segurança\nDeploy identity tem least privilege e separação de duties conforme risco. Secrets não aparecem em arguments/logs. Artifact é verificado por digest no host. O baseline mantém audit de quem/o quê/quando, janela e reason. Emergency deploy ainda usa artifact/pipeline mínimo confiável, não edição SSH. Rate de rollout respeita capacity; novos workers não causam connection/startup storm. Runbook cobre pause, drain, rollback/forward, migration stuck e mixed release. Comunicação distingue mitigação de resolução. Métricas de deployment ligam change a SLO. Acesso break-glass expira e é revisado. Backup recente/restorable é precondition para operação arriscada.",
    "### Incidente, aceite e fontes\nColuna foi removida enquanto workers antigos ainda escreviam; migration concorrente bloqueou tabela e rollback binário não lia dados novos. O baseline usa expand-contract, runner único, canary e rollback compatível ensaiado. Mutantes contraem cedo, rodam migration por réplica e promovem apesar de state mismatch; gates falham. Aceite registra artifact, timeline old/new, catalog, migrations, canary, rollback e final state/effects. Documentação do banco, orquestrador, FPM e migration tool é fonte. Sem staging equivalente, exemplos ficam drafts. A banca não chama zero downtime por haver réplicas, migration success compatibilidade ou rollback de código rollback de efeitos.",
  ],
  "Shutdown, workers e recovery": [
    "## Shutdown, workers e recovery\nShutdown correto fecha admission, deixa unidades em andamento atingir fronteira segura e devolve trabalho não concluído ao protocolo durável. O baseline trata signals no processo/supervisor real, marca worker draining, para novos claims e aguarda até budget menor que grace period. O mutante captura signal e sai imediatamente ou continua claimando. Request FPM e queue worker possuem lifecycle diferentes. Transaction aberta é concluída/rollback conforme estado local; não se inicia efeito remoto no fim do prazo. Item claimed mantém lease que expira ou é liberado por compare-and-set. Stable IDs permitem redelivery. Testes enviam TERM em cada kill point e inspecionam DB/outbox/provider/queue depois do restart.",
    "### Signals e PHP\nSignal delivery e async handling dependem de CLI/SAPI/extensões/biblioteca. O baseline mantém handler mínimo que define flag/cancela token seguro; trabalho complexo ocorre no loop normal. O mutante faz I/O/commit dentro do signal handler. SIGKILL/OOM/power loss não executam handler/finally/shutdown, então correção nunca depende deles. `register_shutdown_function` pode registrar fatal e cleanup best-effort, mas memória/estado podem estar comprometidos. Exit codes orientam supervisor sem marcar poison como sucesso. Teste real valida TERM, timeout e KILL. Windows/container/orchestrator semantics são documentadas quando aplicáveis. Signal masking e child processes recebem ownership explícito.",
    "### Drain de HTTP e jobs\nLoad balancer remove readiness antes de terminar processo; connection keep-alive e requests longos cabem no grace. O baseline para workers de queue de reclamar, termina item curto ou abandona seguro antes do lease, flush telemetry bounded e fecha recursos. O mutante só dorme N segundos. Heartbeat/lease renewal para ao drenar; se deadline insuficiente, operação não inicia. Batch possui checkpoints. Detached task é proibida ou supervisionada/durável. Testes mantêm request/job em pontos conhecidos durante deploy e confirmam outcome ou redelivery idempotente. Métricas mostram draining, inflight e grace exceeded. Shutdown simultâneo da frota é escalonado.",
    "### Kill points e ambiguidades\nMatriz cobre antes/depois de begin, commit, outbox claim, provider send, response, receipt e ack. O baseline classifica estados: antes do commit pode retry; commit sem resposta exige readback; efeito sem receipt é Unknown e consulta provider; ack perdido gera duplicata idempotente. O mutante converte qualquer crash em retry imediato. Harness usa failpoint/process kill, conexão observadora e transcript. Cada restart mantém command/event ID. Reconciliation termina Unknown antes de novo efeito. Teste não depende de finally para simular kill. Resultado esperado pode ser conjunto temporário, mas converge a invariante terminal dentro de prazo. Evidência registra timeline e generation/fence.",
    "### Supervisor e restart storm\nSupervisor define restart policy, backoff, jitter, max attempts e health. O baseline distingue config/schema permanente de falha transitória; erro permanente não entra em loop agressivo. O mutante sempre reinicia instantaneamente e derruba DB/secret manager. Startup não migra nem faz warmup ilimitado. Readiness espera dependencies essenciais com budget global. Circuit/admission protege recovery. Crash loop alerta e preserva logs limitados. Worker poison pode ir DLQ sem matar toda frota. Testes negam config/DB e medem tentativas/backoff. Deployment garante capacity durante recycle. Release ruim é rollback, não restart eterno.",
    "### Recovery e reconciliation\nApós crash/outage, baseline reconcilia leases expirados, transactions, outbox Unknown, provider receipts, queue backlog e cache. Ordem protege source of truth e evita reenviar antes de saber. Scanner usa keyset/checkpoint/rate limit e audit. O mutante simplesmente republica tudo pending. Recovery pode degradar features e manter write admission fechado até invariantes essenciais. Metrics de divergence/oldest age orientam conclusão. Restore ou failover muda epoch/namespace quando necessário. Manual override requer reason e stable identity. Testes deixam resíduos em cada estado e executam reconciler duas vezes, provando idempotência. Backlog drain respeita provider/DB.",
    "### Incidente, aceite e fontes\nWorker recebeu TERM após provider aceitar e antes do receipt; restart criou nova key e duplicou efeito. Outro pool continuou claims durante drain. O baseline para admission, preserva IDs, classifica Unknown e reconcilia. Mutantes saem cedo, renovam lease após drain e repetem com nova identidade; kill tests falham. Aceite registra signals/grace, inflight, leases, DB, transcript, restart e convergência. Manuais PHP PCNTL/SAPI, supervisor/orquestrador, queue e provider são fontes. Sem executor de processo, exemplos ficam drafts. A banca não chama graceful handler proteção contra SIGKILL, restart recovery ou finally garantia de cleanup.",
  ],
  "Backup, restore e incidentes PHP": [
    "## Backup, restore e incidentes PHP\nBackup só existe quando restore periódico prova dados legíveis, completos e compatíveis com aplicação. O baseline define RPO/RTO, source stores, consistência, encryption, retention, access e owner. Banco, object store, secrets/config essenciais e manifests precisam relacionamento temporal. O mutante celebra job de backup sem restaurar. Snapshot/crash consistency e point-in-time recovery são entendidos por engine. Cópia fica isolada contra exclusão/ransomware e acesso é auditado. Teste restaura em ambiente segregado com identidade/rede bloqueando efeitos externos. Checksums/counts e invariantes de domínio verificam conteúdo, não apenas abertura do banco. PII/retention/deletion também valem no backup.",
    "### Restore seguro\nAmbiente restaurado começa com delivery, schedulers, webhooks, email e provider egress desligados. O baseline aplica versão de schema/app compatível, valida catálogo, IDs, tenant relations, capacity e outbox, então executa reconciliation em dry-run. O mutante sobe workers imediatamente e reenvia eventos antigos. Secrets de produção não são necessários para validação e nunca são restaurados em ambiente de teste. DNS/URLs/config apontam para sinks seguros. Clock e backup timestamp informam janela perdida. Cache/search/analytics são reconstruídos da fonte, não tratados como autoridade. O acesso de operadores é temporário e toda exportação é controlada.",
    "### Identidades e efeitos após restore\nRestore não pode regenerar reservation/event/idempotency IDs; provider pode já ter efeitos posteriores ao ponto recuperado. O baseline compara ledger/receipts externos por stable ID, marca Unknown e reconcilia antes de liberar dispatcher. O mutante considera banco restaurado verdade completa e reenvia pending. Epoch/fencing impede worker antigo ou região isolada continuar escrevendo após failover. DNS/traffic só muda depois de fencing. Teste simula backup anterior a receipt, efeito externo existente e outbox pending; resultado deve registrar receipt sem novo envio. Objetivos exatamente-once são substituídos por convergência comprovável.",
    "### Drill de RPO e RTO\nDrill mede desde declaração até serviço seguro, não somente tempo de import. O baseline registra detectar, provisionar, restaurar, migrar, validar, reconciliar, liberar e observar. RPO compara último dado recuperado e obrigações externas. O mutante pausa cronômetro quando banco abre. Cenários incluem corrupção lógica, região indisponível, secret/key loss e backup parcialmente inválido. Runbook é executável por pessoa diferente, com comandos/decisões revisados e nenhum segredo hardcoded. Falha do drill gera ação. Capacidade de restore inclui espaço/bandwidth. Evidência preserva manifest, hashes, versões e resultados redigidos. Frequência segue risco.",
    "### Incidente e forensics\nResposta separa contenção, preservação, erradicação, recuperação e aprendizado. O baseline registra timeline, release/config, audit, telemetry, DB/outbox/provider e decisões; clocks são correlacionados. O mutante reinicia/apaga logs antes de snapshot. Acesso a dumps e dados é mínimo. Rotação de credenciais considera sessões/tokens derivados. Feature flag/egress pause limita dano. Comunicação usa fatos e incerteza. Depois da recuperação, reconciliation prova obligations, monitoramento reforçado detecta recidiva e postmortem sem culpa atualiza tests/runbook. Evidência legal/regulatória segue processo. Não se publica stack/PII em ticket amplo.",
    "### Compatibilidade e retention\nBackups antigos podem exigir versão antiga do app/migration tool; baseline preserva artifact/toolchain ou plano de upgrade testado. Encryption keys têm backup/rotation/escrow controlado, pois backup sem chave é perda. Retenção equilibra RPO/audit/privacy e legal hold. Schema dump sozinho não restaura sequences, extensions, roles ou data. Object references são verificadas. Teste de restore percorre supported recovery window e atualiza quando contract muda. Delete requests propagam conforme política. Manifest associa backup a engine/version/schema/release e logs. Um restore que só funciona com conhecimento tribal não atende RTO.",
    "### Incidente, aceite e fontes\nRestore trouxe outbox anterior ao receipt e worker reenviou cobrança com ID novo; backup estava íntegro, recuperação não. O baseline isola egress, preserva IDs, compara provider e reconcilia antes de abrir. Mutantes habilitam worker, regeneram key e ignoram epoch; drill falha. Aceite registra RPO/RTO medidos, manifest/hashes, engine/schema/artifact, invariantes e transcript externo sem efeito duplicado. Documentação do banco/storage, plataforma e provider é fonte. Sem ambiente segregado, exemplos ficam drafts. A banca não chama backup recovery, import success restore validado ou rollback de banco reversão de efeitos externos.",
  ],
  "Arquitetura PHP do Quíron": [
    "## Arquitetura PHP do Quíron\nO projeto Quíron em PHP recebe `POST /v1/reservations`, autentica identidade/tenant, valida command, aplica policy, grava intenção/reserva/outbox numa transaction local e responde somente depois do outcome conhecido. O baseline separa HTTP adapter, application service, domain values, repository/transaction ports, PDO adapter, outbox dispatcher e provider client. O mutante coloca SQL, sessão e chamada remota no controller. Composition root liga implementações de produção sem fallback. `CreateReservationCommand` contém tenant confiável, actor, idempotency key, fingerprint version, show, quantity e operation ID; não transporta superglobals. Resultado fechado distingue Created, Replayed, Conflict, SoldOut, Forbidden e Unknown. Cada boundary possui error mapping e ownership explícito.",
    "### Fluxo HTTP e domínio\nMiddleware limita body, autentica sessão/token, resolve tenant autorizado e cria context. Router fechado chama handler, que decodifica DTO estrito e passa ao service. O baseline não confia em tenant do body nem converte exception genérica em 409. Service verifica policy e inicia transaction: insere intent ou lê winner por unique tenant/key, compara fingerprint, reserva capacity condicional, cria reservation/event e outbox. Nenhum provider ocorre dentro. Depois do commit, HTTP retorna 201 com receipt local; replay igual retorna resposta armazenada; divergente 409; sold out uniforme. Commit ambíguo vira readback/202 conforme contrato. Tests atravessam stack e conexão observadora.",
    "### Módulos e dependências\n`Domain` depende apenas de PHP/value abstractions; `Application` depende de ports; `Infrastructure` implementa PDO/HTTP/queue; `Entrypoints` traduz protocolos. O baseline usa namespaces/PSR-4, classes readonly/final onde útil e sem service locator. Repositories exigem tenant e transaction context; não oferecem `find($id)` global. Mapper valida row. Config tipada escolhe engine/provider. O mutante deixa Active Record/framework vazar para policy e job. Regra arquitetural e análise estática impedem imports. Contract suites rodam memory/real adapters, com limitations declaradas. Events do domínio são materializados em outbox na mesma unidade. Cache fica decorator contextual de read model, nunca fonte da reserva.",
    "### Dados e protocolos\nSchema possui PK/composite tenant relations, check capacity/quantity/status, unique intent `(tenant,key)`, fingerprint, reservation/event IDs e outbox state/fence. O baseline versiona payload/fingerprint e indexa queries reais. Provider recebe event ID como idempotency key e metadata mínima. Queue carrega event ID/type/version/tenant, não entidade serializada. Worker faz claim atomic, fencing, effect fora da claim transaction, receipt e reconciliation de Unknown. O mutante usa boolean sent e UUID por tentativa. Cache/search/analytics derivam depois. Retention preserva janela de replay/audit. Migrations expand-contract suportam frota mista. Backup/restore mantém identities.",
    "### Segurança e operação\nRuntime least privilege, SQL binds, contextual escaping, CSRF/cookies/CSP quando UI, egress allowlist/TLS e secrets externos compõem defense-in-depth. O baseline limita body/depth/list, FPM/pools/concurrency, jobs/retries e provider response. Telemetria correlaciona operation/event/release sem secret/PII ou labels ilimitadas. Artifact imutável traz lock/SBOM/digest. Canary mede estado/efeito. Shutdown para claims e preserva lease. Restore inicia sem egress e reconcilia. O mutante expõe phpinfo, desliga TLS ou usa tenant/path dinâmico. Threat model liga assets, boundaries, attacker e controls a gates reais. Admin/break-glass é porta separada/auditada.",
    "### Estrutura e execução local\nUma implementação de referência organiza `public/index.php`, `src/Domain`, `Application`, `Infrastructure`, `Entrypoint`, `config`, `migrations`, `tests` e scripts de build, sem efeitos em autoload. Ambiente local pode usar engine descartável e provider stub com transcript; o baseline não baixa serviço no boot. Comandos separados validam composer, static/unit, integration, mutation/security, artifact e load/kill/restore. Cada gate registra versões e alcance. `.env.example` não contém secret real. Fixtures namespaced suportam paralelismo. O projeto não é aprovado porque compila: precisa demonstrar HTTP, banco concorrente, worker, browser quando aplicável, deployment e recovery. Ausência de executor marca Pending.",
    "### Incidente, aceite e fontes\nController confirmou antes do commit, repository global vazou tenant e dispatcher criou novo ID após timeout. O baseline separa boundaries, usa transaction/outbox e identidade estável ponta a ponta. Mutantes removem auth/tenant, commit, unique, atomic update, fence e TLS; matriz deve detectá-los. Aceite inclui diagrama/dependency rules, production graph, requests, SQL/catalog, queue/provider transcript, telemetry, artifact e recovery. Todos os manuais primários citados nos capítulos anteriores formam as fontes. Sem PHP/engine/proxy/worker, os exemplos são draft. A banca não chama arquitetura em pastas isolamento, interface transaction ou outbox exatamente-once.",
  ],
  "Última vaga e replay PHP": [
    "## Última vaga e replay PHP\nO cenário começa com show capacity 1 e duas requisições concorrentes em conexões/processos distintos. Cada uma possui tenant e idempotency key; chaves diferentes disputam vaga, mesma key testa replay. O baseline usa `UPDATE ... SET available=available-:q WHERE tenant_id=:t AND id=:s AND available>=:q`, verifica affected row no engine alvo e insere reservation/outbox na mesma transaction. O mutante faz SELECT/check em PHP ou mutex local. Barreira determinística alinha as tentativas sem sleep. Terceira conexão confirma capacity zero, uma reservation e uma outbox. Winner/loser responses correspondem ao estado. Check constraint impede negativo mesmo por writer alternativo.",
    "### Intent e fingerprint\nAntes da disputa, unique `(tenant,idempotency_key)` escolhe um intent winner. Fingerprint canônico inclui versão e campos semânticos (show, quantity, channel), não timestamps/request ID. O baseline tenta insert; em unique específica lê winner scoped e compara em tempo constante quando relevante. Igual retorna outcome/IDs armazenados; divergente retorna conflict sem repetir. O mutante faz select-then-insert ou trata qualquer integrity error como replay. Tests cobrem simultâneo igual/divergente, cross-tenant, winner rollback e key retention. Canonicalization preserva tipos, Unicode/decimals conforme contrato e não depende de ordem de array instável.",
    "### Retry e commit desconhecido\nDeadlock/serialization retry repete toda a transaction com command/event IDs estáveis e sem efeito externo. Backoff bounded acontece fora da conexão. O baseline diferencia transient SQLSTATE por driver; validation/conflict não repete. Se conexão cai no commit, outcome é Unknown: nova conexão busca intent por tenant/key/fingerprint e retorna winner se visível; não decrementa novamente cegamente. O mutante gera reservation/event dentro da tentativa. Failpoint mata antes/depois de commit e confirma um estado. Deadline global limita tentativas. Logs contam attempt separado de operation. Unique e readback fecham ambiguidade durável.",
    "### Dispatch e efeito externo\nOutbox criada no commit é claimed por workers independentes com token/fence. Provider recebe event ID estável. Sucesso grava receipt condicional; timeout depois de envio fica Unknown e consulta provider por ID antes de retry. O baseline testa crash antes request, depois effect, depois receipt e antes ack. O mutante marca sent antes do provider ou cria nova key. Duas workers/lease expiry não produzem efeito lógico duplicado quando provider suporta idempotência; sem suporte, reconciliation e limitação honesta substituem garantia. Restore mantém event ID. A reserva já committed não desaparece se notification falhar; obrigação permanece visível.",
    "### Harness concorrente\nGate real provisiona schema/migrations, cria tenant/show namespaced e abre PDO connections independentes. Uma barreira externa ou locks coordenam start; cada process registra connection/operation. O baseline roda iterações, inverte ordem e testa duas réplicas/worker quando possível. Readback independente verifica rows, constraints e outbox; transcript conta provider. O mutante usa SQLite in-memory ou mesma connection e chama prova concorrente. Teste registra engine/version/isolation/config. Sem engine alvo, fica Pending. Cleanup ocorre depois de preservar falha. Mutation remove predicate `available>=` e unique/fence para provar força. Load complementa, não substitui, cenário determinístico.",
    "### Oráculos e métricas\nInvariantes: capacity nunca negativa; total vendido não excede inicial; um intent por tenant/key; fingerprint divergente nunca replay; uma reservation/event por sucesso; toda reservation committed possui outbox; effect/receipt converge uma vez logicamente. O baseline verifica após cada cenário e pós-recovery. Metrics distinguem created/replayed/conflict/sold_out/unknown, transaction retry, claim lost e reconciliation, com labels bounded. Trace fecha após commit e liga worker. O mutante só espera um 201. SLO inclui time-to-effect e oldest unknown. Alertas possuem runbook. Evidence matrix mapeia cada invariante ao gate/estado observador.",
    "### Incidente, aceite e fontes\nDuas réplicas fizeram read-check-write e venderam a última vaga; retry do winner usou novo event ID e duplicou provider. O baseline usa update condicional, unique fingerprint, IDs estáveis, outbox/fence e readback. Mutantes removem predicate/constraint/stability e devem falhar em two-session/kill/restore. Aceite registra comandos/IDs, SQLSTATE, connections/isolation, rows/outbox/transcript e convergência. Documentação PDO e engine/provider é fonte. Sem executor, exemplos ficam drafts. A banca não chama teste sequencial concorrência, HTTP único idempotência nem outbox exatamente-once.",
  ],
  "Segurança, testes e carga PHP": [
    "## Segurança, testes e carga PHP\nA banca combina threat model, pirâmide de testes e workload adversarial. Assets incluem identidade, reservas, capacity, secrets, provider receipts e availability. Boundaries abrangem proxy/HTTP, session/token, parser, SQL, cache, queue, worker, provider, filesystem e telemetry. O baseline associa ameaça a controle e prova: same-ID tenant, CSRF/browser, injection por sink, SSRF egress, secret canary, resource budgets e state/effect oracle. O mutante entrega checklist sem execução. Testes unitários cobrem values/policies; contracts adapters; integration stack/DB; browser headers/UI; concurrency/kill; load/soak; deploy/restore. Cada um declara reais e fakes.",
    "### Matriz negativa\nCasos incluem missing/invalid auth, body tenant diferente, resource homônimo, role revogada, duplicate headers, malformed/deep JSON, SQL/order payload, XSS contexts, CSRF, path/upload polyglot, private/redirect URL, token em logs e unknown outcome. O baseline espera status/error uniforme, nenhuma mudança de estado/efeito e telemetry redigida. O mutante verifica somente 4xx. Browser confirma ausência de script/request; DB confirma rows; egress server confirma nenhum destino proibido; canary scan cobre exporters/artifact. Corpus é versionado por sink e regressão. Fuzz gera bytes/shrinks com budgets. Static/taint e mutation complementam execução.",
    "### Carga e fairness\nWorkload mistura create/replay/read/cancel e workers, com tenants normal e ruidoso, keys válidas/divergentes, provider lento e DB contention. O baseline controla arrival rate, concurrency/inflight e registra p50/p95/p99, errors, pool wait, queue age, RSS e state/effects. O mutante usa loop fechado e celebra throughput. Admission/rate limits preservam fairness e health. Retry jitter evita storm. Capacity do DB/provider limita escala FPM. Soak alterna tenants/failures para revelar leak/context. Depois, readback/reconciliation exige capacidade, reservations, intents, outbox e receipts coerentes. Overload aceitável rejeita cedo; não perde commit.",
    "### Fault injection e mutation\nFailpoints cobrem DB disconnect/deadlock/commit lost, provider timeout before/after effect, broker ack loss, lease expiry, TERM/KILL, disk/temp full, collector down e config invalid. O baseline injeta em ambiente controlado com stable IDs. Mutantes removem rollback, tenant predicate, capacity guard, fingerprint comparison, fence, TLS verification, limits e cleanup; ao menos um gate apropriado precisa falhar por mutante crítico. O mutante real equivalente é justificado, não contado. Fault não se limita a exception fake quando protocolo real importa. Estado residual é preservado para diagnóstico e reconciler roda duas vezes. Segurança do experimento impede contato com produção.",
    "### Evidência e thresholds\nGate publica versão PHP/SAPI/extensions, artifact/config, engine/isolation, proxy/browser, broker/provider fake/sandbox e seed/workload. Thresholds editoriais, structural, similarity, static, mutation, performance e security são definidos antes e não reduzidos para aprovação. O baseline liga requisito → cenário → oracle → artifact. Skip por executor ausente é Pending e bloqueia editorial/publicação pertinente. Logs/traces são redigidos e correlacionados. Screenshots não substituem DOM/network. Coverage não substitui assertion. Flaky recebe owner e root cause. Reexecução isolada não apaga histórico. Evidence inclui comandos e digests reproduzíveis.",
    "### Resposta e capacidade operacional\nDurante teste ou incidente, operador consegue pausar delivery, reduzir admission, revogar token, drenar worker, reconciliar Unknown e restaurar artifact. O baseline ensaia runbooks sob carga e mede RTO. O mutante depende do autor da aplicação. Alerts usam SLO/saturation/divergence. Audit distingue ação humana/automática. Recovery preserva tenant/IDs. Postmortem converte descoberta em corpus/mutant/fault. Chaos não roda sem blast-radius e abort. Backup do ambiente de teste não contém secrets reais. A banca observa comportamento de equipe/sistema, não apenas código. Um sistema seguro mas impossível de operar não passa.",
    "### Incidente, aceite e fontes\nTeste de carga retornou rápido porque perdeu outbox; scanner verde não detectou tenant leak e log capturou token. O baseline exige oráculos cruzados, corpus contextual, canários e carga com readback. Mutantes funcionais/de segurança/recursos precisam morrer. Aceite agrega reports unit/contract/integration/static/mutation/fuzz/browser/concurrency/load/kill e incident drill, com escopo honesto. Fontes primárias são runtime/framework/engine/protocol/tools. Sem executores, a seção permanece draft. A banca não chama quantidade de testes qualidade, scanner prova de segurança ou latency sucesso sem obligations.",
  ],
  "Banca, deploy e restore PHP": [
    "## Banca, deploy e restore PHP\nA banca final não é apresentação: promove um artifact específico por pipeline, executa canary, provoca falhas, faz rollback compatível e restaura backup isolado sem duplicar efeitos. O baseline começa com evidence manifest: commit/digest, Composer lock/SBOM, PHP/SAPI/extensões, configs, DB schema, tests e riscos Pending. O mutante recompila entre gates ou demonstra checkout diferente. Production graph resolve adapters reais. Um request namespaced cria reserva/outbox; worker envia ao provider controlado; observer confirma receipt. Telemetria correlaciona tudo e não contém canários. Cada resultado tem artefato e responsável.",
    "### Sequência de deploy\nPipeline verifica assinatura/digest, aplica expand migration por runner único, inicia canary com egress/provider seguro, confirma readiness/release e executa smoke de write/read/effect. O baseline observa locks/pools/queue/SLO/state antes de aumentar tráfego. Mantém worker old/new compatível e drena antigo. O mutante migra por pod ou promove por health apenas. Uma falha planejada após commit prova readback; outra após provider prova Unknown/reconciliation. Canary ruim pausa e coleta evidência. Rollback usa artifact anterior sem contrair schema; operação namespaced continua legível. Depois, forward fix ou decisão é registrada.",
    "### Exercício de crash\nDurante última vaga, harness mata request antes/depois do commit e worker antes/depois do effect/receipt/ack. O baseline mantém command/event IDs e usa conexão independente/provider transcript para classificar. Ao reiniciar, supervisor/backoff evita storm, leases/fence impedem owner velho, e reconciler converge. O mutante depende de shutdown hook. TERM demonstra drain; KILL demonstra protocolo durável. Assertions contam capacity/reservations/intents/outbox/effects. Unknown não é forçado a success/failure sem evidência. Timeline liga process generation e release. O exercício repete após deploy misto para verificar compatibility.",
    "### Restore drill\nBackup escolhido possui manifest/hash/time/RPO. Ambiente segregado sobe com egress/consumers desativados, versão compatível e secrets sintéticos. O baseline restaura, valida catalog/constraints/IDs/tenants/invariants, compara provider receipts e executa reconciliation dry-run/aplicada. Caso central contém outbox pending no backup cujo effect ocorreu depois: reconciler encontra receipt por event ID e não reenvia. O mutante liga worker primeiro ou gera IDs novos. Epoch fence elimina writer antigo antes do traffic switch. RTO inclui provisionamento até serviço seguro. Após abrir gradualmente, monitora divergence/oldest unknown. Drill limpa dados com audit.",
    "### Matriz de aprovação\nEstrutural exige 12 capítulos, 48 seções, 96 exemplos, 36 exercícios e 48 cards; editorial exige prosa autoral densa, baixa similaridade e avaliações específicas. Toolchain exige PHP/Composer/static/unit; infra exige target DB, HTTP/proxy, worker/broker/provider, browser/TLS, load/kill/restore conforme claim. O baseline só recebe attestation/editorial e entra no seed quando todos gates obrigatórios passam; indisponível vira Pending, não aprovado. O mutante reduz threshold ou publica draft. Suite global, typecheck e build protegem integração. Plano/handoff/memória registram evidência e limitações. Revisão manual amostra claims contra testes, evitando métrica gamificada.",
    "### Defesa oral e diagnóstico\nCandidato explica por que prepared statement não autoriza tenant, transaction não abrange provider, outbox não é exactly-once, Fiber não torna PDO nonblocking, rollback não reverte effect e backup não é recovery. Recebe incidente com 201/rollback, timeout pós-effect, mixed release, lease perdida e restore antigo; deve escolher state readback, stable identity e reconciliation. O baseline usa evidência e admite alcance. O mutante responde com retry, lock local ou mais workers. Também justifica limites, config, privacy e sources. A banca altera um parâmetro/mutante e exige previsão/teste. Clareza operacional pesa tanto quanto sintaxe.",
    "### Encerramento e manutenção\nApós aprovação, conteúdo ganha editorial/attestation ligado aos gates e `runSeed` o publica na posição do rollout. CI mantém contract, examples verification, editorial, suite/typecheck/build; updates de PHP/Composer/engine reabrem matriz. Advisories e incidents alimentam corpus/cards/exercises. Métricas educacionais não alteram conteúdo técnico. O baseline conserva artifacts de evidência e expiração de attestation. Se executor some ou claim muda, status pode voltar a Pending. O mutante trata aprovação como eterna. Handoff declara próximos sources sem confundir draft completo com publicado. Nenhuma instalação de infraestrutura é feita apenas para produzir texto.",
    "### Incidente, aceite e fontes\nUma banca antiga aprovou lint e slides; no primeiro restore, workers reenviaram cobranças e artifact não correspondia ao testado. O baseline liga digest a gates, executa deploy/crash/restore e preserva stable IDs. Mutantes recompilam, abrem egress cedo, regeneram ID e reduzem gate; aprovação falha. Aceite final reúne manifestos/reports/transcripts/state e limitações zero-Pending para claims publicadas. Fontes são manuais e especificações versionadas do stack real. No host atual sem PHP, a apostila pode ficar materializada como draft completo, mas não publicada. A banca não transforma ausência de erro em prova de recovery.",
  ],
};
